                        placeholder="Buscar versículos..." 
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                     />
                   </div>
                </form>
             </div>

             {data && viewMode === 'reader' && (
               <div className="flex items-center gap-4 ml-4">
                  <div className="flex items-center space-x-2 border-r border-stone-200 pr-4">
                     <span className="text-xs font-bold text-stone-400 uppercase">Texto</span>
                     <button onClick={() => setFontSize(s => Math.max(14, s - 2))} className="text-stone-500 hover:text-bible-ink px-1 font-serif text-sm">A-</button>
                     <button onClick={() => setFontSize(s => Math.min(32, s + 2))} className="text-stone-500 hover:text-bible-ink px-1 font-serif text-lg">A+</button>
                  </div>
                  <div className="text-stone-400 text-sm italic whitespace-nowrap">
                      {data.metadata.estimated_date}
                  </div>
               </div>
             )}
         </div>

        <div id="bible-content-area" className="flex-1 overflow-y-auto bg-bible-paper p-4 lg:p-12 relative scroll-smooth">

          {viewMode === 'saved' && (
             <SavedContent 
               onNavigateToVerse={handleSelectVerse} 
               onDeleteItem={deleteStoredItem}
             />
          )}

          {viewMode === 'study' && (
            <StudyMode />
          )}

          {viewMode === 'mood' && (
             <div className="max-w-4xl mx-auto pt-4 lg:pt-8">
                {selectedMood ? (
                   <div className="animate-fade-in">
                      <div className="flex items-center gap-2 mb-6 border-b border-stone-200 pb-2">
                        <button 
                          onClick={() => {
                             setSelectedMood('');
                             setMoodResults([]);
                          }}
                          className="lg:hidden text-stone-500 hover:text-bible-gold"
                        >
                           <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                             <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" />
                           </svg>
                        </button>
                        <h3 className="text-xl font-bold text-bible-ink">
                           Versículos para: <span className="text-bible-accent">{selectedMood}</span>
                        </h3>
                      </div>

                      {loadingMood ? (
                         <div className="space-y-4">
                            <div className="h-32 bg-stone-200 rounded-xl animate-pulse"></div>
                            <div className="h-32 bg-stone-200 rounded-xl animate-pulse"></div>
                            <div className="h-32 bg-stone-200 rounded-xl animate-pulse"></div>
                         </div>
                      ) : (
                         <div className="space-y-6 pb-20">
                            {moodResults.map((item, idx) => (
                               <div key={idx} className="bg-white p-6 rounded-xl shadow-sm border border-stone-200 hover:shadow-md transition-shadow">
                                  <div className="flex items-start gap-4">
