                )}
             </div>
          )}

          {viewMode === 'reader' && (
            <div className="max-w-3xl mx-auto">
              {loadingState === LoadingState.IDLE && (
                 <div className="flex flex-col items-center justify-center h-full pt-20 text-center">
                    <div className="w-24 h-24 bg-bible-gold/10 rounded-full flex items-center justify-center mb-6">
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-12 h-12 text-bible-gold">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" />
                      </svg>
                    </div>
                    <h1 className="text-4xl font-display font-bold text-bible-ink mb-4">Bienvenido</h1>
                    <p className="text-stone-600 max-w-md mb-8">Selecciona un libro del menú para comenzar tu estudio con contexto histórico y teológico impulsado por IA.</p>

                    <div className="flex flex-col md:flex-row gap-4">
                       <button onClick={loadDevotional} className="px-6 py-3 rounded-full bg-bible-leather text-white hover:bg-bible-ink transition-colors font-bold text-sm shadow-md">
                         Ver Devocional Diario
                       </button>
                       <button onClick={() => setViewMode('study')} className="px-6 py-3 rounded-full bg-white border border-stone-200 text-bible-ink hover:border-bible-gold hover:text-bible-gold transition-colors font-bold text-sm shadow-sm">
                         Plan de Estudios
                       </button>
                    </div>
                 </div>
              )}

              {loadingState === LoadingState.LOADING && (
                <div className="space-y-8 animate-pulse">
                  <div className="h-12 bg-stone-200 rounded w-1/3 mx-auto"></div>
                  <div className="space-y-4 mt-12">
                    <div className="h-4 bg-stone-200 rounded w-full"></div>
                    <div className="h-4 bg-stone-200 rounded w-5/6"></div>
                    <div className="h-4 bg-stone-200 rounded w-full"></div>
                    <div className="h-4 bg-stone-200 rounded w-4/5"></div>
                  </div>
                </div>
              )}

              {loadingState === LoadingState.SUCCESS && data && (
                <div className="animate-fade-in pb-32 relative">
                  <div className="text-center mb-8">
                    <span className="text-bible-accent uppercase tracking-widest text-xs font-bold mb-2 block">Capítulo {data.metadata.chapter_number}</span>
                    <h1 className="text-4xl lg:text-5xl font-display font-bold text-bible-ink">{data.metadata.book_name}</h1>
                  </div>

                  <div className="mb-8 max-w-xl mx-auto sticky top-0 z-20 shadow-xl rounded-lg">
                    <TextAudioPlayer 
                       text={data.verses.map(v => v.text).join(' ')} 
                       title="Audio del Capítulo" 
                       className="border-none"
                       showText={false}
                       onBoundary={handleAudioProgress}
                    />
                  </div>

                  <div className="space-y-6">
                    {data.verses.map((verse) => {
                      const noteKey = getNoteKey(data.metadata.book_name, data.metadata.chapter_number, verse.number);
                      const highlightKey = getHighlightKey(data.metadata.book_name, data.metadata.chapter_number, verse.number);

                      const note = userNotes[noteKey];
                      const currentVerseHighlights = verseHighlights[highlightKey] || [];
                      const isEditing = editingNote === noteKey;

                      // Check if this verse is being read by global audio
                      const isAudioActive = audioActiveVerse === verse.number;

                      // Calculate local karaoke index if active
                      let activeCharIndexForVerse = null;
                      if (isAudioActive) {
                          // Find this verse's start offset
                          const offsetData = verseOffsets.find(v => v.verse === verse.number);
                          if (offsetData) {
                              // If global char is 505 and verse starts at 500, local index is 5
                              const localIndex = globalAudioCharIndex - offsetData.start;
                              if (localIndex >= 0 && localIndex <= (offsetData.end - offsetData.start)) {
                                  activeCharIndexForVerse = localIndex;
                              }
                          }
                      }

                      return (
                        <div 
                          id={`verse-${verse.number}`} 
                          key={verse.number} 
                          className={`relative group transition-all duration-500 rounded-lg p-2 -mx-2 ${isAudioActive ? 'bg-bible-gold/5 border-l-4 border-bible-gold pl-3' : 'border-l-4 border-transparent'}`} 
                          data-verse-number={verse.number}
                        >
                          {/* Sidebar Actions */}
                          <div className="absolute -left-8 lg:-left-12 top-2 flex flex-col items-end gap-1 w-10 z-10">
                             <span className={`text-xs font-bold font-sans select-none mb-1 transition-colors ${isAudioActive ? 'text-bible-gold scale-110' : 'text-bible-gold/60'}`}>{verse.number}</span>

                             <div className={`flex flex-col gap-1 transition-opacity duration-200 ${note ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                                <button 
                                  onClick={() => setEditingNote(isEditing ? null : noteKey)}
                                  className={`p-1.5 rounded-full transition-colors ${note ? 'text-yellow-600 bg-yellow-50' : 'text-stone-300 hover:text-bible-accent hover:bg-stone-100'}`}
                                  title="Añadir nota"
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" fill={note ? "currentColor" : "none"} viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4">
                                      <path strokeLinecap="round" strokeLinejoin="round" d="M16.862 4.487l1.687-1.688a1.875 1.875 0 112.652 2.652L10.582 16.07a4.5 4.5 0 01-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 011.13-1.897l8.932-8.931zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0115.75 21H5.25A2.25 2.25 0 013 18.75V8.25A2.25 2.25 0 015.25 6H10" />
                                    </svg>
                                </button>
                                <button
                                  onClick={() => handleCreateImage(verse.number, verse.text)}
                                  className="p-1.5 rounded-full text-stone-300 hover:text-pink-500 hover:bg-pink-50 transition-colors"
                                  title="Crear Imagen"
                                >
                                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4">
                                    <path strokeLinecap="round" strokeLinejoin="round" d="M2.25 15.75l5.159-5.159a2.25 2.25 0 013.182 0l5.159 5.159m-1.5-1.5l1.409-1.409a2.25 2.25 0 013.182 0l2.909 2.909m-18 3.75h16.5a1.5 1.5 0 001.5-1.5V6a1.5 1.5 0 00-1.5-1.5H3.75A1.5 1.5 0 002.25 6v12a1.5 1.5 0 001.5 1.5zm10.5-11.25h.008v.008h-.008V8.25zm.375 0a.375.375 0 11-.75 0 .375.375 0 01.75 0z" />
                                  </svg>
                                </button>
                                <button
                                  onClick={() => handleShowReferences(verse.number, verse.text)}
                                  className="p-1.5 rounded-full text-stone-300 hover:text-blue-500 hover:bg-blue-50 transition-colors"
                                  title="Ver Referencias Cruzadas"
                                >
                                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4">
                                    <path strokeLinecap="round" strokeLinejoin="round" d="M13.19 8.688a4.5 4.5 0 011.242 7.244l-4.5 4.5a4.5 4.5 0 01-6.364-6.364l1.757-1.757m13.35-.622l1.757-1.757a4.5 4.5 0 00-6.364-6.364l-4.5 4.5a4.5 4.5 0 001.242 7.244" />
                                  </svg>
                                </button>
                                <button
                                  onClick={() => handlePlayVerse(verse.number, verse.text)}
                                  className={`p-1.5 rounded-full transition-colors ${playingVerse === verse.number ? 'text-bible-gold bg-bible-gold/10' : 'text-stone-300 hover:text-green-500 hover:bg-green-50'}`}
                                  title="Escuchar Versículo"
                                >
                                   {playingVerse === verse.number ? (
                                      <div className="flex gap-0.5 items-end h-3 w-3 justify-center">
                                        <span className="w-0.5 bg-bible-gold animate-music-bar-1 h-2"></span>
                                        <span className="w-0.5 bg-bible-gold animate-music-bar-2 h-3"></span>
                                        <span className="w-0.5 bg-bible-gold animate-music-bar-3 h-1"></span>
                                      </div>
                                   ) : (
                                     <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4">
                                        <path strokeLinecap="round" strokeLinejoin="round" d="M19.114 5.636a9 9 0 010 12.728M16.463 8.288a5.25 5.25 0 010 7.424M6.75 8.25l4.72-4.72a.75.75 0 011.28.53v15.88a.75.75 0 01-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 012.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75z" />
                                      </svg>
                                   )}
                                </button>
                                {/* Verse Chat Button (Enriched Visibility) */}
                                <button
                                  onClick={() => handleChatAboutVerse(verse.number, verse.text)}
                                  className="p-1.5 rounded-full text-stone-300 hover:text-purple-500 hover:bg-purple-50 transition-colors flex items-center justify-center group/chat"
                                  title="Chat AI sobre este Versículo"
                                >
                                   <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4">
                                      <path strokeLinecap="round" strokeLinejoin="round" d="M7.5 8.25h9m-9 3H12m-9.75 1.51c0 1.6 1.123 2.994 2.707 3.227 1.129.166 2.27.293 3.423.379.35.026.67.21.865.501L12 21l2.755-4.133a1.14 1.14 0 01.865-.501 48.172 48.172 0 003.423-.379c1.584-.233 2.707-1.626 2.707-3.228V6.741c0-1.602-1.123-2.995-2.707-3.228A48.394 48.394 0 0012 3c-2.392 0-4.744.175-7.043.513C3.373 3.746 2.25 5.14 2.25 6.741v6.018z" />
                                    </svg>
                                    <span className="hidden group-hover/chat:block absolute right-8 bg-purple-600 text-white text-[10px] px-2 py-0.5 rounded whitespace-nowrap font-bold">Chat AI</span>
                                </button>
                             </div>
                          </div>

                          <div className="rounded-lg px-2">
                            <HighlightableVerse 
                              text={verse.text} 
                              highlights={currentVerseHighlights}
                              fontSize={fontSize}
                              lineHeight={lineHeight}
                              activeCharIndex={activeCharIndexForVerse} // Pass local Karaoke index
                            />
                          </div>

                          {isEditing && (
                            <NoteEditor 
                              initialNote={note || ''}
                              onSave={(content) => saveNote(data.metadata.book_name, data.metadata.chapter_number, verse.number, content)}
                              onCancel={() => setEditingNote(null)}
                              onDelete={() => deleteNote(data.metadata.book_name, data.metadata.chapter_number, verse.number)}
                            />
                          )}

                          {!isEditing && note && (
                            <div 
                              onClick={() => setEditingNote(noteKey)}
                              className="ml-4 lg:ml-8 mb-6 p-4 bg-yellow-50 rounded-lg border-l-4 border-yellow-400 cursor-pointer hover:bg-yellow-100 transition-colors"
                            >
                               <div className="flex items-center gap-2 mb-1 text-xs font-bold text-yellow-700 uppercase tracking-wider">
                                  <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3 h-3">
                                    <path fillRule="evenodd" d="M10 2c-1.716 0-3.408.106-5.07.31C3.806 2.45 3 3.414 3 4.517V17.25a.75.75 0 001.075.676L10 15.082l5.925 2.844A.75.75 0 0017 17.25V4.517c0-1.103-.806-2.068-1.93-2.207A41.403 41.403 0 0010 2z" clipRule="evenodd" />
                                  </svg>
                                  Tu Nota
                               </div>
                               <p className="font-handwriting text-stone-800 text-sm italic">{note}</p>
                            </div>
                          )}
                        </div>
                      );
                    })}
                  </div>

                  <div className="mt-12 pt-8 border-t border-stone-200">
                    <ChapterExplanation explanation={data.metadata.detailed_explanation} />
                  </div>

                  <div className="mt-8 flex justify-center">
                    <button 
                      onClick={() => handleSelectChapter(currentChapter + 1)}
                      className="px-8 py-3 bg-bible-leather text-white rounded-lg hover:bg-bible-ink transition-colors font-display"
                    >
                      Siguiente Capítulo
                    </button>
                  </div>

                  {/* Floating Tutor Button (Enhanced Visibility) */}
                  <div className="fixed bottom-6 right-6 z-30 animate-fade-in-up">
                     <button
                       onClick={() => {
                         setTutorTopic(`${data.metadata.book_name} Capítulo ${data.metadata.chapter_number}`);
                         setIsReaderTutorOpen(true);
                       }}
                       className="group flex items-center gap-2 px-6 py-4 bg-bible-ink text-white rounded-full shadow-2xl hover:bg-stone-800 hover:scale-105 transition-all border-2 border-bible-gold/50"
                     >
                       <span className="whitespace-nowrap text-sm font-bold">
                         ¿Dudas sobre el capítulo?
                       </span>
                       <div className="relative">
                          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-6 h-6 text-bible-gold">
                            <path d="M11.25 4.533A9.707 9.707 0 006 3.75c-2.389 0-4.575.683-6.406 1.858a.75.75 0 01-.437-.695V3.75a.75.75 0 01.75-.75h14.25a.75.75 0 01.75.75v.916c0 .124-.034.24-.094.34a9.712 9.712 0 00-3.563-.467z" />
                            <path fillRule="evenodd" d="M2.25 7.5a.75.75 0 01.75-.75h18a.75.75 0 01.75.75v.784a9.757 9.757 0 01-9.75 9.75A9.757 9.757 0 012.25 8.284V7.5zM9.994 17.585a.75.75 0 01.728.568A11.258 11.258 0 0012 21a11.258 11.258 0 001.278-2.847.75.75 0 011.456.368A12.76 12.76 0 0112 22.5c-1.25 0-2.436-.217-3.55-.615a.75.75 0 01.544-1.299z" clipRule="evenodd" />
                          </svg>
                          <span className="absolute -top-1 -right-1 flex h-3 w-3">
                            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-bible-gold opacity-75"></span>
                            <span className="relative inline-flex rounded-full h-3 w-3 bg-bible-gold"></span>
                          </span>
                       </div>
                     </button>
                  </div>
                </div>
              )}

              {loadingState === LoadingState.ERROR && (
                <div className="text-center p-12 text-red-500">
                  <p>Hubo un error al cargar el contenido sagrado. Por favor intenta de nuevo.</p>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      <ContextPanel 
        metadata={data ? data.metadata : null} 
        isOpen={isContextOpen} 
        onClose={() => setContextOpen(false)}
        isLoading={loadingState === LoadingState.LOADING}
      />

      <TheologyTutor 
        topic={tutorTopic}
        isOpen={isReaderTutorOpen}
        onClose={() => setIsReaderTutorOpen(false)}
      />

      {showRefsPanel && (
         <div className="fixed inset-y-0 right-0 lg:w-96 bg-white shadow-2xl z-50 animate-slide-in-right flex flex-col">
            <div className="p-4 bg-bible-ink text-white flex justify-between items-center">
               <h3 className="font-bold">Referencias Cruzadas</h3>
               <button onClick={() => setShowRefsPanel(false)} className="text-stone-300 hover:text-white">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6">
                   <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                 </svg>
               </button>
            </div>
            <div className="flex-1 overflow-y-auto p-4 bg-stone-50 space-y-4">
               {loadingRefs ? (
                 <div className="space-y-4">
                    {[1,2,3].map(i => <div key={i} className="h-24 bg-stone-200 rounded animate-pulse" />)}
                 </div>
               ) : (
                 crossRefs.map((ref, i) => (
                    <div key={i} className="bg-white p-4 rounded-lg shadow-sm border border-stone-200">
                       <h4 className="font-bold text-bible-accent mb-1">{ref.ref}</h4>
                       <p className="font-serif italic text-stone-700 mb-2">"{ref.text}"</p>
                       <p className="text-xs bg-stone-100 p-2 rounded text-stone-600">{ref.connection}</p>
                    </div>
                 ))
               )}
            </div>
         </div>
      )}
    </div>
  );
}

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { BIBLE_BOOKS, CATEGORY_LABELS, VERSE_COUNTS } from '../constants';
import { BibleBook } from '../types';

interface SidebarProps {
  currentBook: string;
  onSelectBook: (bookName: string) => void;
  onSelectChapter: (chapter: number) => void;
  onSelectVerse: (book: string, chapter: number, verse: number) => void;
  onNavigate: (view: 'reader' | 'plan' | 'devotional' | 'mood' | 'saved' | 'study') => void;
  isOpen: boolean;
  onClose: () => void;
  streak?: number;
  onInstallApp?: () => void;
  canInstall?: boolean;
}

type SidebarView = 'books' | 'chapters' | 'verses';

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentBook, onSelectBook, onSelectChapter, onSelectVerse, onNavigate, isOpen, onClose, streak = 0, onInstallApp, canInstall 
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [view, setView] = useState<SidebarView>('books');
  const [selectedChapter, setSelectedChapter] = useState<number | null>(null);

  // Sync internal view state with external props
  useEffect(() => {
    if (currentBook) {
      if (view === 'books') {
        setView('chapters');
      }
    } else {
      setView('books');
      setSelectedChapter(null);
    }
  }, [currentBook]);

  const groupedBooks = useMemo<Record<string, BibleBook[]>>(() => {
    const filtered = BIBLE_BOOKS.filter(b => 
      b.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const groups: Record<string, BibleBook[]> = {};
    filtered.forEach(book => {
      if (!groups[book.category]) groups[book.category] = [];
      groups[book.category].push(book);
    });
    return groups;
  }, [searchTerm]);

  const activeBookData = BIBLE_BOOKS.find(b => b.name === currentBook);

  const handleBookClick = (bookName: string) => {
    onSelectBook(bookName); // Updates parent state, effectively sets currentBook
    setView('chapters');
    setSelectedChapter(null);
    setSearchTerm('');
  };

  const handleChapterClick = (chapter: number) => {
    setSelectedChapter(chapter);
    setView('verses');
  };

  const handleVerseClick = (verse: number) => {
    if (activeBookData && selectedChapter) {
      onSelectVerse(activeBookData.name, selectedChapter, verse);
      if (window.innerWidth < 1024) onClose();
    }
  };

  const handleBack = () => {
    if (view === 'verses') {
      setView('chapters');
      setSelectedChapter(null);
    } else if (view === 'chapters') {
      setView('books');
      onSelectBook(''); // Clear selected book in parent
    }
  };

  const handleNavClick = (viewMode: 'reader' | 'plan' | 'devotional' | 'mood' | 'saved' | 'study') => {
    onNavigate(viewMode);
    if (window.innerWidth < 1024) onClose();
  };

  // Get verse count for selected chapter
  const verseCount = (activeBookData && selectedChapter) 
    ? (VERSE_COUNTS[activeBookData.name]?.[selectedChapter - 1] || 20) 
    : 0;

  return (
    <div className={`fixed inset-y-0 left-0 transform ${isOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 lg:static lg:w-80 bg-white border-r border-stone-200 z-40 transition-transform duration-300 ease-in-out flex flex-col h-full shadow-xl lg:shadow-none`}>
      <div className="p-6 border-b border-stone-100 bg-bible-paper">

        {/* Streak Counter Header */}
        <div className="flex items-center justify-between mb-4">
           {view === 'books' ? (
             <div className="flex items-center justify-between w-full">
               <h2 className="text-2xl font-display font-bold text-bible-ink">Biblioteca</h2>
               <div className="flex items-center gap-1 bg-orange-50 px-3 py-1 rounded-full border border-orange-100" title="Días seguidos leyendo">
                 <span className="text-lg">🔥</span>
                 <span className="text-sm font-bold text-orange-600">{streak}</span>
               </div>
             </div>
           ) : (
             <div className="flex items-center gap-2">
               <button 
                 onClick={handleBack}
                 className="p-1 rounded-full hover:bg-stone-200 text-stone-500"
               >
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                   <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" />
                 </svg>
               </button>
               <h2 className="text-lg font-display font-bold text-bible-ink truncate max-w-[180px]">
                 {view === 'chapters' ? activeBookData?.name : `${activeBookData?.name} ${selectedChapter}`}
               </h2>
             </div>
           )}
        </div>

        {/* Mobile Main Navigation Links (Visible always in sidebar) */}
        <div className="grid grid-cols-2 gap-2 mb-6">
           {canInstall && (
             <button onClick={onInstallApp} className="col-span-2 p-3 text-sm font-bold rounded bg-bible-leather text-white hover:bg-bible-ink transition-colors flex items-center justify-center gap-2 shadow-md animate-pulse mb-2 border border-bible-gold">
               <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                 <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75V16.5M12 12.75l-3.375-3.375M12 12.75l3.375-3.375M12 12.75V3" />
               </svg>
               Instalar App
             </button>
           )}
           <button onClick={() => handleNavClick('reader')} className="p-2 text-xs font-bold rounded bg-stone-100 hover:bg-bible-gold hover:text-white transition-colors text-stone-600">
             📖 Lectura
           </button>
           <button onClick={() => handleNavClick('plan')} className="p-2 text-xs font-bold rounded bg-stone-100 hover:bg-bible-gold hover:text-white transition-colors text-stone-600">
             📅 Planes Lectura
           </button>
           <button onClick={() => handleNavClick('devotional')} className="p-2 text-xs font-bold rounded bg-stone-100 hover:bg-bible-gold hover:text-white transition-colors text-stone-600">
             🙏 Devocional
           </button>
           <button onClick={() => handleNavClick('mood')} className="p-2 text-xs font-bold rounded bg-stone-100 hover:bg-bible-gold hover:text-white transition-colors text-stone-600">
             ❤️ Sentimientos
           </button>
           <button onClick={() => handleNavClick('study')} className="p-2 text-xs font-bold rounded bg-stone-100 hover:bg-bible-gold hover:text-white transition-colors text-stone-600 col-span-2">
             🎓 Estudios Bíblicos
           </button>
