  // Navigation & View Modes
  const [viewMode, setViewMode] = useState<'reader' | 'plan' | 'search' | 'devotional' | 'mood' | 'saved' | 'study'>('reader');

  // Plan Sub-mode
  const [planMode, setPlanMode] = useState<'chrono' | 'time'>('chrono');

  // Scrolling
  const [scrollToVerse, setScrollToVerse] = useState<number | null>(null);

  // Chronological Plan
  const [chronoPlan, setChronoPlan] = useState<ReadingPlanItem[]>([]);
  const [loadingPlan, setLoadingPlan] = useState(false);

  // Daily Devotional
  const [devotional, setDevotional] = useState<DailyDevotional | null>(null);
  const [loadingDevotional, setLoadingDevotional] = useState(false);

  // Moods
  const [moodResults, setMoodResults] = useState<MoodResult[]>([]);
  const [loadingMood, setLoadingMood] = useState(false);
  const [selectedMood, setSelectedMood] = useState<string>('');

  // Search
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);

  // Notes
  const [userNotes, setUserNotes] = useState<Record<string, string>>({});
  const [editingNote, setEditingNote] = useState<string | null>(null); 

  // Highlights (Partial Text)
  const [verseHighlights, setVerseHighlights] = useState<Record<string, Highlight[]>>({});
  const [selectionMenu, setSelectionMenu] = useState<SelectionMenuPosition | null>(null);

  // Settings
  const [fontSize, setFontSize] = useState<number>(18); 
  const [lineHeight, setLineHeight] = useState<number>(1.625); 

  // Social & Cross Refs
  const [isImageCreatorOpen, setImageCreatorOpen] = useState(false);
  const [selectedVerseForAction, setSelectedVerseForAction] = useState<{number: number, text: string} | null>(null);
  const [crossRefs, setCrossRefs] = useState<CrossReference[]>([]);
  const [loadingRefs, setLoadingRefs] = useState(false);
  const [showRefsPanel, setShowRefsPanel] = useState(false);

  // Reader Tutor
  const [isReaderTutorOpen, setIsReaderTutorOpen] = useState(false);
  const [tutorTopic, setTutorTopic] = useState<string>('');

  // Audio State
  const [playingVerse, setPlayingVerse] = useState<number | null>(null);
  const [audioActiveVerse, setAudioActiveVerse] = useState<number | null>(null);
  const [globalAudioCharIndex, setGlobalAudioCharIndex] = useState<number>(0);

  // Streak State
  const [streakDays, setStreakDays] = useState(0);

  // PWA Install State
  const [installPrompt, setInstallPrompt] = useState<any>(null);
  const [isStandalone, setIsStandalone] = useState(false);

  useEffect(() => {
    // Detect if app is already installed
    if (window.matchMedia('(display-mode: standalone)').matches || (window.navigator as any).standalone) {
      setIsStandalone(true);
    }

    const handler = (e: any) => {
      e.preventDefault();
      setInstallPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  const handleInstallClick = () => {
    if (!installPrompt) {
      alert("Para instalar en iPhone: Toca el botón compartir y selecciona 'Añadir a pantalla de inicio'.");
      return;
    }
    installPrompt.prompt();
    installPrompt.userChoice.then((choiceResult: any) => {
      if (choiceResult.outcome === 'accepted') {
        setInstallPrompt(null);
      }
    });
  };

  // Calculate verse offsets for main audio sync
  const verseOffsets = useMemo(() => {
    if (!data) return [];
    let currentOffset = 0;
    return data.verses.map(v => {
        const start = currentOffset;
        const length = v.text.length;
        currentOffset += length + 1; // +1 for the space joining
        return { verse: v.number, start, end: start + length };
    });
  }, [data]);

  const handleAudioProgress = (charIndex: number) => {
     setGlobalAudioCharIndex(charIndex); // Track exact character index for karaoke

     if (!verseOffsets.length) return;
     const match = verseOffsets.find(v => charIndex >= v.start && charIndex <= v.end);

     if (match && match.verse !== audioActiveVerse) {
        setAudioActiveVerse(match.verse);
        // Auto scroll
        const el = document.getElementById(`verse-${match.verse}`);
        if (el) {
           el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
     }
  };

  // Load Data from LocalStorage on mount
  const loadStoredData = () => {
    const loadedNotes: Record<string, string> = {};
    const loadedHighlights: Record<string, Highlight[]> = {};

    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key) {
        if (key.startsWith('note-')) {
          loadedNotes[key] = localStorage.getItem(key) || '';
        } else if (key.startsWith('highlights-v2-')) {
          try {
            const parsed = JSON.parse(localStorage.getItem(key) || '[]');
            loadedHighlights[key] = parsed;
          } catch (e) {
            console.error("Error parsing highlight", e);
          }
        }
      }
    }
    setUserNotes(loadedNotes);
    setVerseHighlights(loadedHighlights);
  };

  // Handle Streak Logic
  useEffect(() => {
    const checkStreak = () => {
      const lastVisitStr = localStorage.getItem('lastVisitDate');
      const currentStreakStr = localStorage.getItem('currentStreak');
      const today = new Date().toDateString();

      let streak = currentStreakStr ? parseInt(currentStreakStr) : 0;

      if (lastVisitStr !== today) {
        // User hasn't visited today yet
        if (lastVisitStr) {
           const lastVisit = new Date(lastVisitStr);
           const yesterday = new Date();
           yesterday.setDate(yesterday.getDate() - 1);

           if (lastVisit.toDateString() === yesterday.toDateString()) {
             // Continued streak
             streak += 1;
           } else {
             // Broken streak
             streak = 1;
           }
        } else {
           // First time ever
           streak = 1;
        }
        localStorage.setItem('lastVisitDate', today);
        localStorage.setItem('currentStreak', streak.toString());
      }
      setStreakDays(streak);
    };

    checkStreak();
    loadStoredData();
  }, []);

  // Effect to handle scrolling to verse after data loads
  useEffect(() => {
    if (loadingState === LoadingState.SUCCESS && data && scrollToVerse) {
      setTimeout(() => {
        const element = document.getElementById(`verse-${scrollToVerse}`);
        if (element) {
          element.scrollIntoView({ behavior: 'smooth', block: 'center' });
          element.classList.add('bg-bible-gold/20', 'transition-colors', 'duration-1000');
          setTimeout(() => {
            element.classList.remove('bg-bible-gold/20');
          }, 1500);
        }
        setScrollToVerse(null); // Reset
      }, 300);
    }
  }, [loadingState, data, scrollToVerse]);

  // Handle Text Selection
  useEffect(() => {
    const handleSelection = () => {
      const selection = window.getSelection();

      if (!selection || selection.isCollapsed || selection.rangeCount === 0) {
        return;
      }

      const range = selection.getRangeAt(0);
      const container = range.commonAncestorContainer;

      let verseElement: HTMLElement | null = null;
      if (container.nodeType === Node.TEXT_NODE) {
        verseElement = container.parentElement?.closest('[data-verse-number]') as HTMLElement;
      } else {
        verseElement = (container as Element).closest('[data-verse-number]') as HTMLElement;
      }

      if (verseElement) {
        const verseNum = parseInt(verseElement.getAttribute('data-verse-number') || '0', 10);
        const rect = range.getBoundingClientRect();

        setSelectionMenu({
          top: rect.top + window.scrollY - 50, 
          left: rect.left + (rect.width / 2) - 80, 
          verseNumber: verseNum,
          range: range.cloneRange()
        });
      } else {
         setSelectionMenu(null);
      }
    };

    const container = document.getElementById('bible-content-area');
    if (container) {
      container.addEventListener('mouseup', handleSelection);
      container.addEventListener('touchend', handleSelection);
      container.addEventListener('keyup', handleSelection);
    }

    return () => {
       if (container) {
        container.removeEventListener('mouseup', handleSelection);
        container.removeEventListener('touchend', handleSelection);
        container.removeEventListener('keyup', handleSelection);
       }
    };
  }, [data]);

  const handleGlobalClick = (e: React.MouseEvent) => {
     const target = e.target as HTMLElement;
     if (target.closest('#highlight-menu')) return;

     const selection = window.getSelection();
     if (!selection || selection.isCollapsed) {
        setSelectionMenu(null);
     }
  };

  const addHighlight = (color: string) => {
    if (!selectionMenu || !data) return;

    const { verseNumber, range } = selectionMenu;
    const verse = data.verses.find(v => v.number === verseNumber);
    if (!verse) return;

    const selectedText = range.toString();
    const verseEl = document.querySelector(`[data-verse-number="${verseNumber}"]`);
    if (!verseEl) return;

    const preCaretRange = range.cloneRange();
    preCaretRange.selectNodeContents(verseEl);
    preCaretRange.setEnd(range.startContainer, range.startOffset);
    const start = preCaretRange.toString().length;
    const end = start + selectedText.length;

    const newHighlight: Highlight = {
      id: Date.now().toString(),
      start,
      end,
      color,
      text: selectedText
    };

    const key = getHighlightKey(data.metadata.book_name, data.metadata.chapter_number, verseNumber);
    const currentHighlights = verseHighlights[key] || [];
    const updatedHighlights = [...currentHighlights, newHighlight];

    setVerseHighlights(prev => ({ ...prev, [key]: updatedHighlights }));
    localStorage.setItem(key, JSON.stringify(updatedHighlights));

    setSelectionMenu(null);
    window.getSelection()?.removeAllRanges();
  };

  const removeVerseHighlights = (verseNumber: number) => {
     if (!data) return;
     const key = getHighlightKey(data.metadata.book_name, data.metadata.chapter_number, verseNumber);
     setVerseHighlights(prev => ({ ...prev, [key]: [] }));
     localStorage.removeItem(key);
     setSelectionMenu(null);
     window.getSelection()?.removeAllRanges();
  };

  const deleteStoredItem = (key: string) => {
    localStorage.removeItem(key);
    loadStoredData(); 
  };

  const fetchChapter = async (book: string, chapter: number) => {
    setLoadingState(LoadingState.LOADING);
    setData(null);
    setAudioActiveVerse(null);
    setGlobalAudioCharIndex(0);
    setShowRefsPanel(false); 
    setIsReaderTutorOpen(false); 
    try {
      const result = await getBibleChapter(book, chapter);
      setData(result);
      setLoadingState(LoadingState.SUCCESS);
      setTutorTopic(`${result.metadata.book_name} Capítulo ${result.metadata.chapter_number}`);
      if (window.innerWidth >= 1024) {
        setContextOpen(true);
      }
    } catch (error) {
      console.error(error);
      setLoadingState(LoadingState.ERROR);
    }
  };

  const handleSelectBook = (book: string) => {
    setCurrentBook(book);
    setCurrentChapter(1); 
  };

  const handleSelectChapter = (chapter: number) => {
    setCurrentChapter(chapter);
    fetchChapter(currentBook, chapter);
    setSidebarOpen(false); 
    setViewMode('reader');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSelectVerse = (book: string, chapter: number, verse: number) => {
    if (currentBook === book && currentChapter === chapter && data) {
       setScrollToVerse(verse);
       setSidebarOpen(false);
       setViewMode('reader');
    } else {
       setCurrentBook(book);
       setCurrentChapter(chapter);
       setScrollToVerse(verse);
       fetchChapter(book, chapter);
       setSidebarOpen(false);
       setViewMode('reader');
    }
  };

  const handleGoHome = () => {
    setData(null);
    setLoadingState(LoadingState.IDLE);
    setViewMode('reader');
    setCurrentBook('');
    setCurrentChapter(1);
    setSearchQuery('');
    setSidebarOpen(false);
    if (window.innerWidth < 1024) setContextOpen(false);
  };

  const handleBack = () => {
    if (viewMode === 'mood' && selectedMood) {
        setSelectedMood('');
        setMoodResults([]);
        return;
    }
    if (viewMode === 'search') {
        handleGoHome();
        return;
    }
    handleGoHome();
  };

  const handleNavigate = (mode: 'reader' | 'plan' | 'devotional' | 'mood' | 'saved' | 'study') => {
    if (mode === 'reader') {
        handleGoHome();
    } else if (mode === 'plan') {
        loadChronologicalPlan();
    } else if (mode === 'devotional') {
        loadDevotional();
    } else if (mode === 'mood') {
        loadMoodSelector();
    } else if (mode === 'saved') {
        loadSavedContent();
    } else if (mode === 'study') {
        setViewMode('study');
        setSidebarOpen(false);
    }
  };

  const loadSavedContent = () => {
    setViewMode('saved');
    setSidebarOpen(false);
    loadStoredData(); 
  }

  const loadChronologicalPlan = async () => {
    setViewMode('plan');
    setSidebarOpen(false);
    if (chronoPlan.length === 0) {
      setLoadingPlan(true);
      try {
        const plan = await getChronologicalPlan();
        setChronoPlan(plan);
      } catch (e) {
        console.error("Failed to load plan");
      } finally {
        setLoadingPlan(false);
      }
    }
  }

  const loadDevotional = async () => {
    setViewMode('devotional');
    setSidebarOpen(false);
    if (!devotional) {
      setLoadingDevotional(true);
      try {
        const result = await getDailyDevotional();
        setDevotional(result);
      } catch (e) {
        console.error("Failed to load devotional");
      } finally {
        setLoadingDevotional(false);
      }
    }
  };

  const loadMoodSelector = () => {
    setViewMode('mood');
    setSidebarOpen(false);
    setSelectedMood('');
    setMoodResults([]);
  }

  const handleMoodSelect = async (mood: string) => {
    setSelectedMood(mood);
    setLoadingMood(true);
    setMoodResults([]);
    try {
        const results = await getVersesByMood(mood);
        setMoodResults(results);
    } catch (e) {
        console.error("Failed to load mood verses");
    } finally {
        setLoadingMood(false);
    }
  }

  const handleSearch = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!searchQuery.trim()) return;

    setViewMode('search');
    setSidebarOpen(false);
    setIsSearching(true);
    setSearchResults([]);

    try {
      const results = await searchBible(searchQuery);
      setSearchResults(results);
    } catch (error) {
      console.error("Search failed", error);
    } finally {
      setIsSearching(false);
    }
  };

  const saveNote = (book: string, chapter: number, verse: number, noteContent: string) => {
    const key = getNoteKey(book, chapter, verse);
    if (!noteContent.trim()) {
      deleteNote(book, chapter, verse);
      return;
    }
    localStorage.setItem(key, noteContent);
    setUserNotes(prev => ({ ...prev, [key]: noteContent }));
    setEditingNote(null);
  };

  const deleteNote = (book: string, chapter: number, verse: number) => {
    const key = getNoteKey(book, chapter, verse);
    localStorage.removeItem(key);
    const newNotes = { ...userNotes };
    delete newNotes[key];
    setUserNotes(newNotes);
    setEditingNote(null);
  };

  const handleCreateImage = (verseNumber: number, verseText: string) => {
    if (!data) return;
    const ref = `${data.metadata.book_name} ${data.metadata.chapter_number}:${verseNumber}`;
    setSelectedVerseForAction({ number: verseNumber, text: verseText });
    setImageCreatorOpen(true);
  };

  const handleShowReferences = async (verseNumber: number, verseText: string) => {
    if (!data) return;
    const ref = `${data.metadata.book_name} ${data.metadata.chapter_number}:${verseNumber}`;
    setShowRefsPanel(true);
    setLoadingRefs(true);
    setCrossRefs([]);
    try {
      const refs = await getCrossReferences(ref, verseText);
      setCrossRefs(refs);
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingRefs(false);
    }
  }

  const handlePlayVerse = (verseNumber: number, text: string) => {
    window.speechSynthesis.cancel();
    setAudioActiveVerse(null); 
    setGlobalAudioCharIndex(0);

    if (playingVerse === verseNumber) {
      setPlayingVerse(null);
      return;
    }

    setPlayingVerse(verseNumber);
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'es-ES';
    const voices = window.speechSynthesis.getVoices().filter(v => v.lang.startsWith('es'));
    if (voices.length > 0) utterance.voice = voices[0];

    utterance.onend = () => setPlayingVerse(null);
    window.speechSynthesis.speak(utterance);
  }

  const handleChatAboutVerse = (verseNumber: number, text: string) => {
    if (!data) return;
    const context = `${data.metadata.book_name} ${data.metadata.chapter_number}:${verseNumber} - "${text}"`;
    setTutorTopic(context);
    setIsReaderTutorOpen(true);
  }

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth >= 1024) {
        setSidebarOpen(true);
        setContextOpen(true);
      } else {
        setSidebarOpen(false);
        setContextOpen(false);
      }
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const highlightColors = [
    { name: 'yellow', class: 'bg-yellow-400' },
    { name: 'green', class: 'bg-green-400' },
    { name: 'blue', class: 'bg-blue-400' },
    { name: 'pink', class: 'bg-pink-400' },
