          className="fixed z-50 bg-white rounded-full shadow-xl border border-stone-200 p-2 flex gap-2 animate-fade-in"
          style={{ top: selectionMenu.top, left: selectionMenu.left }}
        >
          {highlightColors.map(c => (
            <button
              key={c.name}
              onMouseDown={(e) => {
                e.preventDefault(); 
                addHighlight(c.name);
