                        </h3>
                      </div>

                      {loadingMood ? (
                         <div className="space-y-4">
                            <div className="h-32 bg-stone-200 rounded-xl animate-pulse"></div>
                            <div className="h-32 bg-stone-200 rounded-xl animate-pulse"></div>
                            <div className="h-32 bg-stone-200 rounded-xl animate-pulse"></div>
                         </div>
                      ) : (
                         <div className="space-y-6 pb-20">
                            {moodResults.map((item, idx) => (
                               <div key={idx} className="bg-white p-6 rounded-xl shadow-sm border border-stone-200 hover:shadow-md transition-shadow">
                                  <div className="flex items-start gap-4">
                                     <div className="p-3 bg-bible-gold/10 rounded-full text-bible-gold hidden sm:block">
                                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
                                          <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" />
                                        </svg>
                                     </div>
                                     <div className="flex-1">
                                        <h4 className="text-lg font-bold text-bible-leather mb-1">{item.verseReference}</h4>
