      {isImageCreatorOpen && selectedVerseForAction && data && (
         <ShareableImage 
           verseText={selectedVerseForAction.text}
           verseReference={`${data.metadata.book_name} ${data.metadata.chapter_number}:${selectedVerseForAction.number}`}
           onClose={() => setImageCreatorOpen(false)}
