            {showBackButton ? (
              <button onClick={handleBack} className="p-2 text-bible-leather flex items-center gap-1 bg-stone-100 rounded-full pr-3">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" />
                </svg>
                <span className="text-xs font-bold">Volver</span>
              </button>
            ) : (
              <button onClick={() => setSidebarOpen(true)} className="p-2 text-bible-leather">
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" />
                </svg>
              </button>
            )}
          </div>

           <form onSubmit={handleSearch} className="flex-1 mx-2">
             <div className="relative">
                <input 
                  type="text" 
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Buscar..."
                  className="w-full bg-stone-100 border-none rounded-full py-1.5 px-4 text-sm focus:ring-1 focus:ring-bible-gold outline-none"
                />
             </div>
           </form>

          <button onClick={() => setContextOpen(true)} className={`p-2 ${['plan', 'search', 'devotional', 'mood', 'saved', 'study'].includes(viewMode) ? 'invisible' : 'text-bible-gold'}`}>
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 18v-5.25m0 0a6.001 6.001 0 00-5.304-7.618 6.002 6.002 0 019.957 5.304c.42 2.15-1.65 4.314-4.653 2.314zm0 0l-7.05 4.633a1.125 1.125 0 01-1.373-1.634l-.75-7.5M12 18l7.05 4.633a1.125 1.125 0 001.373-1.634l-.75-7.5" />
            </svg>
          </button>
        </header>

         <div className="hidden lg:flex items-center justify-between px-8 py-4 bg-white border-b border-stone-200">
             <div className="flex gap-4 items-center flex-1 overflow-x-auto pb-2 lg:pb-0">
                {showBackButton ? (
                   <button 
                     onClick={handleBack}
                     className="px-4 py-2 rounded-full text-sm font-bold transition-all text-stone-500 hover:bg-stone-100 hover:text-bible-ink flex items-center gap-2 border border-transparent hover:border-stone-200"
                  >
                     <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" />
                     </svg>
                     Volver
                  </button>
                ) : (
                  <button 
                     onClick={handleGoHome}
                     className="px-4 py-2 rounded-full text-sm font-bold transition-all text-stone-500 hover:bg-stone-100 hover:text-bible-ink flex items-center gap-2"
                  >
                     <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M2.25 12l8.954-8.955c.44-.439 1.152-.439 1.591 0L21.75 12M4.5 9.75v10.125c0 .621.504 1.125 1.125 1.125H9.75v-4.875c0-.621.504-1.125 1.125-1.125h2.25c.621 0 1.125.504 1.125 1.125V21h4.125c.621 0 1.125-.504 1.125-1.125V9.75M8.25 21h8.25" />
                     </svg>
                     Inicio
                  </button>
                )}

                <button 
                  onClick={() => setViewMode('reader')}
                  className={`px-4 py-2 rounded-full text-sm font-bold transition-all whitespace-nowrap ${viewMode === 'reader' && loadingState !== LoadingState.IDLE ? 'bg-bible-leather text-white' : 'text-stone-500 hover:bg-stone-100'}`}
                >
                  Biblia
                </button>
                <button 
                   onClick={loadChronologicalPlan}
                   className={`px-4 py-2 rounded-full text-sm font-bold transition-all whitespace-nowrap ${viewMode === 'plan' ? 'bg-bible-leather text-white' : 'text-stone-500 hover:bg-stone-100'}`}
                >
                  Planes de Lectura
                </button>
                <button 
                   onClick={loadDevotional}
                   className={`px-4 py-2 rounded-full text-sm font-bold transition-all whitespace-nowrap ${viewMode === 'devotional' ? 'bg-bible-leather text-white' : 'text-stone-500 hover:bg-stone-100'}`}
                >
                  Devocional Diario
                </button>
                <button 
                   onClick={loadMoodSelector}
                   className={`px-4 py-2 rounded-full text-sm font-bold transition-all whitespace-nowrap ${viewMode === 'mood' ? 'bg-bible-leather text-white' : 'text-stone-500 hover:bg-stone-100'}`}
                >
                  Sentimientos
                </button>
                 <button 
                   onClick={() => setViewMode('study')}
                   className={`px-4 py-2 rounded-full text-sm font-bold transition-all whitespace-nowrap ${viewMode === 'study' ? 'bg-bible-leather text-white' : 'text-stone-500 hover:bg-stone-100'}`}
                >
                  Estudios
                </button>

                <form onSubmit={handleSearch} className="ml-4 relative flex-1 min-w-[200px] max-w-md hidden xl:block">
                   <div className="relative group">
                     <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                        <svg className="w-4 h-4 text-stone-400 group-focus-within:text-bible-gold" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 20 20">
                            <path stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="m19 19-4-4m0-7A7 7 0 1 1 1 8a7 7 0 0 1 14 0Z"/>
                        </svg>
                     </div>
                     <input 
                        type="search" 
                        className="block w-full p-2 pl-10 text-sm text-stone-900 border border-stone-200 rounded-full bg-stone-50 focus:ring-bible-gold focus:border-bible-gold outline-none transition-all" 
                        placeholder="Buscar versículos..." 
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                     />
                   </div>
                </form>
             </div>

             {data && viewMode === 'reader' && (
               <div className="flex items-center gap-4 ml-4">
                  <div className="flex items-center space-x-2 border-r border-stone-200 pr-4">
                     <span className="text-xs font-bold text-stone-400 uppercase">Texto</span>
                     <button onClick={() => setFontSize(s => Math.max(14, s - 2))} className="text-stone-500 hover:text-bible-ink px-1 font-serif text-sm">A-</button>
                     <button onClick={() => setFontSize(s => Math.min(32, s + 2))} className="text-stone-500 hover:text-bible-ink px-1 font-serif text-lg">A+</button>
                  </div>
                  <div className="text-stone-400 text-sm italic whitespace-nowrap">
                      {data.metadata.estimated_date}
                  </div>
               </div>
             )}
         </div>

        <div id="bible-content-area" className="flex-1 overflow-y-auto bg-bible-paper p-4 lg:p-12 relative scroll-smooth">

          {viewMode === 'saved' && (
             <SavedContent 
               onNavigateToVerse={handleSelectVerse} 
               onDeleteItem={deleteStoredItem}
             />
          )}

          {viewMode === 'study' && (
            <StudyMode />
          )}

          {viewMode === 'mood' && (
             <div className="max-w-4xl mx-auto pt-4 lg:pt-8">
                {selectedMood ? (
                   <div className="animate-fade-in">
                      <div className="flex items-center gap-2 mb-6 border-b border-stone-200 pb-2">
                        <button 
                          onClick={() => {
                             setSelectedMood('');
                             setMoodResults([]);
                          }}
                          className="lg:hidden text-stone-500 hover:text-bible-gold"
                        >
                           <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                             <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" />
                           </svg>
                        </button>
                        <h3 className="text-xl font-bold text-bible-ink">
                           Versículos para: <span className="text-bible-accent">{selectedMood}</span>
                        </h3>
                      </div>

                      {loadingMood ? (
                         <div className="space-y-4">
                            <div className="h-32 bg-stone-200 rounded-xl animate-pulse"></div>
                            <div className="h-32 bg-stone-200 rounded-xl animate-pulse"></div>
                            <div className="h-32 bg-stone-200 rounded-xl animate-pulse"></div>
                         </div>
                      ) : (
                         <div className="space-y-6 pb-20">
                            {moodResults.map((item, idx) => (
                               <div key={idx} className="bg-white p-6 rounded-xl shadow-sm border border-stone-200 hover:shadow-md transition-shadow">
                                  <div className="flex items-start gap-4">
                                     <div className="p-3 bg-bible-gold/10 rounded-full text-bible-gold hidden sm:block">
                                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
                                          <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" />
                                        </svg>
                                     </div>
                                     <div className="flex-1">
                                        <h4 className="text-lg font-bold text-bible-leather mb-1">{item.verseReference}</h4>
                                        <p className="font-serif text-xl text-bible-ink mb-4 italic">"{item.text}"</p>
                                        <div className="bg-stone-50 p-4 rounded-lg text-sm text-stone-700">
                                           <TextAudioPlayer text={item.explanation} title="Explicación Pastoral" />
                                        </div>
                                     </div>
                                  </div>
                               </div>
                            ))}
                         </div>
                      )}
                   </div>
                ) : (
                   <MoodSelector onSelectMood={handleMoodSelect} />
                )}
             </div>
          )}

          {viewMode === 'devotional' && (
            <div className="max-w-2xl mx-auto pt-4 lg:pt-8 animate-fade-in">
              <div className="text-center mb-8">
                <h1 className="text-2xl lg:text-3xl font-display font-bold text-bible-ink">Devocional Diario</h1>
                <p className="text-stone-500 text-sm mt-1">{new Date().toLocaleDateString('es-ES', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
              </div>

              {loadingDevotional ? (
                <div className="space-y-6">
                  <div className="h-48 bg-stone-200 rounded-xl animate-pulse"></div>
                  <div className="h-32 bg-stone-200 rounded-xl animate-pulse"></div>
                  <div className="h-24 bg-stone-200 rounded-xl animate-pulse"></div>
                </div>
              ) : devotional ? (
                <div className="space-y-8 pb-20">
                  <div className="bg-white p-8 rounded-xl shadow-lg border-t-4 border-bible-gold text-center relative overflow-hidden">
                    <h2 className="text-3xl font-serif text-bible-ink leading-relaxed mb-6">"{devotional.verseText}"</h2>
                    <p className="text-bible-accent font-bold tracking-widest uppercase text-sm">{devotional.verseReference}</p>
                  </div>

                  <div className="bg-white p-6 rounded-lg border border-stone-200">
                    <div className="mb-4">
                      <TextAudioPlayer 
                        text={devotional.reflection} 
                        title="Reflexión Pastoral"
                      />
                    </div>
                  </div>

                  <div className="grid md:grid-cols-2 gap-6">
                     <div className="bg-stone-50 p-6 rounded-lg border-l-4 border-bible-leather">
                        <h3 className="text-stone-500 font-bold uppercase text-xs tracking-widest mb-3">Oración</h3>
                        <p className="font-serif italic text-stone-600">"{devotional.prayer}"</p>
