                           {result.text}
                         </p>
                      </div>
                    ))
                  )}
                </div>
              )}
            </div>
          )}

          {viewMode === 'plan' && (
             <div className="max-w-3xl mx-auto">
                <div className="text-center mb-8">
                   <h1 className="text-3xl lg:text-4xl font-display font-bold text-bible-ink mb-2">Planes de Lectura</h1>
