                      >
                        Cronológico
                      </button>
                      <button 
                        onClick={() => setPlanMode('time')}
                        className={`px-6 py-2 rounded-full text-sm font-bold transition-all ${planMode === 'time' ? 'bg-white shadow-sm text-bible-leather' : 'text-stone-500 hover:text-stone-700'}`}
                      >
                        Por Tiempo
                      </button>
                   </div>
                </div>

                {planMode === 'time' ? (
                   <ReadingGoalSelector onSelect={() => {}} />
                ) : (
                  <>
                    {loadingPlan ? (
                      <div className="space-y-4">
                        {[1,2,3].map(i => <div key={i} className="h-32 bg-stone-200 rounded animate-pulse" />)}
                      </div>
                    ) : (
                      <div className="relative border-l-2 border-bible-gold/30 ml-4 lg:ml-0 space-y-8 pl-8 lg:pl-12 py-4">
                        {chronoPlan.map((item, idx) => (
                          <div key={idx} className="relative group">
                            <span className="absolute -left-[41px] lg:-left-[57px] top-0 flex items-center justify-center w-8 h-8 rounded-full bg-bible-paper border-2 border-bible-gold text-bible-gold font-bold text-sm">
                              {item.order}
                            </span>
                            <div className="bg-white p-6 rounded-xl shadow-sm border border-stone-100 hover:shadow-md transition-shadow">
                              <h3 className="text-xl font-display font-bold text-bible-leather mb-2">{item.book} <span className="text-stone-400 text-base font-sans font-normal">Caps {item.chapters.join(", ")}...</span></h3>
                              <p className="text-stone-600 mb-4">{item.reason}</p>
                              <button 
                                onClick={() => {
                                  setCurrentBook(item.book);
                                  handleSelectChapter(item.chapters[0]);
                                }}
                                className="inline-flex items-center text-bible-accent hover:text-bible-leather font-bold text-sm uppercase tracking-wider"
                              >
                                Leer Ahora
                                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4 ml-1">
                                  <path strokeLinecap="round" strokeLinejoin="round" d="M13.5 4.5L21 12m0 0l-7.5 7.5M21 12H3" />
                                </svg>
                              </button>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
