            <div className="max-w-3xl mx-auto">
              {loadingState === LoadingState.IDLE && (
                 <div className="flex flex-col items-center justify-center h-full pt-20 text-center"><div className="w-24 h-24 bg-bible-gold/10 rounded-full flex items-center justify-center mb-6"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-12 h-12 text-bible-gold"><path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" /></svg></div><h1 className="text-4xl font-display font-bold text-bible-ink mb-4">Lectura Bíblica</h1><p className="text-stone-600 max-w-md mb-8">Usa el menú lateral para elegir un libro y capítulo.</p><button onClick={() => setSidebarOpen(true)} className="px-6 py-3 rounded-full bg-bible-leather text-white hover:bg-bible-ink transition-colors font-bold text-sm shadow-md">Abrir Biblioteca</button></div>
              )}

              {loadingState === LoadingState.LOADING && ( <div className="space-y-8 animate-pulse"><div className="h-12 bg-stone-200 rounded w-1/3 mx-auto"></div><div className="space-y-4 mt-12"><div className="h-4 bg-stone-200 rounded w-full"></div><div className="h-4 bg-stone-200 rounded w-5/6"></div></div></div> )}

              {loadingState === LoadingState.SUCCESS && data && (
                <div className="animate-fade-in pb-32 relative">
                  <div className="text-center mb-8">
                    <span className="text-bible-accent uppercase tracking-widest text-xs font-bold mb-2 block">Capítulo {data.metadata.chapter_number}</span>
                    <h1 className="text-4xl lg:text-5xl font-display font-bold text-bible-ink">{data.metadata.book_name}</h1>
                  </div>

                  <div className="mb-8 max-w-xl mx-auto sticky top-0 z-20 shadow-xl rounded-lg">
                    <TextAudioPlayer text={data.verses.map(v => v.text).join(' ')} title="Audio del Capítulo" className="border-none" showText={false} onBoundary={handleAudioProgress} />
                  </div>

                  <div className="space-y-6">
                    {data.verses.map((verse) => {
                      const noteKey = getNoteKey(data.metadata.book_name, data.metadata.chapter_number, verse.number);
                      const highlightKey = getHighlightKey(data.metadata.book_name, data.metadata.chapter_number, verse.number);
                      const note = userNotes[noteKey];
                      const currentVerseHighlights = verseHighlights[highlightKey] || [];
                      const isEditing = editingNote === noteKey;
                      const isAudioActive = audioActiveVerse === verse.number;
                      let activeCharIndexForVerse = null;
                      if (isAudioActive) {
                          const offsetData = verseOffsets.find(v => v.verse === verse.number);
                          if (offsetData) {
                              const localIndex = globalAudioCharIndex - offsetData.start;
                              if (localIndex >= 0 && localIndex <= (offsetData.end - offsetData.start)) { activeCharIndexForVerse = localIndex; }
                          }
                      }
                      return (
                        <div id={`verse-${verse.number}`} key={verse.number} className={`relative group transition-all duration-500 rounded-lg p-2 -mx-2 ${isAudioActive ? 'bg-bible-gold/5 border-l-4 border-bible-gold pl-3' : 'border-l-4 border-transparent'}`} data-verse-number={verse.number}>
                          <div className="absolute -left-8 lg:-left-12 top-2 flex flex-col items-end gap-1 w-10 z-10">
                             <span className={`text-xs font-bold font-sans select-none mb-1 transition-colors ${isAudioActive ? 'text-bible-gold scale-110' : 'text-bible-gold/60'}`}>{verse.number}</span>
                             <div className={`flex flex-col gap-1 transition-opacity duration-200 ${note ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                                <button onClick={() => setEditingNote(isEditing ? null : noteKey)} className={`p-1.5 rounded-full transition-colors ${note ? 'text-yellow-600 bg-yellow-50' : 'text-stone-300 hover:text-bible-accent hover:bg-stone-100'}`} title="Añadir nota"><svg xmlns="http://www.w3.org/2000/svg" fill={note ? "currentColor" : "none"} viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path strokeLinecap="round" strokeLinejoin="round" d="M16.862 4.487l1.687-1.688a1.875 1.875 0 112.652 2.652L10.582 16.07a4.5 4.5 0 01-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 011.13-1.897l8.932-8.931zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0115.75 21H5.25A2.25 2.25 0 013 18.75V8.25A2.25 2.25 0 015.25 6H10" /></svg></button>
                                <button onClick={() => handleCreateImage(verse.number, verse.text)} className="p-1.5 rounded-full text-stone-300 hover:text-pink-500 hover:bg-pink-50 transition-colors" title="Crear Imagen"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path strokeLinecap="round" strokeLinejoin="round" d="M2.25 15.75l5.159-5.159a2.25 2.25 0 013.182 0l5.159 5.159m-1.5-1.5l1.409-1.409a2.25 2.25 0 013.182 0l2.909 2.909m-18 3.75h16.5a1.5 1.5 0 001.5-1.5V6a1.5 1.5 0 00-1.5-1.5H3.75A1.5 1.5 0 002.25 6v12a1.5 1.5 0 001.5 1.5zm10.5-11.25h.008v.008h-.008V8.25zm.375 0a.375.375 0 11-.75 0 .375.375 0 01.75 0z" /></svg></button>
                                <button onClick={() => handleShowReferences(verse.number, verse.text)} className="p-1.5 rounded-full text-stone-300 hover:text-blue-500 hover:bg-blue-50 transition-colors" title="Ver Referencias Cruzadas"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path strokeLinecap="round" strokeLinejoin="round" d="M13.19 8.688a4.5 4.5 0 011.242 7.244l-4.5 4.5a4.5 4.5 0 01-6.364-6.364l1.757-1.757m13.35-.622l1.757-1.757a4.5 4.5 0 00-6.364-6.364l-4.5 4.5a4.5 4.5 0 001.242 7.244" /></svg></button>
                                <button onClick={() => handlePlayVerse(verse.number, verse.text)} className={`p-1.5 rounded-full transition-colors ${playingVerse === verse.number ? 'text-bible-gold bg-bible-gold/10' : 'text-stone-300 hover:text-green-500 hover:bg-green-50'}`} title="Escuchar Versículo">{playingVerse === verse.number ? ( <div className="flex gap-0.5 items-end h-3 w-3 justify-center"><span className="w-0.5 bg-bible-gold animate-music-bar-1 h-2"></span><span className="w-0.5 bg-bible-gold animate-music-bar-2 h-3"></span><span className="w-0.5 bg-bible-gold animate-music-bar-3 h-1"></span></div> ) : ( <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path strokeLinecap="round" strokeLinejoin="round" d="M19.114 5.636a9 9 0 010 12.728M16.463 8.288a5.25 5.25 0 010 7.424M6.75 8.25l4.72-4.72a.75.75 0 011.28.53v15.88a.75.75 0 01-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 012.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75z" /></svg> )}</button>
                                <button onClick={() => handleChatAboutVerse(verse.number, verse.text)} className="p-1.5 rounded-full text-stone-300 hover:text-purple-500 hover:bg-purple-50 transition-colors flex items-center justify-center group/chat" title="Chat AI"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path strokeLinecap="round" strokeLinejoin="round" d="M7.5 8.25h9m-9 3H12m-9.75 1.51c0 1.6 1.123 2.994 2.707 3.227 1.129.166 2.27.293 3.423.379.35.026.67.21.865.501L12 21l2.755-4.133a1.14 1.14 0 01.865-.501 48.172 48.172 0 003.423-.379c1.584-.233 2.707-1.626 2.707-3.228V6.741c0-1.602-1.123-2.995-2.707-3.228A48.394 48.394 0 0012 3c-2.392 0-4.744.175-7.043.513C3.373 3.746 2.25 5.14 2.25 6.741v6.018z" /></svg></button>
                             </div>
                          </div>
                          <div className="rounded-lg px-2"><HighlightableVerse text={verse.text} highlights={currentVerseHighlights} fontSize={fontSize} lineHeight={lineHeight} activeCharIndex={activeCharIndexForVerse} /></div>
                          {isEditing && ( <NoteEditor initialNote={note || ''} onSave={(content) => saveNote(data.metadata.book_name, data.metadata.chapter_number, verse.number, content)} onCancel={() => setEditingNote(null)} onDelete={() => deleteNote(data.metadata.book_name, data.metadata.chapter_number, verse.number)} /> )}
                          {!isEditing && note && ( <div onClick={() => setEditingNote(noteKey)} className="ml-4 lg:ml-8 mb-6 p-4 bg-yellow-50 rounded-lg border-l-4 border-yellow-400 cursor-pointer hover:bg-yellow-100 transition-colors"><div className="flex items-center gap-2 mb-1 text-xs font-bold text-yellow-700 uppercase tracking-wider"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3 h-3"><path fillRule="evenodd" d="M10 2c-1.716 0-3.408.106-5.07.31C3.806 2.45 3 3.414 3 4.517V17.25a.75.75 0 001.075.676L10 15.082l5.925 2.844A.75.75 0 0017 17.25V4.517c0-1.103-.806-2.068-1.93-2.207A41.403 41.403 0 0010 2z" clipRule="evenodd" /></svg>Tu Nota</div><p className="font-handwriting text-stone-800 text-sm italic">{note}</p></div> )}
                        </div>
                      );
                    })}
                  </div>

                  <div className="mt-12 pt-8 border-t border-stone-200"><ChapterExplanation explanation={data.metadata.detailed_explanation} /></div>
                  <div className="mt-8 flex justify-center"><button onClick={() => handleSelectChapter(currentChapter + 1)} className="px-8 py-3 bg-bible-leather text-white rounded-lg hover:bg-bible-ink transition-colors font-display">Siguiente Capítulo</button></div>
                  <div className="fixed bottom-6 right-6 z-30 animate-fade-in-up">
                     <button onClick={() => { setTutorTopic(`${data.metadata.book_name} Capítulo ${data.metadata.chapter_number}`); setIsReaderTutorOpen(true); }} className="group flex items-center gap-2 px-6 py-4 bg-bible-ink text-white rounded-full shadow-2xl hover:bg-stone-800 hover:scale-105 transition-all border-2 border-bible-gold/50"><span className="whitespace-nowrap text-sm font-bold">¿Dudas?</span><div className="relative"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-6 h-6 text-bible-gold"><path d="M11.25 4.533A9.707 9.707 0 006 3.75c-2.389 0-4.575.683-6.406 1.858a.75.75 0 01-.437-.695V3.75a.75.75 0 01.75-.75h14.25a.75.75 0 01.75.75v.916c0 .124-.034.24-.094.34a9.712 9.712 0 00-3.563-.467z" /><path fillRule="evenodd" d="M2.25 7.5a.75.75 0 01.75-.75h18a.75.75 0 01.75.75v.784a9.757 9.757 0 01-9.75 9.75A9.757 9.757 0 012.25 8.284V7.5zM9.994 17.585a.75.75 0 01.728.568A11.258 11.258 0 0012 21a11.258 11.258 0 001.278-2.847.75.75 0 011.456.368A12.76 12.76 0 0112 22.5c-1.25 0-2.436-.217-3.55-.615a.75.75 0 01.544-1.299z" clipRule="evenodd" /></svg><span className="absolute -top-1 -right-1 flex h-3 w-3"><span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-bible-gold opacity-75"></span><span className="relative inline-flex rounded-full h-3 w-3 bg-bible-gold"></span></span></div></button>
                  </div>
                </div>
              )}
              {loadingState === LoadingState.ERROR && ( <div className="text-center p-12 text-red-500"><p>Hubo un error al cargar. Intenta de nuevo.</p></div> )}
            </div>
          )}
        </div>
      </div>

      <ContextPanel metadata={data ? data.metadata : null} isOpen={isContextOpen} onClose={() => setContextOpen(false)} isLoading={loadingState === LoadingState.LOADING} />
      <TheologyTutor topic={tutorTopic} isOpen={isReaderTutorOpen} onClose={() => setIsReaderTutorOpen(false)} />
      {showRefsPanel && (
         <div className="fixed inset-y-0 right-0 lg:w-96 bg-white shadow-2xl z-50 animate-slide-in-right flex flex-col"><div className="p-4 bg-bible-ink text-white flex justify-between items-center"><h3 className="font-bold">Referencias Cruzadas</h3><button onClick={() => setShowRefsPanel(false)} className="text-stone-300 hover:text-white"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6"><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg></button></div><div className="flex-1 overflow-y-auto p-4 bg-stone-50 space-y-4">{loadingRefs ? ( <div className="space-y-4">{[1,2,3].map(i => <div key={i} className="h-24 bg-stone-200 rounded animate-pulse" />)}</div> ) : ( crossRefs.map((ref, i) => ( <div key={i} className="bg-white p-4 rounded-lg shadow-sm border border-stone-200"><h4 className="font-bold text-bible-accent mb-1">{ref.ref}</h4><p className="font-serif italic text-stone-700 mb-2">"{ref.text}"</p><p className="text-xs bg-stone-100 p-2 rounded text-stone-600">{ref.connection}</p></div> )) )}</div></div>
      )}
    </div>
  );
}

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { BIBLE_BOOKS, CATEGORY_LABELS, VERSE_COUNTS } from '../constants';
import { BibleBook } from '../types';

interface SidebarProps {
  currentBook: string;
  onSelectBook: (bookName: string) => void;
  onSelectChapter: (chapter: number) => void;
  onSelectVerse: (book: string, chapter: number, verse: number) => void;
  onNavigate: (view: 'home' | 'reader' | 'plan' | 'devotional' | 'mood' | 'saved' | 'study') => void;
  isOpen: boolean;
  onClose: () => void;
  streak?: number;
}

type SidebarView = 'books' | 'chapters' | 'verses';

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentBook, onSelectBook, onSelectChapter, onSelectVerse, onNavigate, isOpen, onClose, streak = 0 
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [view, setView] = useState<SidebarView>('books');
  const [selectedChapter, setSelectedChapter] = useState<number | null>(null);

  useEffect(() => {
    if (currentBook) {
      if (view === 'books') {
        setView('chapters');
      }
    } else {
      setView('books');
      setSelectedChapter(null);
    }
  }, [currentBook]);

  const groupedBooks = useMemo<Record<string, BibleBook[]>>(() => {
    const filtered = BIBLE_BOOKS.filter(b => 
      b.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const groups: Record<string, BibleBook[]> = {};
    filtered.forEach(book => {
      if (!groups[book.category]) groups[book.category] = [];
      groups[book.category].push(book);
    });
    return groups;
  }, [searchTerm]);

  const activeBookData = BIBLE_BOOKS.find(b => b.name === currentBook);

  const handleBookClick = (bookName: string) => {
    onSelectBook(bookName);
    setView('chapters');
    setSelectedChapter(null);
    setSearchTerm('');
  };

  const handleChapterClick = (chapter: number) => {
    setSelectedChapter(chapter);
    setView('verses');
  };

  const handleVerseClick = (verse: number) => {
    if (activeBookData && selectedChapter) {
      onSelectVerse(activeBookData.name, selectedChapter, verse);
      if (window.innerWidth < 1024) onClose();
    }
  };

  const handleBack = () => {
    if (view === 'verses') {
      setView('chapters');
      setSelectedChapter(null);
    } else if (view === 'chapters') {
      setView('books');
      onSelectBook('');
    }
  };

  const handleNavClick = (viewMode: 'home' | 'reader' | 'plan' | 'devotional' | 'mood' | 'saved' | 'study') => {
    if (viewMode === 'reader' || viewMode === 'home') {
        setView('books'); 
        onSelectBook('');
    }
    onNavigate(viewMode);
    if (window.innerWidth < 1024) onClose();
  };

  const verseCount = (activeBookData && selectedChapter) 
    ? (VERSE_COUNTS[activeBookData.name]?.[selectedChapter - 1] || 20) 
    : 0;

  return (
    <div className={`fixed inset-y-0 left-0 transform ${isOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 lg:static lg:w-80 bg-white border-r border-stone-200 z-40 transition-transform duration-300 ease-in-out flex flex-col h-full shadow-xl lg:shadow-none`}>
      <div className="p-6 border-b border-stone-100 bg-bible-paper">
        <div className="flex items-center justify-between mb-4">
           {view === 'books' ? (
             <div className="flex items-center justify-between w-full">
               <h2 className="text-2xl font-display font-bold text-bible-ink">Biblioteca</h2>
               <div className="flex items-center gap-1 bg-orange-50 px-3 py-1 rounded-full border border-orange-100" title="Racha de lectura">
                 <span className="text-lg">🔥</span>
                 <span className="text-sm font-bold text-orange-600">{streak}</span>
               </div>
             </div>
           ) : (
             <div className="flex items-center gap-2">
               <button onClick={handleBack} className="p-1 rounded-full hover:bg-stone-200 text-stone-500">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg>
               </button>
               <h2 className="text-lg font-display font-bold text-bible-ink truncate max-w-[180px]">
                 {view === 'chapters' ? activeBookData?.name : `${activeBookData?.name} ${selectedChapter}`}
               </h2>
             </div>
           )}
        </div>

        <div className="grid grid-cols-2 gap-2 mb-6">
           <button onClick={() => handleNavClick('home')} className="p-2 text-xs font-bold rounded bg-stone-100 hover:bg-bible-gold hover:text-white transition-colors text-stone-600">🏠 Inicio</button>
           <button onClick={() => handleNavClick('reader')} className="p-2 text-xs font-bold rounded bg-stone-100 hover:bg-bible-gold hover:text-white transition-colors text-stone-600">📖 Biblia</button>
           <button onClick={() => handleNavClick('plan')} className="p-2 text-xs font-bold rounded bg-stone-100 hover:bg-bible-gold hover:text-white transition-colors text-stone-600">📅 Planes</button>
           <button onClick={() => handleNavClick('devotional')} className="p-2 text-xs font-bold rounded bg-stone-100 hover:bg-bible-gold hover:text-white transition-colors text-stone-600">🙏 Devocional</button>
           <button onClick={() => handleNavClick('mood')} className="p-2 text-xs font-bold rounded bg-stone-100 hover:bg-bible-gold hover:text-white transition-colors text-stone-600">❤️ Sentimientos</button>
           <button onClick={() => handleNavClick('study')} className="p-2 text-xs font-bold rounded bg-stone-100 hover:bg-bible-gold hover:text-white transition-colors text-stone-600">🎓 Estudios</button>
           <button onClick={() => handleNavClick('saved')} className="col-span-2 p-2 text-xs font-bold rounded bg-stone-100 hover:bg-bible-gold hover:text-white transition-colors text-stone-600 flex items-center justify-center gap-2">
             <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path strokeLinecap="round" strokeLinejoin="round" d="M17.593 3.322c1.1.128 1.907 1.077 1.907 2.185V21L12 17.25 4.5 21V5.507c0-1.108.806-2.057 1.907-2.185a48.507 48.507 0 0111.186 0z" /></svg>
             Mis Guardados
           </button>
        </div>

        {view === 'books' && (
          <input type="text" placeholder="Buscar libro..." className="w-full px-4 py-2 rounded-lg bg-stone-100 border-none focus:ring-2 focus:ring-bible-gold outline-none text-sm font-sans" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
        )}
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6 bg-bible-paper">
        {view === 'books' && Object.entries(groupedBooks).map(([category, books]: [string, BibleBook[]]) => (
          <div key={category}>
            <h3 className="text-xs font-bold text-bible-accent uppercase tracking-widest mb-3 ml-2">{CATEGORY_LABELS[category]}</h3>
            <div className="space-y-1">
              {books.map(book => (
                <button key={book.name} onClick={() => handleBookClick(book.name)} className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium transition-colors ${currentBook === book.name ? 'bg-bible-gold/10 text-bible-gold' : 'text-stone-600 hover:bg-stone-50'}`}>{book.name}</button>
              ))}
            </div>
          </div>
        ))}

        {view === 'chapters' && activeBookData && (
          <div className="animate-fade-in"><p className="text-xs text-stone-500 mb-4 px-1">Capítulos:</p>
            <div className="grid grid-cols-5 gap-2">{Array.from({ length: activeBookData.chapters }, (_, i) => i + 1).map(chap => (
                <button key={chap} onClick={() => handleChapterClick(chap)} className="aspect-square flex items-center justify-center text-sm font-medium rounded hover:bg-bible-gold hover:text-white transition-colors bg-white border border-stone-200 text-stone-600">{chap}</button>
              ))}</div>
          </div>
        )}

        {view === 'verses' && activeBookData && selectedChapter && (
           <div className="animate-fade-in">
              <button onClick={() => { onSelectChapter(selectedChapter); if (window.innerWidth < 1024) onClose(); }} className="w-full mb-6 py-3 bg-stone-100 text-stone-600 font-bold text-sm rounded-lg hover:bg-bible-gold hover:text-white transition-colors flex items-center justify-center gap-2">
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4"><path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" /></svg>
                Leer Capítulo
              </button>
              <div className="grid grid-cols-5 gap-2">{Array.from({ length: verseCount }, (_, i) => i + 1).map(verse => (
                  <button key={verse} onClick={() => handleVerseClick(verse)} className="aspect-square flex items-center justify-center text-xs font-medium rounded hover:bg-bible-accent hover:text-white transition-colors bg-white border border-stone-200 text-stone-500">{verse}</button>
                ))}</div>
           </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Sidebar } from './components/Sidebar';
import { ContextPanel } from './components/ContextPanel';
import { NoteEditor } from './components/NoteEditor';
import { ChapterExplanation } from './components/ChapterExplanation';
import { HighlightableVerse } from './components/HighlightableVerse';
import { TextAudioPlayer } from './components/TextAudioPlayer';
import { MoodSelector } from './components/MoodSelector';
import { SavedContent } from './components/SavedContent';
import { StudyMode } from './components/StudyMode';
import { ShareableImage } from './components/ShareableImage';
import { ReadingGoalSelector } from './components/ReadingGoalSelector';
import { TheologyTutor } from './components/TheologyTutor';
import { getBibleChapter, getChronologicalPlan, searchBible, getDailyDevotional, getVersesByMood, getCrossReferences } from './services/geminiService';
import { ChapterResponse, LoadingState, ReadingPlanItem, SearchResult, DailyDevotional, Highlight, MoodResult, CrossReference, ReadingGoal } from './types';

const getNoteKey = (book: string, chapter: number, verse: number) => `note-${book}-${chapter}-${verse}`;
const getHighlightKey = (book: string, chapter: number, verse: number) => `highlights-v2-${book}-${chapter}-${verse}`;

interface SelectionMenuPosition {
  top: number;
  left: number;
  verseNumber: number;
  range: Range;
}

function App() {
  const [currentBook, setCurrentBook] = useState<string>('');
  const [currentChapter, setCurrentChapter] = useState<number>(1);
  const [data, setData] = useState<ChapterResponse | null>(null);
  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isContextOpen, setContextOpen] = useState(false);
  const [viewMode, setViewMode] = useState<'home' | 'reader' | 'plan' | 'search' | 'devotional' | 'mood' | 'saved' | 'study'>('home');
  const [planMode, setPlanMode] = useState<'chrono' | 'time'>('chrono');
  const [scrollToVerse, setScrollToVerse] = useState<number | null>(null);
  const [chronoPlan, setChronoPlan] = useState<ReadingPlanItem[]>([]);
  const [loadingPlan, setLoadingPlan] = useState(false);
  const [devotional, setDevotional] = useState<DailyDevotional | null>(null);
  const [loadingDevotional, setLoadingDevotional] = useState(false);
  const [moodResults, setMoodResults] = useState<MoodResult[]>([]);
  const [loadingMood, setLoadingMood] = useState(false);
  const [selectedMood, setSelectedMood] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [userNotes, setUserNotes] = useState<Record<string, string>>({});
  const [editingNote, setEditingNote] = useState<string | null>(null); 
  const [verseHighlights, setVerseHighlights] = useState<Record<string, Highlight[]>>({});
  const [selectionMenu, setSelectionMenu] = useState<SelectionMenuPosition | null>(null);
  const [fontSize, setFontSize] = useState<number>(18); 
  const [lineHeight, setLineHeight] = useState<number>(1.625); 
  const [isImageCreatorOpen, setImageCreatorOpen] = useState(false);
  const [selectedVerseForAction, setSelectedVerseForAction] = useState<{number: number, text: string} | null>(null);
  const [crossRefs, setCrossRefs] = useState<CrossReference[]>([]);
  const [loadingRefs, setLoadingRefs] = useState(false);
  const [showRefsPanel, setShowRefsPanel] = useState(false);
  const [isReaderTutorOpen, setIsReaderTutorOpen] = useState(false);
  const [tutorTopic, setTutorTopic] = useState<string>('');
  const [playingVerse, setPlayingVerse] = useState<number | null>(null);
  const [audioActiveVerse, setAudioActiveVerse] = useState<number | null>(null);
  const [globalAudioCharIndex, setGlobalAudioCharIndex] = useState<number>(0);
  const [streakDays, setStreakDays] = useState(0);

  const verseOffsets = useMemo(() => {
    if (!data) return [];
    let currentOffset = 0;
    return data.verses.map(v => {
        const start = currentOffset;
        const length = v.text.length;
        currentOffset += length + 1; 
        return { verse: v.number, start, end: start + length };
    });
  }, [data]);

  const handleAudioProgress = (charIndex: number) => {
     setGlobalAudioCharIndex(charIndex); 
     if (!verseOffsets.length) return;
     const match = verseOffsets.find(v => charIndex >= v.start && charIndex <= v.end);
     if (match && match.verse !== audioActiveVerse) {
        setAudioActiveVerse(match.verse);
        const el = document.getElementById(`verse-${match.verse}`);
        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
     }
  };

  useEffect(() => {
    const loadedNotes: Record<string, string> = {};
    const loadedHighlights: Record<string, Highlight[]> = {};
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key) {
        if (key.startsWith('note-')) loadedNotes[key] = localStorage.getItem(key) || '';
        else if (key.startsWith('highlights-v2-')) {
          try { loadedHighlights[key] = JSON.parse(localStorage.getItem(key) || '[]'); } catch (e) {}
        }
      }
    }
    setUserNotes(loadedNotes);
    setVerseHighlights(loadedHighlights);

    const today = new Date().toDateString();
    const lastVisit = localStorage.getItem('lastVisitDate');
    let streak = parseInt(localStorage.getItem('currentStreak') || '0');
    if (lastVisit !== today) {
        if (lastVisit) {
            const yesterday = new Date(); yesterday.setDate(yesterday.getDate() - 1);
            if (new Date(lastVisit).toDateString() === yesterday.toDateString()) streak += 1;
            else streak = 1;
        } else streak = 1;
        localStorage.setItem('lastVisitDate', today);
        localStorage.setItem('currentStreak', streak.toString());
    }
    setStreakDays(streak);
  }, []);

  const fetchChapter = async (book: string, chapter: number) => {
    setLoadingState(LoadingState.LOADING);
    setData(null);
    setAudioActiveVerse(null);
    setGlobalAudioCharIndex(0);
    setContextOpen(false); // Default hidden
    try {
      const result = await getBibleChapter(book, chapter);
      setData(result);
      setLoadingState(LoadingState.SUCCESS);
      setTutorTopic(`${result.metadata.book_name} Capítulo ${result.metadata.chapter_number}`);
    } catch (error) {
      setLoadingState(LoadingState.ERROR);
    }
  };

  const handleSelectBook = (book: string) => { setCurrentBook(book); setCurrentChapter(1); };
  const handleSelectChapter = (chapter: number) => {
    setCurrentChapter(chapter);
    fetchChapter(currentBook, chapter);
    setSidebarOpen(false); 
    setViewMode('reader');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };
  const handleSelectVerse = (book: string, chapter: number, verse: number) => {
    if (currentBook === book && currentChapter === chapter && data) {
       setScrollToVerse(verse);
       setSidebarOpen(false);
       setViewMode('reader');
    } else {
       setCurrentBook(book); setCurrentChapter(chapter); setScrollToVerse(verse);
       fetchChapter(book, chapter); setSidebarOpen(false); setViewMode('reader');
    }
  };

  const handleGoHome = () => {
    setData(null); setLoadingState(LoadingState.IDLE); setViewMode('home');
    setCurrentBook(''); setCurrentChapter(1); setSearchQuery('');
    setSidebarOpen(false); setContextOpen(false);
  };

  const handleNavigate = (mode: 'home' | 'reader' | 'plan' | 'devotional' | 'mood' | 'saved' | 'study') => {
    if (mode === 'home') handleGoHome();
    else if (mode === 'reader') { setViewMode('reader'); if (!data) setSidebarOpen(true); }
    else if (mode === 'plan') loadChronologicalPlan();
    else if (mode === 'devotional') loadDevotional();
    else if (mode === 'mood') loadMoodSelector();
    else if (mode === 'saved') { setViewMode('saved'); setSidebarOpen(false); }
    else if (mode === 'study') { setViewMode('study'); setSidebarOpen(false); }
  };

  const loadChronologicalPlan = async () => {
    setViewMode('plan'); setSidebarOpen(false);
    if (chronoPlan.length === 0) {
      setLoadingPlan(true);
      try { const plan = await getChronologicalPlan(); setChronoPlan(plan); } catch (e) {} finally { setLoadingPlan(false); }
    }
  };

  const loadDevotional = async () => {
    setViewMode('devotional'); setSidebarOpen(false);
    if (!devotional) {
      setLoadingDevotional(true);
      try { const result = await getDailyDevotional(); setDevotional(result); } catch (e) {} finally { setLoadingDevotional(false); }
    }
  };

  const loadMoodSelector = () => { setViewMode('mood'); setSidebarOpen(false); setSelectedMood(''); setMoodResults([]); };

  const handleSearch = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!searchQuery.trim()) return;
    setViewMode('search'); setSidebarOpen(false); setIsSearching(true); setSearchResults([]);
    try { const results = await searchBible(searchQuery); setSearchResults(results); } catch (error) {} finally { setIsSearching(false); }
  };

  const addHighlight = (color: string) => {
    if (!selectionMenu || !data) return;
    const { verseNumber, range } = selectionMenu;
    const selectedText = range.toString();
    const verseEl = document.querySelector(`[data-verse-number="${verseNumber}"]`);
    if (!verseEl) return;
    const preCaretRange = range.cloneRange();
    preCaretRange.selectNodeContents(verseEl);
    preCaretRange.setEnd(range.startContainer, range.startOffset);
    const start = preCaretRange.toString().length;
    const end = start + selectedText.length;
    const key = getHighlightKey(data.metadata.book_name, data.metadata.chapter_number, verseNumber);
    const updatedHighlights = [...(verseHighlights[key] || []), { id: Date.now().toString(), start, end, color, text: selectedText }];
    setVerseHighlights(prev => ({ ...prev, [key]: updatedHighlights }));
    localStorage.setItem(key, JSON.stringify(updatedHighlights));
    setSelectionMenu(null);
    window.getSelection()?.removeAllRanges();
  };

  const handlePlayVerse = (verseNumber: number, text: string) => {
    window.speechSynthesis.cancel();
    if (playingVerse === verseNumber) { setPlayingVerse(null); return; }
    setPlayingVerse(verseNumber);
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'es-ES';
    utterance.onend = () => setPlayingVerse(null);
    window.speechSynthesis.speak(utterance);
  };

  return (
    <div className="flex h-screen bg-stone-100 overflow-hidden font-sans" onClick={(e) => {
        const target = e.target as HTMLElement;
        if (!target.closest('#highlight-menu') && (!window.getSelection() || window.getSelection()?.isCollapsed)) setSelectionMenu(null);
    }}>

      {selectionMenu && (
        <div id="highlight-menu" className="fixed z-50 bg-white rounded-full shadow-xl border border-stone-200 p-2 flex gap-2 animate-fade-in" style={{ top: selectionMenu.top, left: selectionMenu.left }}>
          {['yellow', 'green', 'blue', 'pink'].map(color => (
            <button key={color} onMouseDown={(e) => { e.preventDefault(); addHighlight(color); }} className={`w-8 h-8 rounded-full bg-${color}-400 hover:scale-110 transition-transform border border-stone-100`} />
          ))}
          <div className="w-px h-8 bg-stone-200 mx-1"></div>
          <button onMouseDown={(e) => { e.preventDefault(); 
             const key = getHighlightKey(data!.metadata.book_name, data!.metadata.chapter_number, selectionMenu.verseNumber);
             setVerseHighlights(prev => ({ ...prev, [key]: [] })); localStorage.removeItem(key); setSelectionMenu(null); window.getSelection()?.removeAllRanges();
          }} className="px-3 py-1 text-xs font-bold text-red-500 hover:bg-red-50 rounded-full">Borrar</button>
        </div>
      )}

      {isImageCreatorOpen && selectedVerseForAction && data && (
         <ShareableImage verseText={selectedVerseForAction.text} verseReference={`${data.metadata.book_name} ${data.metadata.chapter_number}:${selectedVerseForAction.number}`} onClose={() => setImageCreatorOpen(false)} />
      )}

      <Sidebar 
        currentBook={currentBook} 
        onSelectBook={handleSelectBook} 
        onSelectChapter={handleSelectChapter}
        onSelectVerse={handleSelectVerse}
        onNavigate={handleNavigate}
        isOpen={isSidebarOpen}
        onClose={() => setSidebarOpen(false)}
        streak={streakDays}
      />

      <div className="flex-1 flex flex-col h-full overflow-hidden relative">
        <header className="bg-white border-b border-stone-200 p-4 flex items-center justify-between lg:hidden shadow-sm z-30">
          <div className="flex items-center gap-2">
            {viewMode !== 'home' ? (
              <button onClick={handleGoHome} className="p-2 text-bible-leather flex items-center gap-1 bg-stone-100 rounded-full pr-3">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg>
                 <span className="text-xs font-bold">Inicio</span>
              </button>
            ) : (
              <button onClick={() => setSidebarOpen(true)} className="p-2 text-bible-leather">
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6"><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" /></svg>
              </button>
            )}
          </div>

           <form onSubmit={handleSearch} className="flex-1 mx-2">
              <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Buscar en la Biblia..." className="w-full bg-stone-100 border-none rounded-full py-1.5 px-4 text-sm focus:ring-1 focus:ring-bible-gold outline-none" />
           </form>

          {data && viewMode === 'reader' && (
            <button onClick={() => setContextOpen(!isContextOpen)} className={`p-2 rounded-full transition-colors ${isContextOpen ? 'bg-bible-gold text-white' : 'text-bible-gold hover:bg-bible-gold/10'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 18v-5.25m0 0a6.001 6.001 0 00-5.304-7.618 6.002 6.002 0 019.957 5.304c.42 2.15-1.65 4.314-4.653 2.314zm0 0l-7.05 4.633a1.125 1.125 0 01-1.373-1.634l-.75-7.5M12 18l7.05 4.633a1.125 1.125 0 001.373-1.634l-.75-7.5" />
              </svg>
            </button>
          )}
        </header>

         <div className="hidden lg:flex items-center justify-between px-8 py-4 bg-white border-b border-stone-200">
             <div className="flex gap-4 items-center flex-1 overflow-x-auto">
                <button onClick={handleGoHome} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${viewMode === 'home' ? 'bg-bible-leather text-white' : 'text-stone-500 hover:bg-stone-100'}`}>Inicio</button>
                <button onClick={() => handleNavigate('reader')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${viewMode === 'reader' ? 'bg-bible-leather text-white' : 'text-stone-500 hover:bg-stone-100'}`}>Biblia</button>
                <button onClick={() => handleNavigate('plan')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${viewMode === 'plan' ? 'bg-bible-leather text-white' : 'text-stone-500 hover:bg-stone-100'}`}>Planes</button>
                <button onClick={() => handleNavigate('devotional')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${viewMode === 'devotional' ? 'bg-bible-leather text-white' : 'text-stone-500 hover:bg-stone-100'}`}>Devocional</button>
                <button onClick={() => handleNavigate('mood')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${viewMode === 'mood' ? 'bg-bible-leather text-white' : 'text-stone-500 hover:bg-stone-100'}`}>Sentimientos</button>
                <button onClick={() => handleNavigate('study')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${viewMode === 'study' ? 'bg-bible-leather text-white' : 'text-stone-500 hover:bg-stone-100'}`}>Estudios</button>
             </div>

             {data && viewMode === 'reader' && (
               <div className="flex items-center gap-4 ml-4">
                  <div className="flex items-center space-x-2 border-r border-stone-200 pr-4">
                     <button onClick={() => setFontSize(s => Math.max(14, s - 2))} className="text-stone-500 hover:text-bible-ink px-1 font-serif text-sm">A-</button>
                     <button onClick={() => setFontSize(s => Math.min(32, s + 2))} className="text-stone-500 hover:text-bible-ink px-1 font-serif text-lg">A+</button>
                  </div>
                  <button 
                    onClick={() => setContextOpen(!isContextOpen)} 
                    className={`flex items-center gap-2 px-4 py-2 rounded-full transition-all border-2 ${isContextOpen ? 'bg-bible-gold border-bible-gold text-white shadow-md' : 'bg-white border-bible-gold/30 text-bible-gold hover:border-bible-gold'}`}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                      <path strokeLinecap="round" strokeLinejoin="round" d="M12 18v-5.25m0 0a6.001 6.001 0 00-5.304-7.618 6.002 6.002 0 019.957 5.304c.42 2.15-1.65 4.314-4.653 2.314zm0 0l-7.05 4.633a1.125 1.125 0 01-1.373-1.634l-.75-7.5M12 18l7.05 4.633a1.125 1.125 0 001.373-1.634l-.75-7.5" />
                    </svg>
                    <span className="text-xs font-bold uppercase tracking-wider">Análisis Contextual</span>
                  </button>
               </div>
             )}
         </div>

        <div id="bible-content-area" className="flex-1 overflow-y-auto bg-bible-paper p-4 lg:p-12 relative scroll-smooth">

          {viewMode === 'home' && (
             <div className="max-w-5xl mx-auto py-6 animate-fade-in">
                <div className="text-center mb-12">
                   <div className="w-24 h-24 bg-bible-leather rounded-full flex items-center justify-center mx-auto mb-6 shadow-xl border-4 border-bible-gold/20">
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-14 h-14 text-bible-gold">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" />
                      </svg>
                   </div>
                   <h1 className="text-5xl md:text-6xl font-display font-bold text-bible-ink mb-4 tracking-tighter">ABBA BIBLIA</h1>
                   <p className="text-stone-500 text-lg max-w-xl mx-auto italic font-serif leading-relaxed">"Lámpara es a mis pies tu palabra, y lumbrera a mi camino." <br/><span className="text-bible-accent not-italic font-sans text-sm font-bold uppercase tracking-widest mt-2 block">— Salmos 119:105</span></p>
                </div>

                <div className="grid grid-cols-2 md:grid-cols-3 gap-4 lg:gap-8">
                   {[
                      { mode: 'reader', label: 'Leer Biblia', sub: 'Texto y Análisis', icon: '📖', color: 'from-amber-50 to-orange-50' },
                      { mode: 'devotional', label: 'Devocional', sub: 'Reflexión Diaria', icon: '🙏', color: 'from-emerald-50 to-teal-50' },
                      { mode: 'plan', label: 'Planes', sub: 'Ruta de Lectura', icon: '📅', color: 'from-blue-50 to-indigo-50' },
                      { mode: 'study', label: 'Estudios', sub: 'Clases y Quizzes', icon: '🎓', color: 'from-purple-50 to-fuchsia-50' },
                      { mode: 'mood', label: 'Sentimientos', sub: 'Guía Espiritual', icon: '❤️', color: 'from-rose-50 to-red-50' },
                      { mode: 'saved', label: 'Favoritos', sub: 'Notas y Resaltados', icon: '🔖', color: 'from-stone-100 to-stone-200' },
                   ].map((item: any) => (
                      <button 
                        key={item.mode} 
                        onClick={() => handleNavigate(item.mode)} 
                        className={`bg-gradient-to-br ${item.color} p-6 md:p-8 rounded-3xl shadow-sm border border-black/5 hover:shadow-2xl hover:-translate-y-2 transition-all flex flex-col items-center text-center group relative overflow-hidden`}
                      >
                         <span className="text-4xl md:text-5xl mb-4 group-hover:scale-125 transition-transform duration-500">{item.icon}</span>
                         <h3 className="text-lg md:text-xl font-display font-bold text-bible-ink mb-1">{item.label}</h3>
                         <p className="text-stone-500 text-[10px] md:text-xs font-bold uppercase tracking-widest opacity-60">{item.sub}</p>
                         <div className="absolute -bottom-2 -right-2 w-12 h-12 bg-black/5 rounded-full group-hover:scale-150 transition-transform"></div>
                      </button>
                   ))}
                </div>

                <div className="mt-12 bg-white/60 backdrop-blur-md border border-stone-200 p-8 rounded-[2.5rem] text-center shadow-inner">
                   <h2 className="text-2xl font-display font-bold text-bible-ink mb-2">Comienza Hoy</h2>
                   <p className="text-stone-500 mb-8 text-sm">¿En qué parte de las Escrituras quieres profundizar?</p>
                   <button onClick={() => { setSidebarOpen(true); setViewMode('reader'); }} className="bg-bible-leather text-white px-12 py-4 rounded-full font-bold shadow-xl hover:bg-bible-ink hover:scale-105 active:scale-95 transition-all text-sm tracking-widest uppercase">Elegir Libro</button>
                </div>
             </div>
          )}

          {viewMode === 'reader' && (
            <div className="max-w-3xl mx-auto">
              {loadingState === LoadingState.IDLE && (
                 <div className="flex flex-col items-center justify-center h-full pt-10 text-center animate-fade-in">
                    <div className="w-20 h-20 bg-bible-gold/10 rounded-full flex items-center justify-center mb-6">
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-10 h-10 text-bible-gold"><path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" /></svg>
                    </div>
                    <h1 className="text-4xl font-display font-bold text-bible-ink mb-4">Estudio Bíblico</h1>
                    <p className="text-stone-500 max-w-md mb-8">Navega por los libros y descubre el contexto histórico y teológico con ayuda de la IA.</p>
                    <button onClick={() => setSidebarOpen(true)} className="px-8 py-3 rounded-full bg-bible-leather text-white hover:bg-bible-ink transition-all font-bold text-sm shadow-lg">Abrir Biblioteca</button>
                 </div>
              )}

              {loadingState === LoadingState.LOADING && ( <div className="space-y-8 animate-pulse"><div className="h-12 bg-stone-200 rounded w-1/3 mx-auto"></div><div className="space-y-4 mt-12"><div className="h-4 bg-stone-200 rounded w-full"></div><div className="h-4 bg-stone-200 rounded w-5/6"></div></div></div> )}

              {loadingState === LoadingState.SUCCESS && data && (
                <div className="animate-fade-in pb-32 relative">
                  <div className="text-center mb-10">
                    <span className="text-bible-accent uppercase tracking-[0.3em] text-[10px] font-bold mb-3 block">Capítulo {data.metadata.chapter_number}</span>
                    <h1 className="text-5xl lg:text-6xl font-display font-bold text-bible-ink">{data.metadata.book_name}</h1>
                  </div>

                  <div className="mb-10 max-w-xl mx-auto sticky top-0 z-20 shadow-2xl rounded-2xl overflow-hidden bg-white/80 backdrop-blur-md border border-stone-200">
                    <TextAudioPlayer text={data.verses.map(v => v.text).join(' ')} title="Audio Biblia" className="border-none" showText={false} onBoundary={handleAudioProgress} />
                  </div>

                  <div className="space-y-8">
                    {data.verses.map((verse) => {
                      const noteKey = getNoteKey(data.metadata.book_name, data.metadata.chapter_number, verse.number);
                      const highlightKey = getHighlightKey(data.metadata.book_name, data.metadata.chapter_number, verse.number);
                      const note = userNotes[noteKey];
                      const currentVerseHighlights = verseHighlights[highlightKey] || [];
                      const isEditing = editingNote === noteKey;
                      const isAudioActive = audioActiveVerse === verse.number;
                      let activeCharIndexForVerse = null;
                      if (isAudioActive) {
                          const offsetData = verseOffsets.find(v => v.verse === verse.number);
                          if (offsetData) {
                              const localIndex = globalAudioCharIndex - offsetData.start;
                              if (localIndex >= 0 && localIndex <= (offsetData.end - offsetData.start)) activeCharIndexForVerse = localIndex;
                          }
                      }
                      return (
                        <div id={`verse-${verse.number}`} key={verse.number} className={`relative group transition-all duration-700 rounded-xl p-3 -mx-3 ${isAudioActive ? 'bg-bible-gold/10 border-l-4 border-bible-gold' : 'border-l-4 border-transparent'}`} data-verse-number={verse.number}>
                          <div className="absolute -left-10 lg:-left-12 top-3 flex flex-col items-end gap-2 w-10 z-10">
                             <span className={`text-[10px] font-bold font-sans select-none mb-1 transition-all ${isAudioActive ? 'text-bible-gold scale-150' : 'text-bible-gold/40'}`}>{verse.number}</span>
                             <div className={`flex flex-col gap-2 transition-opacity duration-300 ${note ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                                <button onClick={() => setEditingNote(isEditing ? null : noteKey)} className={`p-1.5 rounded-full ${note ? 'text-yellow-600 bg-yellow-50' : 'text-stone-300 hover:text-bible-accent'}`} title="Nota"><svg xmlns="http://www.w3.org/2000/svg" fill={note ? "currentColor" : "none"} viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path d="M16.862 4.487l1.687-1.688a1.875 1.875 0 112.652 2.652L10.582 16.07a4.5 4.5 0 01-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 011.13-1.897l8.932-8.931zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0115.75 21H5.25A2.25 2.25 0 013 18.75V8.25A2.25 2.25 0 015.25 6H10" /></svg></button>
                                <button onClick={() => handlePlayVerse(verse.number, verse.text)} className={`p-1.5 rounded-full ${playingVerse === verse.number ? 'text-bible-gold' : 'text-stone-300 hover:text-green-500'}`} title="Oír">{playingVerse === verse.number ? '🔊' : <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path d="M19.114 5.636a9 9 0 010 12.728M16.463 8.288a5.25 5.25 0 010 7.424M6.75 8.25l4.72-4.72a.75.75 0 011.28.53v15.88a.75.75 0 01-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 012.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75z" /></svg>}</button>
                             </div>
                          </div>
                          <div className="rounded-lg px-2"><HighlightableVerse text={verse.text} highlights={currentVerseHighlights} fontSize={fontSize} lineHeight={lineHeight} activeCharIndex={activeCharIndexForVerse} /></div>
                          {isEditing && ( <NoteEditor initialNote={note || ''} onSave={(c) => { localStorage.setItem(noteKey, c); setUserNotes(prev => ({ ...prev, [noteKey]: c })); setEditingNote(null); }} onCancel={() => setEditingNote(null)} onDelete={() => { localStorage.removeItem(noteKey); setUserNotes(p => { const n = {...p}; delete n[noteKey]; return n; }); setEditingNote(null); }} /> )}
                          {!isEditing && note && ( <div onClick={() => setEditingNote(noteKey)} className="ml-4 lg:ml-8 mb-6 p-4 bg-yellow-50 rounded-xl border-l-4 border-yellow-400 cursor-pointer hover:bg-yellow-100 transition-colors shadow-sm"><p className="font-handwriting text-stone-800 text-sm italic">"{note}"</p></div> )}
                        </div>
                      );
                    })}
                  </div>

                  <div className="mt-16 pt-10 border-t border-stone-200"><ChapterExplanation explanation={data.metadata.detailed_explanation} /></div>
                  <div className="mt-12 flex justify-center"><button onClick={() => handleSelectChapter(currentChapter + 1)} className="px-10 py-4 bg-bible-leather text-white rounded-full hover:bg-bible-ink transition-all font-display shadow-2xl hover:scale-105 active:scale-95">Siguiente Capítulo</button></div>
                  <div className="fixed bottom-6 right-6 z-30 animate-fade-in-up">
                     <button onClick={() => { setTutorTopic(`${data.metadata.book_name} Capítulo ${data.metadata.chapter_number}`); setIsReaderTutorOpen(true); }} className="group flex items-center gap-3 px-6 py-4 bg-bible-ink text-white rounded-full shadow-2xl hover:bg-stone-800 transition-all border-2 border-bible-gold/50"><span className="text-sm font-bold">¿Dudas?</span><div className="relative"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-6 h-6 text-bible-gold"><path d="M11.25 4.533A9.707 9.707 0 006 3.75c-2.389 0-4.575.683-6.406 1.858a.75.75 0 01-.437-.695V3.75a.75.75 0 01.75-.75h14.25a.75.75 0 01.75.75v.916c0 .124-.034.24-.094.34a9.712 9.712 0 00-3.563-.467z" /><path fillRule="evenodd" d="M2.25 7.5a.75.75 0 01.75-.75h18a.75.75 0 01.75.75v.784a9.757 9.757 0 01-9.75 9.75A9.757 9.757 0 012.25 8.284V7.5zM9.994 17.585a.75.75 0 01.728.568A11.258 11.258 0 0012 21a11.258 11.258 0 001.278-2.847.75.75 0 011.456.368A12.76 12.76 0 0112 22.5c-1.25 0-2.436-.217-3.55-.615a.75.75 0 01.544-1.299z" clipRule="evenodd" /></svg></div></button>
                  </div>
                </div>
              )}
            </div>
          )}

          {viewMode === 'saved' && ( <SavedContent onNavigateToVerse={handleSelectVerse} onDeleteItem={(k) => { localStorage.removeItem(k); handleNavigate('saved'); }} /> )}
          {viewMode === 'study' && ( <StudyMode /> )}
          {viewMode === 'mood' && (
             <div className="max-w-4xl mx-auto pt-4 lg:pt-8">
                {selectedMood ? (
                   <div className="animate-fade-in">
                      <div className="flex items-center gap-2 mb-6 border-b border-stone-200 pb-2">
                        <button onClick={() => { setSelectedMood(''); setMoodResults([]); }} className="text-stone-500 hover:text-bible-gold"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg></button>
                        <h3 className="text-xl font-bold text-bible-ink">Versículos para: <span className="text-bible-accent">{selectedMood}</span></h3>
                      </div>
                      <div className="space-y-6 pb-20">{moodResults.map((item, idx) => (<div key={idx} className="bg-white p-6 rounded-2xl shadow-sm border border-stone-100"><h4 className="font-bold text-bible-leather mb-1">{item.verseReference}</h4><p className="font-serif text-xl text-bible-ink mb-4 italic">"{item.text}"</p><p className="text-sm text-stone-600 bg-stone-50 p-4 rounded-xl">{item.explanation}</p></div>))}</div>
                   </div>
                ) : ( <MoodSelector onSelectMood={async (m) => { setSelectedMood(m); setLoadingMood(true); const r = await getVersesByMood(m); setMoodResults(r); setLoadingMood(false); }} /> )}
             </div>
          )}
          {viewMode === 'plan' && ( <div className="max-w-3xl mx-auto"><div className="text-center mb-8 font-display font-bold text-3xl text-bible-ink">Planes de Lectura</div><ReadingGoalSelector onSelect={() => {}} /></div> )}
          {viewMode === 'devotional' && (
            <div className="max-w-2xl mx-auto pt-8 animate-fade-in">
               <div className="text-center mb-10"><h1 className="text-3xl font-display font-bold text-bible-ink">Devocional Diario</h1><p className="text-stone-500 text-sm">{new Date().toLocaleDateString('es-ES', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p></div>
               {loadingDevotional ? ( <div className="h-40 bg-white rounded-2xl animate-pulse"></div> ) : devotional ? (
                <div className="space-y-8 pb-20 animate-fade-in-up">
                  <div className="bg-white p-10 rounded-[2.5rem] shadow-2xl border-t-8 border-bible-gold text-center"><h2 className="text-3xl font-serif text-bible-ink leading-relaxed mb-6 italic">"{devotional.verseText}"</h2><p className="text-bible-accent font-bold tracking-[0.2em] uppercase text-xs">{devotional.verseReference}</p></div>
                  <div className="bg-white p-8 rounded-3xl shadow-sm border border-stone-100"><TextAudioPlayer text={devotional.reflection} title="Reflexión" /></div>
                </div>
               ) : ( <div className="text-center py-20"><button onClick={loadDevotional} className="px-10 py-4 bg-bible-gold text-white rounded-full font-bold shadow-xl">Comenzar</button></div> )}
            </div>
          )}
        </div>
      </div>

      <ContextPanel metadata={data ? data.metadata : null} isOpen={isContextOpen} onClose={() => setContextOpen(false)} isLoading={loadingState === LoadingState.LOADING} />
      <TheologyTutor topic={tutorTopic} isOpen={isReaderTutorOpen} onClose={() => setIsReaderTutorOpen(false)} />
    </div>
  );
}

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { BIBLE_BOOKS, CATEGORY_LABELS, VERSE_COUNTS } from '../constants';
import { BibleBook } from '../types';

interface SidebarProps {
  currentBook: string;
  onSelectBook: (bookName: string) => void;
  onSelectChapter: (chapter: number) => void;
  onSelectVerse: (book: string, chapter: number, verse: number) => void;
  onNavigate: (view: 'home' | 'reader' | 'plan' | 'devotional' | 'mood' | 'saved' | 'study') => void;
  isOpen: boolean;
  onClose: () => void;
  streak?: number;
}

type SidebarView = 'books' | 'chapters' | 'verses';

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentBook, onSelectBook, onSelectChapter, onSelectVerse, onNavigate, isOpen, onClose, streak = 0 
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [view, setView] = useState<SidebarView>('books');
  const [selectedChapter, setSelectedChapter] = useState<number | null>(null);

  useEffect(() => {
    if (currentBook) {
      if (view === 'books') setView('chapters');
    } else {
      setView('books');
      setSelectedChapter(null);
    }
  }, [currentBook]);

  const groupedBooks = useMemo<Record<string, BibleBook[]>>(() => {
    const filtered = BIBLE_BOOKS.filter(b => b.name.toLowerCase().includes(searchTerm.toLowerCase()));
    const groups: Record<string, BibleBook[]> = {};
    filtered.forEach(book => {
      if (!groups[book.category]) groups[book.category] = [];
      groups[book.category].push(book);
    });
    return groups;
  }, [searchTerm]);

  const activeBookData = BIBLE_BOOKS.find(b => b.name === currentBook);

  const handleBookClick = (bookName: string) => {
    onSelectBook(bookName);
    setView('chapters');
    setSelectedChapter(null);
    setSearchTerm('');
  };

  const handleChapterClick = (chapter: number) => {
    setSelectedChapter(chapter);
    setView('verses');
  };

  const handleVerseClick = (verse: number) => {
    if (activeBookData && selectedChapter) {
      onSelectVerse(activeBookData.name, selectedChapter, verse);
      if (window.innerWidth < 1024) onClose();
    }
  };

  const handleBack = () => {
    if (view === 'verses') { setView('chapters'); setSelectedChapter(null); }
    else if (view === 'chapters') { setView('books'); onSelectBook(''); }
  };

  const handleNavClick = (viewMode: any) => {
    if (viewMode === 'reader' || viewMode === 'home') { setView('books'); onSelectBook(''); }
    onNavigate(viewMode);
    if (window.innerWidth < 1024) onClose();
  };

  const verseCount = (activeBookData && selectedChapter) 
    ? (VERSE_COUNTS[activeBookData.name]?.[selectedChapter - 1] || 20) 
    : 0;

  return (
    <div className={`fixed inset-y-0 left-0 transform ${isOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 lg:static lg:w-80 bg-white border-r border-stone-200 z-40 transition-transform duration-300 ease-in-out flex flex-col h-full shadow-2xl lg:shadow-none`}>
      <div className="p-6 border-b border-stone-100 bg-bible-paper">
        <div className="flex items-center justify-between mb-6">
           {view === 'books' ? (
             <div className="flex items-center justify-between w-full">
               <h2 className="text-2xl font-display font-bold text-bible-ink">Biblioteca</h2>
               <div className="flex items-center gap-1 bg-orange-50 px-3 py-1 rounded-full border border-orange-100" title="Días activos">
                 <span className="text-lg">🔥</span>
                 <span className="text-sm font-bold text-orange-600">{streak}</span>
               </div>
             </div>
           ) : (
             <div className="flex items-center gap-3">
               <button onClick={handleBack} className="p-2 rounded-full hover:bg-stone-100 text-stone-500 transition-colors">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg>
               </button>
               <h2 className="text-lg font-display font-bold text-bible-ink truncate max-w-[180px]">
                 {view === 'chapters' ? activeBookData?.name : `${activeBookData?.name} ${selectedChapter}`}
               </h2>
             </div>
           )}
        </div>

        <div className="grid grid-cols-2 gap-2 mb-6">
           <button onClick={() => handleNavClick('home')} className="p-2 text-[10px] font-bold rounded-xl bg-stone-100 hover:bg-bible-gold hover:text-white transition-all text-stone-600">🏠 Inicio</button>
           <button onClick={() => handleNavClick('reader')} className="p-2 text-[10px] font-bold rounded-xl bg-stone-100 hover:bg-bible-gold hover:text-white transition-all text-stone-600">📖 Biblia</button>
        </div>

        {view === 'books' && (
          <div className="relative">
            <input type="text" placeholder="Filtrar libro..." className="w-full px-4 py-2.5 rounded-xl bg-stone-100 border-none focus:ring-2 focus:ring-bible-gold outline-none text-sm font-sans" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4 absolute right-3 top-3 text-stone-400"><path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" /></svg>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6 bg-bible-paper custom-scrollbar">
        {view === 'books' && Object.entries(groupedBooks).map(([category, books]: any) => (
          <div key={category} className="mb-6">
            <h3 className="text-[10px] font-bold text-bible-accent uppercase tracking-[0.2em] mb-3 ml-2 opacity-70">{CATEGORY_LABELS[category]}</h3>
            <div className="grid grid-cols-1 gap-1">
              {books.map((book: any) => (
                <button key={book.name} onClick={() => handleBookClick(book.name)} className={`w-full text-left px-4 py-3 rounded-xl text-sm font-medium transition-all ${currentBook === book.name ? 'bg-bible-gold text-white shadow-lg' : 'text-stone-600 hover:bg-stone-50'}`}>{book.name}</button>
              ))}
            </div>
          </div>
        ))}

        {view === 'chapters' && activeBookData && (
          <div className="animate-fade-in"><p className="text-xs font-bold text-stone-400 uppercase tracking-widest mb-4 px-1">Capítulos:</p>
            <div className="grid grid-cols-4 gap-2">{Array.from({ length: activeBookData.chapters }, (_, i) => i + 1).map(chap => (
                <button key={chap} onClick={() => handleChapterClick(chap)} className="aspect-square flex items-center justify-center text-sm font-bold rounded-xl hover:bg-bible-gold hover:text-white transition-all bg-white border border-stone-100 text-stone-600 shadow-sm">{chap}</button>
              ))}</div>
          </div>
        )}

        {view === 'verses' && activeBookData && selectedChapter && (
           <div className="animate-fade-in">
              <button onClick={() => { onSelectChapter(selectedChapter); if (window.innerWidth < 1024) onClose(); }} className="w-full mb-6 py-4 bg-bible-leather text-white font-bold text-xs uppercase tracking-widest rounded-2xl hover:bg-bible-ink transition-all shadow-xl flex items-center justify-center gap-2">
                Leer Capítulo Completo
              </button>
              <div className="grid grid-cols-5 gap-2">{Array.from({ length: verseCount }, (_, i) => i + 1).map(verse => (
                  <button key={verse} onClick={() => handleVerseClick(verse)} className="aspect-square flex items-center justify-center text-[10px] font-bold rounded-lg hover:bg-bible-accent hover:text-white transition-all bg-white border border-stone-100 text-stone-500 shadow-sm">{verse}</button>
                ))}</div>
           </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Sidebar } from './components/Sidebar';
import { ContextPanel } from './components/ContextPanel';
import { NoteEditor } from './components/NoteEditor';
import { ChapterExplanation } from './components/ChapterExplanation';
import { HighlightableVerse } from './components/HighlightableVerse';
import { TextAudioPlayer } from './components/TextAudioPlayer';
import { MoodSelector } from './components/MoodSelector';
import { SavedContent } from './components/SavedContent';
import { StudyMode } from './components/StudyMode';
import { ShareableImage } from './components/ShareableImage';
import { ReadingGoalSelector } from './components/ReadingGoalSelector';
import { TheologyTutor } from './components/TheologyTutor';
import { getBibleChapter, getChronologicalPlan, searchBible, getDailyDevotional, getVersesByMood, getCrossReferences } from './services/geminiService';
import { ChapterResponse, LoadingState, ReadingPlanItem, SearchResult, DailyDevotional, Highlight, MoodResult, CrossReference, ReadingGoal } from './types';
import { BIBLE_BOOKS, CATEGORY_LABELS, VERSE_COUNTS } from './constants';

const getNoteKey = (book: string, chapter: number, verse: number) => `note-${book}-${chapter}-${verse}`;
const getHighlightKey = (book: string, chapter: number, verse: number) => `highlights-v2-${book}-${chapter}-${verse}`;

interface SelectionMenuPosition {
  top: number;
  left: number;
  verseNumber: number;
  range: Range;
}

function App() {
  const [currentBook, setCurrentBook] = useState<string>('');
  const [currentChapter, setCurrentChapter] = useState<number>(1);
  const [data, setData] = useState<ChapterResponse | null>(null);
  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isContextOpen, setContextOpen] = useState(false);
  const [viewMode, setViewMode] = useState<'home' | 'reader' | 'plan' | 'search' | 'devotional' | 'mood' | 'saved' | 'study'>('home');
  const [planMode, setPlanMode] = useState<'chrono' | 'time'>('chrono');
  const [scrollToVerse, setScrollToVerse] = useState<number | null>(null);
  const [chronoPlan, setChronoPlan] = useState<ReadingPlanItem[]>([]);
  const [loadingPlan, setLoadingPlan] = useState(false);
  const [devotional, setDevotional] = useState<DailyDevotional | null>(null);
  const [loadingDevotional, setLoadingDevotional] = useState(false);
  const [moodResults, setMoodResults] = useState<MoodResult[]>([]);
  const [loadingMood, setLoadingMood] = useState(false);
  const [selectedMood, setSelectedMood] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [userNotes, setUserNotes] = useState<Record<string, string>>({});
  const [editingNote, setEditingNote] = useState<string | null>(null); 
  const [verseHighlights, setVerseHighlights] = useState<Record<string, Highlight[]>>({});
  const [selectionMenu, setSelectionMenu] = useState<SelectionMenuPosition | null>(null);
  const [fontSize, setFontSize] = useState<number>(18); 
  const [lineHeight, setLineHeight] = useState<number>(1.625); 
  const [isImageCreatorOpen, setImageCreatorOpen] = useState(false);
  const [selectedVerseForAction, setSelectedVerseForAction] = useState<{number: number, text: string} | null>(null);
  const [crossRefs, setCrossRefs] = useState<CrossReference[]>([]);
  const [loadingRefs, setLoadingRefs] = useState(false);
  const [showRefsPanel, setShowRefsPanel] = useState(false);
  const [isReaderTutorOpen, setIsReaderTutorOpen] = useState(false);
  const [tutorTopic, setTutorTopic] = useState<string>('');
  const [playingVerse, setPlayingVerse] = useState<number | null>(null);
  const [audioActiveVerse, setAudioActiveVerse] = useState<number | null>(null);
  const [globalAudioCharIndex, setGlobalAudioCharIndex] = useState<number>(0);
  const [streakDays, setStreakDays] = useState(0);

  // Bible Browser State (Integrated Library)
  const [bibleBrowserView, setBibleBrowserView] = useState<'books' | 'chapters'>('books');

  const verseOffsets = useMemo(() => {
    if (!data) return [];
    let currentOffset = 0;
    return data.verses.map(v => {
        const start = currentOffset;
        const length = v.text.length;
        currentOffset += length + 1; 
        return { verse: v.number, start, end: start + length };
    });
  }, [data]);

  const handleAudioProgress = (charIndex: number) => {
     setGlobalAudioCharIndex(charIndex); 
     if (!verseOffsets.length) return;
     const match = verseOffsets.find(v => charIndex >= v.start && charIndex <= v.end);
     if (match && match.verse !== audioActiveVerse) {
        setAudioActiveVerse(match.verse);
        const el = document.getElementById(`verse-${match.verse}`);
        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
     }
  };

  useEffect(() => {
    const loadedNotes: Record<string, string> = {};
    const loadedHighlights: Record<string, Highlight[]> = {};
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key) {
        if (key.startsWith('note-')) loadedNotes[key] = localStorage.getItem(key) || '';
        else if (key.startsWith('highlights-v2-')) {
          try { loadedHighlights[key] = JSON.parse(localStorage.getItem(key) || '[]'); } catch (e) {}
        }
      }
    }
    setUserNotes(loadedNotes);
    setVerseHighlights(loadedHighlights);

    const today = new Date().toDateString();
    const lastVisit = localStorage.getItem('lastVisitDate');
    let streak = parseInt(localStorage.getItem('currentStreak') || '0');
    if (lastVisit !== today) {
        if (lastVisit) {
            const yesterday = new Date(); yesterday.setDate(yesterday.getDate() - 1);
            if (new Date(lastVisit).toDateString() === yesterday.toDateString()) streak += 1;
            else streak = 1;
        } else streak = 1;
        localStorage.setItem('lastVisitDate', today);
        localStorage.setItem('currentStreak', streak.toString());
    }
    setStreakDays(streak);
  }, []);

  const fetchChapter = async (book: string, chapter: number) => {
    setLoadingState(LoadingState.LOADING);
    setData(null);
    setAudioActiveVerse(null);
    setGlobalAudioCharIndex(0);
    // CRITICAL: Ensure Context Panel is closed by default per user request
    setContextOpen(false); 
    try {
      const result = await getBibleChapter(book, chapter);
      setData(result);
      setLoadingState(LoadingState.SUCCESS);
      setTutorTopic(`${result.metadata.book_name} Capítulo ${result.metadata.chapter_number}`);
    } catch (error) {
      setLoadingState(LoadingState.ERROR);
    }
  };

  const handleSelectBook = (book: string) => { 
    setCurrentBook(book); 
    setBibleBrowserView('chapters');
  };

  const handleSelectChapter = (chapter: number) => {
    setCurrentChapter(chapter);
    fetchChapter(currentBook, chapter);
    setSidebarOpen(false); 
    setViewMode('reader');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSelectVerse = (book: string, chapter: number, verse: number) => {
    if (currentBook === book && currentChapter === chapter && data) {
       setScrollToVerse(verse);
       setSidebarOpen(false);
       setViewMode('reader');
    } else {
       setCurrentBook(book); setCurrentChapter(chapter); setScrollToVerse(verse);
       fetchChapter(book, chapter); setSidebarOpen(false); setViewMode('reader');
    }
  };

  const handleGoHome = () => {
    setData(null); setLoadingState(LoadingState.IDLE); setViewMode('home');
    setCurrentBook(''); setCurrentChapter(1); setSearchQuery('');
    setBibleBrowserView('books');
    setSidebarOpen(false); setContextOpen(false);
  };

  const handleNavigate = (mode: 'home' | 'reader' | 'plan' | 'devotional' | 'mood' | 'saved' | 'study') => {
    if (mode === 'home') handleGoHome();
    else if (mode === 'reader') { 
      setViewMode('reader');
      if (!data) setBibleBrowserView('books');
    }
    else if (mode === 'plan') loadChronologicalPlan();
    else if (mode === 'devotional') loadDevotional();
    else if (mode === 'mood') loadMoodSelector();
    else if (mode === 'saved') { setViewMode('saved'); setSidebarOpen(false); }
    else if (mode === 'study') { setViewMode('study'); setSidebarOpen(false); }
  };

  const loadChronologicalPlan = async () => {
    setViewMode('plan'); setSidebarOpen(false);
    if (chronoPlan.length === 0) {
      setLoadingPlan(true);
      try { const plan = await getChronologicalPlan(); setChronoPlan(plan); } catch (e) {} finally { setLoadingPlan(false); }
    }
  };

  const loadDevotional = async () => {
    setViewMode('devotional'); setSidebarOpen(false);
    if (!devotional) {
      setLoadingDevotional(true);
      try { const result = await getDailyDevotional(); setDevotional(result); } catch (e) {} finally { setLoadingDevotional(false); }
    }
  };

  const loadMoodSelector = () => { setViewMode('mood'); setSidebarOpen(false); setSelectedMood(''); setMoodResults([]); };

  const handleSearch = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!searchQuery.trim()) return;
    setViewMode('search'); setSidebarOpen(false); setIsSearching(true); setSearchResults([]);
    try { const results = await searchBible(searchQuery); setSearchResults(results); } catch (error) {} finally { setIsSearching(false); }
  };

  const addHighlight = (color: string) => {
    if (!selectionMenu || !data) return;
    const { verseNumber, range } = selectionMenu;
    const selectedText = range.toString();
    const verseEl = document.querySelector(`[data-verse-number="${verseNumber}"]`);
    if (!verseEl) return;
    const preCaretRange = range.cloneRange();
    preCaretRange.selectNodeContents(verseEl);
    preCaretRange.setEnd(range.startContainer, range.startOffset);
    const start = preCaretRange.toString().length;
    const end = start + selectedText.length;
    const key = getHighlightKey(data.metadata.book_name, data.metadata.chapter_number, verseNumber);
    const updatedHighlights = [...(verseHighlights[key] || []), { id: Date.now().toString(), start, end, color, text: selectedText }];
    setVerseHighlights(prev => ({ ...prev, [key]: updatedHighlights }));
    localStorage.setItem(key, JSON.stringify(updatedHighlights));
    setSelectionMenu(null);
    window.getSelection()?.removeAllRanges();
  };

  const handlePlayVerse = (verseNumber: number, text: string) => {
    window.speechSynthesis.cancel();
    if (playingVerse === verseNumber) { setPlayingVerse(null); return; }
    setPlayingVerse(verseNumber);
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'es-ES';
    utterance.onend = () => setPlayingVerse(null);
    window.speechSynthesis.speak(utterance);
  };

  // Helper for Bible Browser (Integrated Library)
  const activeBookData = BIBLE_BOOKS.find(b => b.name === currentBook);

  return (
    <div className="flex h-screen bg-stone-100 overflow-hidden font-sans" onClick={(e) => {
        const target = e.target as HTMLElement;
        if (!target.closest('#highlight-menu') && (!window.getSelection() || window.getSelection()?.isCollapsed)) setSelectionMenu(null);
    }}>

      {selectionMenu && (
        <div id="highlight-menu" className="fixed z-50 bg-white rounded-full shadow-xl border border-stone-200 p-2 flex gap-2 animate-fade-in" style={{ top: selectionMenu.top, left: selectionMenu.left }}>
          {['yellow', 'green', 'blue', 'pink'].map(color => (
            <button key={color} onMouseDown={(e) => { e.preventDefault(); addHighlight(color); }} className={`w-8 h-8 rounded-full bg-${color}-400 hover:scale-110 transition-transform border border-stone-100`} />
          ))}
          <div className="w-px h-8 bg-stone-200 mx-1"></div>
          <button onMouseDown={(e) => { e.preventDefault(); 
             const key = getHighlightKey(data!.metadata.book_name, data!.metadata.chapter_number, selectionMenu.verseNumber);
             setVerseHighlights(prev => ({ ...prev, [key]: [] })); localStorage.removeItem(key); setSelectionMenu(null); window.getSelection()?.removeAllRanges();
          }} className="px-3 py-1 text-xs font-bold text-red-500 hover:bg-red-50 rounded-full">Borrar</button>
        </div>
      )}

      {isImageCreatorOpen && selectedVerseForAction && data && (
         <ShareableImage verseText={selectedVerseForAction.text} verseReference={`${data.metadata.book_name} ${data.metadata.chapter_number}:${selectedVerseForAction.number}`} onClose={() => setImageCreatorOpen(false)} />
      )}

      <Sidebar 
        currentBook={currentBook} 
        onSelectBook={handleSelectBook} 
        onSelectChapter={handleSelectChapter}
        onSelectVerse={handleSelectVerse}
        onNavigate={handleNavigate}
        isOpen={isSidebarOpen}
        onClose={() => setSidebarOpen(false)}
        streak={streakDays}
      />

      <div className="flex-1 flex flex-col h-full overflow-hidden relative">
        <header className="bg-white border-b border-stone-200 p-4 flex items-center justify-between lg:hidden shadow-sm z-30">
          <div className="flex items-center gap-2">
            <button onClick={handleGoHome} className="p-2 text-bible-leather flex items-center gap-1 bg-stone-100 rounded-full pr-3">
               <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg>
               <span className="text-xs font-bold">Inicio</span>
            </button>
          </div>

           <form onSubmit={handleSearch} className="flex-1 mx-2">
              <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Buscar en la Biblia..." className="w-full bg-stone-100 border-none rounded-full py-1.5 px-4 text-sm focus:ring-1 focus:ring-bible-gold outline-none" />
           </form>

          {data && viewMode === 'reader' && (
            <button onClick={() => setContextOpen(!isContextOpen)} className={`p-2 rounded-full transition-colors ${isContextOpen ? 'bg-bible-gold text-white' : 'text-bible-gold hover:bg-bible-gold/10'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 18v-5.25m0 0a6.001 6.001 0 00-5.304-7.618 6.002 6.002 0 019.957 5.304c.42 2.15-1.65 4.314-4.653 2.314zm0 0l-7.05 4.633a1.125 1.125 0 01-1.373-1.634l-.75-7.5M12 18l7.05 4.633a1.125 1.125 0 001.373-1.634l-.75-7.5" />
              </svg>
            </button>
          )}
        </header>

         <div className="hidden lg:flex items-center justify-between px-8 py-4 bg-white border-b border-stone-200">
             <div className="flex gap-4 items-center flex-1 overflow-x-auto">
                <button onClick={handleGoHome} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${viewMode === 'home' ? 'bg-bible-leather text-white shadow-sm' : 'text-stone-500 hover:bg-stone-100'}`}>Inicio</button>
                <button onClick={() => handleNavigate('reader')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${viewMode === 'reader' ? 'bg-bible-leather text-white shadow-sm' : 'text-stone-500 hover:bg-stone-100'}`}>Biblia</button>
                <button onClick={() => handleNavigate('plan')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${viewMode === 'plan' ? 'bg-bible-leather text-white shadow-sm' : 'text-stone-500 hover:bg-stone-100'}`}>Planes</button>
                <button onClick={() => handleNavigate('devotional')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${viewMode === 'devotional' ? 'bg-bible-leather text-white shadow-sm' : 'text-stone-500 hover:bg-stone-100'}`}>Devocional</button>
                <button onClick={() => handleNavigate('mood')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${viewMode === 'mood' ? 'bg-bible-leather text-white shadow-sm' : 'text-stone-500 hover:bg-stone-100'}`}>Sentimientos</button>
                <button onClick={() => handleNavigate('study')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${viewMode === 'study' ? 'bg-bible-leather text-white shadow-sm' : 'text-stone-500 hover:bg-stone-100'}`}>Estudios</button>
             </div>

             {data && viewMode === 'reader' && (
               <div className="flex items-center gap-4 ml-4">
                  <div className="flex items-center space-x-2 border-r border-stone-200 pr-4 text-stone-400">
                     <button onClick={() => setFontSize(s => Math.max(14, s - 2))} className="hover:text-bible-ink px-1 font-serif text-sm">A-</button>
                     <button onClick={() => setFontSize(s => Math.min(32, s + 2))} className="hover:text-bible-ink px-1 font-serif text-lg">A+</button>
                  </div>
                  <button 
                    onClick={() => setContextOpen(!isContextOpen)} 
                    className={`flex items-center gap-2 px-5 py-2.5 rounded-full transition-all border-2 ${isContextOpen ? 'bg-bible-gold border-bible-gold text-white shadow-lg' : 'bg-white border-bible-gold/30 text-bible-gold hover:border-bible-gold hover:bg-bible-gold/5'}`}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                      <path strokeLinecap="round" strokeLinejoin="round" d="M12 18v-5.25m0 0a6.001 6.001 0 00-5.304-7.618 6.002 6.002 0 019.957 5.304c.42 2.15-1.65 4.314-4.653 2.314zm0 0l-7.05 4.633a1.125 1.125 0 01-1.373-1.634l-.75-7.5M12 18l7.05 4.633a1.125 1.125 0 001.373-1.634l-.75-7.5" />
                    </svg>
                    <span className="text-xs font-bold uppercase tracking-widest">Análisis Contextual</span>
                  </button>
               </div>
             )}
         </div>

        <div id="bible-content-area" className="flex-1 overflow-y-auto bg-bible-paper p-4 lg:p-12 relative scroll-smooth">

          {viewMode === 'home' && (
             <div className="max-w-5xl mx-auto py-6 animate-fade-in">
                <div className="text-center mb-16">
                   <div className="w-28 h-28 bg-bible-leather rounded-full flex items-center justify-center mx-auto mb-8 shadow-2xl border-4 border-bible-gold/20 transform hover:rotate-12 transition-transform duration-500">
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-16 h-16 text-bible-gold">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" />
                      </svg>
                   </div>
                   <h1 className="text-6xl md:text-7xl font-display font-bold text-bible-ink mb-4 tracking-tighter">ABBA BIBLIA</h1>
                   <p className="text-stone-500 text-xl max-w-2xl mx-auto italic font-serif leading-relaxed opacity-80">"Tu palabra es una lámpara que guía mis pies y una luz para mi camino." <br/><span className="text-bible-accent not-italic font-sans text-xs font-bold uppercase tracking-[0.4em] mt-3 block">— SALMOS 119:105</span></p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6 lg:gap-10">
                   {[
                      { mode: 'reader', label: 'Explorar Biblia', sub: 'Lectura y Contexto', icon: '📖', color: 'from-amber-100 to-orange-50' },
                      { mode: 'devotional', label: 'Devocional', sub: 'Palabra del Día', icon: '🙏', color: 'from-emerald-100 to-teal-50' },
                      { mode: 'plan', label: 'Planes', sub: 'Ruta de Lectura', icon: '📅', color: 'from-blue-100 to-indigo-50' },
                      { mode: 'study', label: 'Estudios', sub: 'Teología y Quizzes', icon: '🎓', color: 'from-purple-100 to-fuchsia-50' },
                      { mode: 'mood', label: 'Guía Espiritual', sub: 'Según tu Sentir', icon: '❤️', color: 'from-rose-100 to-red-50' },
                      { mode: 'saved', label: 'Mis Notas', sub: 'Favoritos y Marcas', icon: '🔖', color: 'from-stone-200 to-stone-50' },
                   ].map((item: any) => (
                      <button 
                        key={item.mode} 
                        onClick={() => handleNavigate(item.mode)} 
                        className={`bg-gradient-to-br ${item.color} p-8 rounded-[2rem] shadow-sm border border-black/5 hover:shadow-2xl hover:-translate-y-2 transition-all flex flex-col items-center text-center group relative overflow-hidden h-full`}
                      >
                         <span className="text-5xl mb-5 group-hover:scale-125 transition-transform duration-500 block">{item.icon}</span>
                         <h3 className="text-xl font-display font-bold text-bible-ink mb-1">{item.label}</h3>
                         <p className="text-stone-500 text-[10px] font-bold uppercase tracking-widest opacity-70">{item.sub}</p>
                         <div className="absolute -bottom-4 -right-4 w-16 h-16 bg-black/5 rounded-full group-hover:scale-150 transition-transform duration-700"></div>
                      </button>
                   ))}
                </div>

                <div className="mt-16 bg-white/40 backdrop-blur-sm border border-stone-200 p-12 rounded-[3rem] text-center shadow-inner">
                   <h2 className="text-3xl font-display font-bold text-bible-ink mb-3">Retoma tu Estudio</h2>
                   <p className="text-stone-500 mb-10 text-sm max-w-sm mx-auto">Continúa explorando las profundidades de las Escrituras con análisis teológico.</p>
                   <button onClick={() => handleNavigate('reader')} className="bg-bible-leather text-white px-14 py-4 rounded-full font-bold shadow-2xl hover:bg-bible-ink hover:scale-105 active:scale-95 transition-all text-xs tracking-[0.2em] uppercase">Elegir un Libro</button>
                </div>
             </div>
          )}

          {viewMode === 'reader' && (
            <div className="max-w-4xl mx-auto">
              {/* Integrated Bible Browser (Previously Library) */}
              {loadingState === LoadingState.IDLE && (
                 <div className="animate-fade-in py-6">
                    <div className="flex items-center justify-between mb-10 border-b border-stone-200 pb-6">
                       <div>
                          <h1 className="text-4xl font-display font-bold text-bible-ink">Biblia Sagrada</h1>
                          <p className="text-stone-500 text-sm">Selecciona un libro para comenzar el análisis.</p>
                       </div>
                       {bibleBrowserView === 'chapters' && (
                          <button 
                            onClick={() => setBibleBrowserView('books')}
                            className="flex items-center gap-2 text-bible-leather font-bold text-sm bg-stone-100 px-4 py-2 rounded-full hover:bg-stone-200"
                          >
                             &larr; Ver Libros
                          </button>
                       )}
                    </div>

                    {bibleBrowserView === 'books' ? (
                       <div className="space-y-12">
                          {Object.entries(CATEGORY_LABELS).map(([catId, label]) => {
                             const booksInCategory = BIBLE_BOOKS.filter(b => b.category === catId);
                             if (booksInCategory.length === 0) return null;
                             return (
                                <div key={catId}>
                                   <h3 className="text-xs font-bold text-bible-accent uppercase tracking-[0.3em] mb-6 pl-2 border-l-4 border-bible-gold">{label}</h3>
                                   <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3">
                                      {booksInCategory.map(book => (
                                         <button 
                                           key={book.name}
                                           onClick={() => handleSelectBook(book.name)}
                                           className="p-4 bg-white border border-stone-200 rounded-2xl text-left hover:border-bible-gold hover:shadow-lg transition-all group"
                                         >
                                            <span className="block text-stone-800 font-bold group-hover:text-bible-leather transition-colors">{book.name}</span>
                                            <span className="text-[10px] text-stone-400 font-bold uppercase tracking-widest">{book.chapters} caps</span>
                                         </button>
                                      ))}
                                   </div>
                                </div>
                             )
                          })}
                       </div>
                    ) : (
                       <div className="animate-fade-in text-center">
                          <h2 className="text-5xl font-display font-bold text-bible-ink mb-2">{activeBookData?.name}</h2>
                          <p className="text-stone-500 mb-10">Selecciona el capítulo que deseas estudiar:</p>
                          <div className="grid grid-cols-4 sm:grid-cols-6 md:grid-cols-8 lg:grid-cols-10 gap-3">
                             {Array.from({ length: activeBookData?.chapters || 0 }, (_, i) => i + 1).map(chap => (
                                <button
                                  key={chap}
                                  onClick={() => handleSelectChapter(chap)}
                                  className="aspect-square flex items-center justify-center text-lg font-bold rounded-2xl bg-white border border-stone-200 text-stone-600 hover:bg-bible-leather hover:text-white hover:border-bible-leather hover:shadow-xl transition-all"
                                >
                                   {chap}
                                </button>
                             ))}
                          </div>
                       </div>
                    )}
                 </div>
              )}

              {loadingState === LoadingState.LOADING && ( <div className="space-y-8 animate-pulse pt-20"><div className="h-16 bg-stone-200 rounded-3xl w-1/3 mx-auto"></div><div className="space-y-4 mt-16"><div className="h-4 bg-stone-200 rounded-full w-full"></div><div className="h-4 bg-stone-200 rounded-full w-5/6"></div></div></div> )}

              {loadingState === LoadingState.SUCCESS && data && (
                <div className="animate-fade-in pb-32 relative">
                  <div className="text-center mb-12">
                    <span className="text-bible-accent uppercase tracking-[0.4em] text-[10px] font-bold mb-4 block">Capítulo {data.metadata.chapter_number}</span>
                    <h1 className="text-5xl lg:text-7xl font-display font-bold text-bible-ink leading-tight">{data.metadata.book_name}</h1>
                  </div>

                  <div className="mb-12 max-w-xl mx-auto sticky top-0 z-20 shadow-2xl rounded-[2rem] overflow-hidden bg-white/90 backdrop-blur-md border border-stone-200">
                    <TextAudioPlayer text={data.verses.map(v => v.text).join(' ')} title="Narración Bíblica" className="border-none" showText={false} onBoundary={handleAudioProgress} />
                  </div>

                  <div className="space-y-10">
                    {data.verses.map((verse) => {
                      const noteKey = getNoteKey(data.metadata.book_name, data.metadata.chapter_number, verse.number);
                      const highlightKey = getHighlightKey(data.metadata.book_name, data.metadata.chapter_number, verse.number);
                      const note = userNotes[noteKey];
                      const currentVerseHighlights = verseHighlights[highlightKey] || [];
                      const isEditing = editingNote === noteKey;
                      const isAudioActive = audioActiveVerse === verse.number;
                      let activeCharIndexForVerse = null;
                      if (isAudioActive) {
                          const offsetData = verseOffsets.find(v => v.verse === verse.number);
                          if (offsetData) {
                              const localIndex = globalAudioCharIndex - offsetData.start;
                              if (localIndex >= 0 && localIndex <= (offsetData.end - offsetData.start)) activeCharIndexForVerse = localIndex;
                          }
                      }
                      return (
                        <div id={`verse-${verse.number}`} key={verse.number} className={`relative group transition-all duration-700 rounded-2xl p-4 -mx-4 ${isAudioActive ? 'bg-bible-gold/10 border-l-4 border-bible-gold shadow-sm' : 'border-l-4 border-transparent'}`} data-verse-number={verse.number}>
                          <div className="absolute -left-10 lg:-left-12 top-4 flex flex-col items-end gap-2 w-10 z-10">
                             <span className={`text-xs font-bold font-sans select-none mb-1 transition-all ${isAudioActive ? 'text-bible-gold scale-150' : 'text-bible-gold/30'}`}>{verse.number}</span>
                             <div className={`flex flex-col gap-2 transition-opacity duration-300 ${note ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                                <button onClick={() => setEditingNote(isEditing ? null : noteKey)} className={`p-1.5 rounded-full ${note ? 'text-yellow-600 bg-yellow-50 shadow-sm' : 'text-stone-300 hover:text-bible-accent hover:bg-stone-100'}`} title="Nota"><svg xmlns="http://www.w3.org/2000/svg" fill={note ? "currentColor" : "none"} viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path d="M16.862 4.487l1.687-1.688a1.875 1.875 0 112.652 2.652L10.582 16.07a4.5 4.5 0 01-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 011.13-1.897l8.932-8.931zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0115.75 21H5.25A2.25 2.25 0 013 18.75V8.25A2.25 2.25 0 015.25 6H10" /></svg></button>
                                <button onClick={() => handlePlayVerse(verse.number, verse.text)} className={`p-1.5 rounded-full ${playingVerse === verse.number ? 'text-bible-gold bg-white shadow-sm' : 'text-stone-300 hover:text-green-500 hover:bg-stone-100'}`} title="Oír">{playingVerse === verse.number ? '🔊' : <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path d="M19.114 5.636a9 9 0 010 12.728M16.463 8.288a5.25 5.25 0 010 7.424M6.75 8.25l4.72-4.72a.75.75 0 011.28.53v15.88a.75.75 0 01-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 012.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75z" /></svg>}</button>
                             </div>
                          </div>
                          <div className="rounded-lg px-2"><HighlightableVerse text={verse.text} highlights={currentVerseHighlights} fontSize={fontSize} lineHeight={lineHeight} activeCharIndex={activeCharIndexForVerse} /></div>
                          {isEditing && ( <NoteEditor initialNote={note || ''} onSave={(c) => { localStorage.setItem(noteKey, c); setUserNotes(prev => ({ ...prev, [noteKey]: c })); setEditingNote(null); }} onCancel={() => setEditingNote(null)} onDelete={() => { localStorage.removeItem(noteKey); setUserNotes(p => { const n = {...p}; delete n[noteKey]; return n; }); setEditingNote(null); }} /> )}
                          {!isEditing && note && ( <div onClick={() => setEditingNote(noteKey)} className="ml-4 lg:ml-10 mb-8 p-5 bg-yellow-50 rounded-[1.5rem] border-l-4 border-yellow-400 cursor-pointer hover:bg-yellow-100 transition-colors shadow-sm relative"><div className="absolute -top-3 -left-2 text-2xl">💡</div><p className="font-handwriting text-stone-800 text-sm italic leading-relaxed">"{note}"</p></div> )}
                        </div>
                      );
                    })}
                  </div>

                  <div className="mt-20 pt-12 border-t border-stone-200"><ChapterExplanation explanation={data.metadata.detailed_explanation} /></div>
                  <div className="mt-16 flex justify-center"><button onClick={() => handleSelectChapter(currentChapter + 1)} className="px-14 py-5 bg-bible-leather text-white rounded-full hover:bg-bible-ink transition-all font-display shadow-2xl hover:scale-105 active:scale-95 text-xs tracking-widest uppercase">Siguiente Capítulo</button></div>
