                  <div className="bg-white p-12 rounded-[3rem] shadow-2xl border-t-[12px] border-bible-gold text-center relative overflow-hidden"><div className="absolute top-4 left-4 text-stone-100 text-8xl font-serif">"</div><h2 className="text-4xl font-serif text-bible-ink leading-relaxed mb-8 italic relative z-10">"{devotional.verseText}"</h2><p className="text-bible-accent font-bold tracking-[0.4em] uppercase text-[10px]">{devotional.verseReference}</p></div>
                  <div className="bg-white p-10 rounded-[2.5rem] shadow-sm border border-stone-100"><TextAudioPlayer text={devotional.reflection} title="Reflexión Espiritual" /></div>
                </div>
               ) : ( <div className="text-center py-20"><button onClick={loadDevotional} className="px-12 py-5 bg-bible-gold text-white rounded-full font-bold shadow-2xl hover:scale-105 transition-all text-xs tracking-widest">DESCUBRIR PALABRA DE HOY</button></div> )}
