                <button onClick={() => handleNavigate('study')} className={`px-4 py-2 rounded-full text-sm font-bold transition-all ${viewMode === 'study' ? 'bg-bible-leather text-white shadow-sm' : 'text-stone-500 hover:bg-stone-100'}`}>Estudios</button>
             </div>

             {data && viewMode === 'reader' && (
               <div className="flex items-center gap-4 ml-4">
                  <div className="flex items-center space-x-2 border-r border-stone-200 pr-4 text-stone-400">
