                      { mode: 'devotional', label: 'Devocional', sub: 'Palabra del Día', icon: '🙏', color: 'from-emerald-100 to-teal-50' },
                      { mode: 'plan', label: 'Planes', sub: 'Ruta de Lectura', icon: '📅', color: 'from-blue-100 to-indigo-50' },
                      { mode: 'study', label: 'Estudios', sub: 'Teología y Quizzes', icon: '🎓', color: 'from-purple-100 to-fuchsia-50' },
