          {viewMode === 'saved' && ( <SavedContent onNavigateToVerse={handleSelectVerse} onDeleteItem={(k) => { localStorage.removeItem(k); handleNavigate('saved'); }} /> )}
          {viewMode === 'study' && ( <StudyMode /> )}
          {viewMode === 'mood' && (
             <div className="max-w-4xl mx-auto pt-4 lg:pt-8">
                {selectedMood ? (
                   <div className="animate-fade-in">
                      <div className="flex items-center gap-2 mb-10 border-b border-stone-200 pb-6">
                        <button onClick={() => { setSelectedMood(''); setMoodResults([]); }} className="text-stone-500 hover:text-bible-gold transition-colors"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-7 h-7"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg></button>
                        <h3 className="text-3xl font-bold text-bible-ink">Versículos para: <span className="text-bible-accent italic">{selectedMood}</span></h3>
                      </div>
                      <div className="space-y-10 pb-20">{moodResults.map((item, idx) => (<div key={idx} className="bg-white p-10 rounded-[3rem] shadow-sm border border-stone-100 hover:shadow-2xl transition-all"><h4 className="font-bold text-bible-leather mb-3 text-xl">{item.verseReference}</h4><p className="font-serif text-3xl text-bible-ink mb-8 italic">"{item.text}"</p><div className="text-base text-stone-600 bg-stone-50 p-8 rounded-3xl border border-stone-100 leading-relaxed font-serif text-justify">{item.explanation}</div></div>))}</div>
                   </div>
                ) : ( <MoodSelector onSelectMood={async (m) => { setSelectedMood(m); setLoadingMood(true); const r = await getVersesByMood(m); setMoodResults(r); setLoadingMood(false); }} /> )}
             </div>
          )}
          {viewMode === 'plan' && ( <div className="max-w-4xl mx-auto"><div className="text-center mb-14 font-display font-bold text-5xl text-bible-ink">Ruta de Lectura</div><ReadingGoalSelector onSelect={() => {}} /></div> )}
          {viewMode === 'devotional' && (
            <div className="max-w-3xl mx-auto pt-8 animate-fade-in">
               <div className="text-center mb-14"><h1 className="text-5xl font-display font-bold text-bible-ink mb-2">Devocional</h1><p className="text-stone-500 font-bold uppercase tracking-[0.3em] text-[10px]">{new Date().toLocaleDateString('es-ES', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p></div>
               {loadingDevotional ? ( <div className="h-80 bg-white rounded-[4rem] animate-pulse"></div> ) : devotional ? (
                <div className="space-y-12 pb-20 animate-fade-in-up">
                  <div className="bg-white p-16 rounded-[4rem] shadow-2xl border-t-[14px] border-bible-gold text-center relative overflow-hidden"><div className="absolute top-4 left-4 text-stone-100 text-9xl font-serif select-none">"</div><h2 className="text-4xl lg:text-5xl font-serif text-bible-ink leading-tight mb-10 italic relative z-10">"{devotional.verseText}"</h2><p className="text-bible-accent font-bold tracking-[0.5em] uppercase text-xs">{devotional.verseReference}</p></div>
                  <div className="bg-white p-12 rounded-[3rem] shadow-sm border border-stone-100"><TextAudioPlayer text={devotional.reflection} title="Reflexión Pastoral" /></div>
                </div>
               ) : ( <div className="text-center py-24"><button onClick={loadDevotional} className="px-16 py-6 bg-bible-gold text-white rounded-full font-bold shadow-2xl hover:scale-105 active:scale-95 transition-all text-xs tracking-[0.3em]">RECIBIR PALABRA DE HOY</button></div> )}
            </div>
          )}
        </div>
      </div>

      <ContextPanel metadata={data ? data.metadata : null} isOpen={isContextOpen} onClose={() => setContextOpen(false)} isLoading={loadingState === LoadingState.LOADING} />
      <TheologyTutor topic={tutorTopic} isOpen={isReaderTutorOpen} onClose={() => setIsReaderTutorOpen(false)} />
    </div>
  );
}

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { BIBLE_BOOKS, CATEGORY_LABELS, VERSE_COUNTS } from '../constants';
import { BibleBook } from '../types';

interface SidebarProps {
  currentBook: string;
  onSelectBook: (bookName: string) => void;
  onSelectChapter: (chapter: number) => void;
  onSelectVerse: (book: string, chapter: number, verse: number) => void;
  onNavigate: (view: 'home' | 'reader' | 'plan' | 'devotional' | 'mood' | 'saved' | 'study') => void;
  isOpen: boolean;
  onClose: () => void;
  streak?: number;
}

type SidebarView = 'books' | 'chapters' | 'verses';

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentBook, onSelectBook, onSelectChapter, onSelectVerse, onNavigate, isOpen, onClose, streak = 0 
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [view, setView] = useState<SidebarView>('books');
  const [selectedChapter, setSelectedChapter] = useState<number | null>(null);

  useEffect(() => {
    if (currentBook) {
      if (view === 'books') setView('chapters');
    } else {
      setView('books');
      setSelectedChapter(null);
    }
  }, [currentBook]);

  const groupedBooks = useMemo<Record<string, BibleBook[]>>(() => {
    const filtered = BIBLE_BOOKS.filter(b => b.name.toLowerCase().includes(searchTerm.toLowerCase()));
    const groups: Record<string, BibleBook[]> = {};
    filtered.forEach(book => {
      if (!groups[book.category]) groups[book.category] = [];
      groups[book.category].push(book);
    });
    return groups;
  }, [searchTerm]);

  const activeBookData = BIBLE_BOOKS.find(b => b.name === currentBook);

  const handleBookClick = (bookName: string) => {
    onSelectBook(bookName);
    setView('chapters');
    setSelectedChapter(null);
    setSearchTerm('');
  };

  const handleChapterClick = (chapter: number) => {
    setSelectedChapter(chapter);
    setView('verses');
  };

  const handleVerseClick = (verse: number) => {
    if (activeBookData && selectedChapter) {
      onSelectVerse(activeBookData.name, selectedChapter, verse);
      if (window.innerWidth < 1024) onClose();
    }
  };

  const handleBack = () => {
    if (view === 'verses') { setView('chapters'); setSelectedChapter(null); }
    else if (view === 'chapters') { setView('books'); onSelectBook(''); }
  };

  const handleNavClick = (viewMode: any) => {
    if (viewMode === 'reader' || viewMode === 'home') { setView('books'); onSelectBook(''); }
    onNavigate(viewMode);
    if (window.innerWidth < 1024) onClose();
  };

  const verseCount = (activeBookData && selectedChapter) 
    ? (VERSE_COUNTS[activeBookData.name]?.[selectedChapter - 1] || 20) 
    : 0;

  return (
    <div className={`fixed inset-y-0 left-0 transform ${isOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 lg:static lg:w-80 bg-white border-r border-stone-200 z-40 transition-transform duration-300 ease-in-out flex flex-col h-full shadow-2xl lg:shadow-none`}>
      <div className="p-6 border-b border-stone-100 bg-bible-paper">
        <div className="flex items-center justify-between mb-8">
           {view === 'books' ? (
             <div className="flex items-center justify-between w-full">
               <h2 className="text-2xl font-display font-bold text-bible-ink">Navegación</h2>
               <div className="flex items-center gap-1 bg-orange-50 px-3 py-1 rounded-full border border-orange-100" title="Racha espiritual">
                 <span className="text-lg">🔥</span>
                 <span className="text-sm font-bold text-orange-600">{streak}</span>
               </div>
             </div>
           ) : (
             <div className="flex items-center gap-3">
               <button onClick={handleBack} className="p-2.5 rounded-full hover:bg-stone-100 text-stone-500 transition-all">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg>
               </button>
               <h2 className="text-lg font-display font-bold text-bible-ink truncate max-w-[180px]">
                 {view === 'chapters' ? activeBookData?.name : `${activeBookData?.name} ${selectedChapter}`}
               </h2>
             </div>
           )}
        </div>

        <div className="flex flex-col gap-2 mb-8">
           <button onClick={() => handleNavClick('home')} className="flex items-center gap-3 w-full p-3.5 text-xs font-bold rounded-2xl bg-stone-100 hover:bg-bible-gold hover:text-white transition-all text-stone-600 uppercase tracking-widest shadow-sm">
             <span>🏠</span> Inicio
           </button>
           <button onClick={() => handleNavClick('reader')} className="flex items-center gap-3 w-full p-3.5 text-xs font-bold rounded-2xl bg-bible-leather text-white hover:bg-bible-ink transition-all uppercase tracking-widest shadow-md">
             <span>📖</span> Biblia Sagrada
           </button>
        </div>

        <div className="grid grid-cols-2 gap-2 mb-8">
           <button onClick={() => handleNavClick('plan')} className="p-2 text-[10px] font-bold rounded-xl bg-stone-50 hover:bg-stone-200 text-stone-600 uppercase tracking-widest">Planes</button>
           <button onClick={() => handleNavClick('devotional')} className="p-2 text-[10px] font-bold rounded-xl bg-stone-50 hover:bg-stone-200 text-stone-600 uppercase tracking-widest">Diario</button>
           <button onClick={() => handleNavClick('study')} className="p-2 text-[10px] font-bold rounded-xl bg-stone-50 hover:bg-stone-200 text-stone-600 uppercase tracking-widest">Estudios</button>
           <button onClick={() => handleNavClick('saved')} className="p-2 text-[10px] font-bold rounded-xl bg-stone-50 hover:bg-stone-200 text-stone-600 uppercase tracking-widest">Mis Notas</button>
        </div>

        {view === 'books' && (
          <div className="relative">
            <input type="text" placeholder="Buscar libro..." className="w-full px-5 py-3.5 rounded-2xl bg-stone-100 border-none focus:ring-2 focus:ring-bible-gold outline-none text-sm font-sans" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4 absolute right-4 top-4 text-stone-400"><path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" /></svg>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-y-auto p-5 space-y-6 bg-bible-paper custom-scrollbar">
        {view === 'books' && Object.entries(groupedBooks).map(([category, books]: any) => (
          <div key={category} className="mb-8">
            <h3 className="text-[10px] font-bold text-bible-accent uppercase tracking-[0.4em] mb-4 ml-2 opacity-60">{CATEGORY_LABELS[category]}</h3>
            <div className="grid grid-cols-1 gap-1.5">
              {books.map((book: any) => (
                <button key={book.name} onClick={() => handleBookClick(book.name)} className={`w-full text-left px-5 py-4 rounded-2xl text-sm font-medium transition-all ${currentBook === book.name ? 'bg-bible-leather text-white shadow-xl scale-[1.02]' : 'text-stone-600 hover:bg-stone-50 hover:pl-6'}`}>{book.name}</button>
              ))}
            </div>
          </div>
        ))}

        {view === 'chapters' && activeBookData && (
          <div className="animate-fade-in">
            <h3 className="text-[10px] font-bold text-stone-400 uppercase tracking-widest mb-6 px-2">Selecciona Capítulo:</h3>
            <div className="grid grid-cols-4 gap-3">{Array.from({ length: activeBookData.chapters }, (_, i) => i + 1).map(chap => (
                <button key={chap} onClick={() => handleChapterClick(chap)} className="aspect-square flex items-center justify-center text-sm font-bold rounded-2xl hover:bg-bible-gold hover:text-white transition-all bg-white border border-stone-100 text-stone-600 shadow-sm">{chap}</button>
              ))}</div>
          </div>
        )}

        {view === 'verses' && activeBookData && selectedChapter && (
           <div className="animate-fade-in">
              <button onClick={() => { onSelectChapter(selectedChapter); if (window.innerWidth < 1024) onClose(); }} className="w-full mb-8 py-5 bg-bible-leather text-white font-bold text-[11px] uppercase tracking-[0.3em] rounded-[2rem] hover:bg-bible-ink transition-all shadow-2xl flex items-center justify-center gap-2">
                Lectura Completa
              </button>
              <h3 className="text-[10px] font-bold text-stone-400 uppercase tracking-widest mb-6 px-2">Salto a Versículo:</h3>
              <div className="grid grid-cols-5 gap-2.5">{Array.from({ length: verseCount }, (_, i) => i + 1).map(verse => (
                  <button key={verse} onClick={() => handleVerseClick(verse)} className="aspect-square flex items-center justify-center text-[11px] font-bold rounded-xl hover:bg-bible-accent hover:text-white transition-all bg-white border border-stone-100 text-stone-500 shadow-sm">{verse}</button>
                ))}</div>
           </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Sidebar } from './components/Sidebar';
import { ContextPanel } from './components/ContextPanel';
import { NoteEditor } from './components/NoteEditor';
import { ChapterExplanation } from './components/ChapterExplanation';
import { HighlightableVerse } from './components/HighlightableVerse';
import { TextAudioPlayer } from './components/TextAudioPlayer';
import { MoodSelector } from './components/MoodSelector';
import { SavedContent } from './components/SavedContent';
import { StudyMode } from './components/StudyMode';
import { ShareableImage } from './components/ShareableImage';
import { ReadingGoalSelector } from './components/ReadingGoalSelector';
import { TheologyTutor } from './components/TheologyTutor';
import { getBibleChapter, getChronologicalPlan, searchBible, getDailyDevotional, getVersesByMood, getCrossReferences } from './services/geminiService';
import { ChapterResponse, LoadingState, ReadingPlanItem, SearchResult, DailyDevotional, Highlight, MoodResult, CrossReference } from './types';
import { BIBLE_BOOKS, CATEGORY_LABELS } from './constants';

const getNoteKey = (book: string, chapter: number, verse: number) => `note-${book}-${chapter}-${verse}`;
const getHighlightKey = (book: string, chapter: number, verse: number) => `highlights-v2-${book}-${chapter}-${verse}`;

interface SelectionMenuPosition {
  top: number;
  left: number;
  verseNumber: number;
  range: Range;
}

function App() {
  const [currentBook, setCurrentBook] = useState<string>('');
  const [currentChapter, setCurrentChapter] = useState<number>(1);
  const [data, setData] = useState<ChapterResponse | null>(null);
  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isContextOpen, setContextOpen] = useState(false);
  const [viewMode, setViewMode] = useState<'home' | 'reader' | 'plan' | 'search' | 'devotional' | 'mood' | 'saved' | 'study'>('home');
  const [scrollToVerse, setScrollToVerse] = useState<number | null>(null);
  const [chronoPlan, setChronoPlan] = useState<ReadingPlanItem[]>([]);
  const [loadingPlan, setLoadingPlan] = useState(false);
  const [devotional, setDevotional] = useState<DailyDevotional | null>(null);
  const [loadingDevotional, setLoadingDevotional] = useState(false);
  const [moodResults, setMoodResults] = useState<MoodResult[]>([]);
  const [loadingMood, setLoadingMood] = useState(false);
  const [selectedMood, setSelectedMood] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [userNotes, setUserNotes] = useState<Record<string, string>>({});
  const [editingNote, setEditingNote] = useState<string | null>(null); 
  const [verseHighlights, setVerseHighlights] = useState<Record<string, Highlight[]>>({});
  const [selectionMenu, setSelectionMenu] = useState<SelectionMenuPosition | null>(null);
  const [fontSize, setFontSize] = useState<number>(18); 
  const [lineHeight, setLineHeight] = useState<number>(1.625); 
  const [isImageCreatorOpen, setImageCreatorOpen] = useState(false);
  const [selectedVerseForAction, setSelectedVerseForAction] = useState<{number: number, text: string} | null>(null);
  const [isReaderTutorOpen, setIsReaderTutorOpen] = useState(false);
  const [tutorTopic, setTutorTopic] = useState<string>('');
  const [playingVerse, setPlayingVerse] = useState<number | null>(null);
  const [audioActiveVerse, setAudioActiveVerse] = useState<number | null>(null);
  const [globalAudioCharIndex, setGlobalAudioCharIndex] = useState<number>(0);
  const [streakDays, setStreakDays] = useState(0);
  const [bibleBrowserView, setBibleBrowserView] = useState<'books' | 'chapters'>('books');

  const verseOffsets = useMemo(() => {
    if (!data) return [];
    let currentOffset = 0;
    return data.verses.map(v => {
        const start = currentOffset;
        const length = v.text.length;
        currentOffset += length + 1; 
        return { verse: v.number, start, end: start + length };
    });
  }, [data]);

  const handleAudioProgress = (charIndex: number) => {
     setGlobalAudioCharIndex(charIndex); 
     if (!verseOffsets.length) return;
     const match = verseOffsets.find(v => charIndex >= v.start && charIndex <= v.end);
     if (match && match.verse !== audioActiveVerse) {
        setAudioActiveVerse(match.verse);
        const el = document.getElementById(`verse-${match.verse}`);
        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
     }
  };

  useEffect(() => {
    const loadedNotes: Record<string, string> = {};
    const loadedHighlights: Record<string, Highlight[]> = {};
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key) {
        if (key.startsWith('note-')) loadedNotes[key] = localStorage.getItem(key) || '';
        else if (key.startsWith('highlights-v2-')) {
          try { loadedHighlights[key] = JSON.parse(localStorage.getItem(key) || '[]'); } catch (e) {}
        }
      }
    }
    setUserNotes(loadedNotes);
    setVerseHighlights(loadedHighlights);

    const today = new Date().toDateString();
    const lastVisit = localStorage.getItem('lastVisitDate');
    let streak = parseInt(localStorage.getItem('currentStreak') || '0');
    if (lastVisit !== today) {
        if (lastVisit) {
            const yesterday = new Date(); yesterday.setDate(yesterday.getDate() - 1);
            if (new Date(lastVisit).toDateString() === yesterday.toDateString()) streak += 1;
            else streak = 1;
        } else streak = 1;
        localStorage.setItem('lastVisitDate', today);
        localStorage.setItem('currentStreak', streak.toString());
    }
    setStreakDays(streak);
  }, []);

  const fetchChapter = async (book: string, chapter: number) => {
    setLoadingState(LoadingState.LOADING);
    setData(null);
    setAudioActiveVerse(null);
    setGlobalAudioCharIndex(0);
    setContextOpen(false); 
    try {
      const result = await getBibleChapter(book, chapter);
      setData(result);
      setLoadingState(LoadingState.SUCCESS);
      setTutorTopic(`${result.metadata.book_name} Capítulo ${result.metadata.chapter_number}`);
    } catch (error) {
      setLoadingState(LoadingState.ERROR);
    }
  };

  const handleSelectBook = (book: string) => { 
    setCurrentBook(book); 
    setBibleBrowserView('chapters');
  };

  const handleSelectChapter = (chapter: number) => {
    setCurrentChapter(chapter);
    fetchChapter(currentBook, chapter);
    setSidebarOpen(false); 
    setViewMode('reader');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSelectVerse = (book: string, chapter: number, verse: number) => {
    if (currentBook === book && currentChapter === chapter && data) {
       setScrollToVerse(verse);
       setSidebarOpen(false);
       setViewMode('reader');
    } else {
       setCurrentBook(book); setCurrentChapter(chapter); setScrollToVerse(verse);
       fetchChapter(book, chapter); setSidebarOpen(false); setViewMode('reader');
    }
  };

  const handleGoHome = () => {
    setData(null); setLoadingState(LoadingState.IDLE); setViewMode('home');
    setCurrentBook(''); setCurrentChapter(1); setSearchQuery('');
    setBibleBrowserView('books');
    setSidebarOpen(false); setContextOpen(false);
  };

  const handleNavigate = (mode: 'reader' | 'plan' | 'devotional' | 'mood' | 'saved' | 'study') => {
    if (mode === 'reader') { 
      setViewMode('reader');
      if (!data) setBibleBrowserView('books');
    }
    else if (mode === 'plan') loadChronologicalPlan();
    else if (mode === 'devotional') loadDevotional();
    else if (mode === 'mood') loadMoodSelector();
    else if (mode === 'saved') { setViewMode('saved'); setSidebarOpen(false); }
    else if (mode === 'study') { setViewMode('study'); setSidebarOpen(false); }
  };

  const loadChronologicalPlan = async () => {
    setViewMode('plan'); setSidebarOpen(false);
    if (chronoPlan.length === 0) {
      setLoadingPlan(true);
      try { const plan = await getChronologicalPlan(); setChronoPlan(plan); } catch (e) {} finally { setLoadingPlan(false); }
    }
  };

  const loadDevotional = async () => {
    setViewMode('devotional'); setSidebarOpen(false);
    if (!devotional) {
      setLoadingDevotional(true);
      try { const result = await getDailyDevotional(); setDevotional(result); } catch (e) {} finally { setLoadingDevotional(false); }
    }
  };

  const loadMoodSelector = () => { setViewMode('mood'); setSidebarOpen(false); setSelectedMood(''); setMoodResults([]); };

  const handleSearch = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!searchQuery.trim()) return;
    setViewMode('search'); setSidebarOpen(false); setIsSearching(true); setSearchResults([]);
    try { const results = await searchBible(searchQuery); setSearchResults(results); } catch (error) {} finally { setIsSearching(false); }
  };

  const addHighlight = (color: string) => {
    if (!selectionMenu || !data) return;
    const { verseNumber, range } = selectionMenu;
    const selectedText = range.toString();
    const verseEl = document.querySelector(`[data-verse-number="${verseNumber}"]`);
    if (!verseEl) return;
    const preCaretRange = range.cloneRange();
    preCaretRange.selectNodeContents(verseEl);
    preCaretRange.setEnd(range.startContainer, range.startOffset);
    const start = preCaretRange.toString().length;
    const end = start + selectedText.length;
    const key = getHighlightKey(data.metadata.book_name, data.metadata.chapter_number, verseNumber);
    const updatedHighlights = [...(verseHighlights[key] || []), { id: Date.now().toString(), start, end, color, text: selectedText }];
    setVerseHighlights(prev => ({ ...prev, [key]: updatedHighlights }));
    localStorage.setItem(key, JSON.stringify(updatedHighlights));
    setSelectionMenu(null);
    window.getSelection()?.removeAllRanges();
  };

  const handlePlayVerse = (verseNumber: number, text: string) => {
    window.speechSynthesis.cancel();
    if (playingVerse === verseNumber) { setPlayingVerse(null); return; }
    setPlayingVerse(verseNumber);
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'es-ES';
    utterance.onend = () => setPlayingVerse(null);
    window.speechSynthesis.speak(utterance);
  };

  const activeBookData = BIBLE_BOOKS.find(b => b.name === currentBook);

  return (
    <div className="flex h-screen bg-stone-100 overflow-hidden font-sans" onClick={(e) => {
        const target = e.target as HTMLElement;
        if (!target.closest('#highlight-menu') && (!window.getSelection() || window.getSelection()?.isCollapsed)) setSelectionMenu(null);
    }}>

      {selectionMenu && (
        <div id="highlight-menu" className="fixed z-50 bg-white rounded-full shadow-xl border border-stone-200 p-2 flex gap-2 animate-fade-in" style={{ top: selectionMenu.top, left: selectionMenu.left }}>
          {['yellow', 'green', 'blue', 'pink'].map(color => (
            <button key={color} onMouseDown={(e) => { e.preventDefault(); addHighlight(color); }} className={`w-8 h-8 rounded-full bg-${color}-400 hover:scale-110 transition-transform border border-stone-100`} />
          ))}
          <div className="w-px h-8 bg-stone-200 mx-1"></div>
          <button onMouseDown={(e) => { e.preventDefault(); 
             const key = getHighlightKey(data!.metadata.book_name, data!.metadata.chapter_number, selectionMenu.verseNumber);
             setVerseHighlights(prev => ({ ...prev, [key]: [] })); localStorage.removeItem(key); setSelectionMenu(null); window.getSelection()?.removeAllRanges();
          }} className="px-3 py-1 text-xs font-bold text-red-500 hover:bg-red-50 rounded-full">Borrar</button>
        </div>
      )}

      {isImageCreatorOpen && selectedVerseForAction && data && (
         <ShareableImage verseText={selectedVerseForAction.text} verseReference={`${data.metadata.book_name} ${data.metadata.chapter_number}:${selectedVerseForAction.number}`} onClose={() => setImageCreatorOpen(false)} />
      )}

      {/* Sidebar exists but only for indexed book navigation, not general nav */}
      <Sidebar 
        currentBook={currentBook} 
        onSelectBook={handleSelectBook} 
        onSelectChapter={handleSelectChapter}
        onSelectVerse={handleSelectVerse}
        isOpen={isSidebarOpen}
        onClose={() => setSidebarOpen(false)}
        streak={streakDays}
      />

      <div className="flex-1 flex flex-col h-full overflow-hidden relative">
        <header className="bg-white border-b border-stone-200 p-4 flex items-center justify-between shadow-sm z-30">
          <div className="flex items-center gap-2">
            {viewMode !== 'home' ? (
              <button onClick={handleGoHome} className="p-2 text-bible-leather flex items-center gap-2 bg-stone-100 rounded-full pr-4 hover:bg-stone-200 transition-colors">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg>
                 <span className="text-xs font-bold uppercase tracking-widest">Inicio</span>
              </button>
            ) : (
              <div className="flex items-center gap-2 px-2">
                <span className="text-xl">🔥</span>
                <span className="text-sm font-bold text-orange-600">{streakDays} días</span>
              </div>
            )}
          </div>

          <form onSubmit={handleSearch} className="flex-1 max-w-md mx-4">
              <div className="relative">
                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Buscar en las Escrituras..." className="w-full bg-stone-100 border-none rounded-full py-2 px-10 text-sm focus:ring-2 focus:ring-bible-gold outline-none" />
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4 absolute left-3.5 top-2.5 text-stone-400"><path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" /></svg>
              </div>
          </form>

          <div className="flex items-center gap-2">
            {viewMode === 'reader' && (
              <button onClick={() => setSidebarOpen(true)} className="p-2.5 bg-stone-100 text-bible-leather rounded-full hover:bg-stone-200 transition-colors lg:hidden" title="Abrir Índice">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" /></svg>
              </button>
            )}
            {data && viewMode === 'reader' && (
               <button 
                  onClick={() => setContextOpen(!isContextOpen)} 
                  className={`p-2.5 rounded-full transition-all border-2 ${isContextOpen ? 'bg-bible-gold border-bible-gold text-white' : 'bg-white border-stone-200 text-bible-gold hover:border-bible-gold'}`}
                  title="Análisis Contextual"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M12 18v-5.25m0 0a6.001 6.001 0 00-5.304-7.618 6.002 6.002 0 019.957 5.304c.42 2.15-1.65 4.314-4.653 2.314zm0 0l-7.05 4.633a1.125 1.125 0 01-1.373-1.634l-.75-7.5M12 18l7.05 4.633a1.125 1.125 0 001.373-1.634l-.75-7.5" />
                  </svg>
                </button>
            )}
          </div>
        </header>

        <div id="bible-content-area" className="flex-1 overflow-y-auto bg-bible-paper p-4 lg:p-10 relative scroll-smooth">

          {viewMode === 'home' && (
             <div className="max-w-6xl mx-auto py-4 animate-fade-in">
                <div className="text-center mb-12">
                   <div className="w-24 h-24 bg-bible-leather rounded-full flex items-center justify-center mx-auto mb-6 shadow-xl border-4 border-bible-gold/20">
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-14 h-14 text-bible-gold">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" />
                      </svg>
                   </div>
                   <h1 className="text-5xl md:text-6xl font-display font-bold text-bible-ink mb-3 tracking-tighter uppercase">ABBA BIBLIA</h1>
                   <p className="text-stone-500 text-lg max-w-xl mx-auto italic font-serif opacity-80 leading-relaxed">"Tu palabra es una lámpara que guía mis pies y una luz para mi camino."</p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                   {[
                      { mode: 'reader', label: 'Explorar Biblia', sub: 'Lectura y Contexto', icon: '📖', color: 'from-amber-100 to-amber-50' },
                      { mode: 'devotional', label: 'Devocional', sub: 'Palabra del Día', icon: '🙏', color: 'from-emerald-100 to-emerald-50' },
                      { mode: 'plan', label: 'Rutas de Lectura', sub: 'Cronología Bíblica', icon: '📅', color: 'from-blue-100 to-blue-50' },
                      { mode: 'study', label: 'Academia Bíblica', sub: 'Cursos y Quizzes', icon: '🎓', color: 'from-purple-100 to-purple-50' },
                      { mode: 'mood', label: 'Guía Espiritual', sub: 'Según tu Sentir', icon: '❤️', color: 'from-rose-100 to-rose-50' },
                      { mode: 'saved', label: 'Mis Tesoros', sub: 'Notas y Marcas', icon: '🔖', color: 'from-stone-200 to-stone-100' },
                   ].map((item: any) => (
                      <button 
                        key={item.mode} 
                        onClick={() => handleNavigate(item.mode)} 
                        className={`bg-gradient-to-br ${item.color} p-10 rounded-[2.5rem] shadow-sm border border-black/5 hover:shadow-2xl hover:-translate-y-2 transition-all flex flex-col items-center text-center group relative overflow-hidden h-full`}
                      >
                         <span className="text-6xl mb-6 group-hover:scale-110 transition-transform duration-500 block">{item.icon}</span>
                         <h3 className="text-2xl font-display font-bold text-bible-ink mb-1">{item.label}</h3>
                         <p className="text-stone-500 text-[10px] font-bold uppercase tracking-widest opacity-60">{item.sub}</p>
                         <div className="absolute -bottom-6 -right-6 w-20 h-20 bg-black/5 rounded-full group-hover:scale-150 transition-transform duration-700"></div>
                      </button>
                   ))}
                </div>

                <div className="mt-12 bg-white/40 backdrop-blur-sm border border-stone-200 p-12 rounded-[3rem] text-center shadow-inner">
                   <h2 className="text-3xl font-display font-bold text-bible-ink mb-3 tracking-wide">Comienza tu estudio</h2>
                   <p className="text-stone-500 mb-10 text-sm max-w-sm mx-auto">Selecciona una de las opciones superiores para profundizar en las Sagradas Escrituras.</p>
                   <button onClick={() => handleNavigate('reader')} className="bg-bible-leather text-white px-16 py-5 rounded-full font-bold shadow-2xl hover:bg-bible-ink hover:scale-105 active:scale-95 transition-all text-xs tracking-[0.2em] uppercase">Iniciar Lectura</button>
                </div>
             </div>
          )}

          {viewMode === 'reader' && (
            <div className="max-w-4xl mx-auto">
              {loadingState === LoadingState.IDLE && (
                 <div className="animate-fade-in py-4">
                    <div className="flex flex-col md:flex-row md:items-center justify-between mb-12 border-b border-stone-200 pb-8 gap-4">
                       <div>
                          <h1 className="text-4xl font-display font-bold text-bible-ink mb-1">Biblioteca Sagrada</h1>
                          <p className="text-stone-500 text-xs tracking-[0.2em] uppercase">Explora el Canon Bíblico</p>
                       </div>
                       {bibleBrowserView === 'chapters' && (
                          <button 
                            onClick={() => setBibleBrowserView('books')}
                            className="flex items-center gap-2 text-bible-leather font-bold text-xs uppercase tracking-widest bg-stone-200/50 px-6 py-3 rounded-full hover:bg-stone-200 transition-colors"
                          >
                             &larr; Volver a Libros
                          </button>
                       )}
                    </div>

                    {bibleBrowserView === 'books' ? (
                       <div className="space-y-12">
                          {Object.entries(CATEGORY_LABELS).map(([catId, label]) => {
                             const booksInCategory = BIBLE_BOOKS.filter(b => b.category === catId);
                             if (booksInCategory.length === 0) return null;
                             return (
                                <div key={catId}>
                                   <h3 className="text-[10px] font-bold text-bible-accent uppercase tracking-[0.4em] mb-6 pl-4 border-l-4 border-bible-gold">{label}</h3>
                                   <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                                      {booksInCategory.map(book => (
                                         <button 
                                           key={book.name}
                                           onClick={() => handleSelectBook(book.name)}
                                           className="p-6 bg-white border border-stone-100 rounded-3xl text-left hover:border-bible-gold hover:shadow-xl transition-all group relative overflow-hidden"
                                         >
                                            <span className="block text-stone-800 font-bold group-hover:text-bible-leather transition-colors relative z-10">{book.name}</span>
                                            <span className="text-[10px] text-stone-400 font-bold uppercase tracking-widest relative z-10">{book.chapters} caps</span>
                                            <div className="absolute -bottom-2 -right-2 text-stone-50 text-4xl font-display font-bold group-hover:text-bible-gold/5 transition-colors">{book.name[0]}</div>
                                         </button>
                                      ))}
                                   </div>
                                </div>
                             )
                          })}
                       </div>
                    ) : (
                       <div className="animate-fade-in text-center py-10">
                          <span className="text-bible-accent text-xs font-bold uppercase tracking-[0.5em] mb-4 block">Libro de</span>
                          <h2 className="text-6xl font-display font-bold text-bible-ink mb-4">{activeBookData?.name}</h2>
                          <div className="w-20 h-1 bg-bible-gold mx-auto mb-12"></div>
                          <div className="grid grid-cols-4 sm:grid-cols-6 md:grid-cols-8 lg:grid-cols-10 gap-4 px-4">
                             {Array.from({ length: activeBookData?.chapters || 0 }, (_, i) => i + 1).map(chap => (
                                <button
                                  key={chap}
                                  onClick={() => handleSelectChapter(chap)}
                                  className="aspect-square flex items-center justify-center text-lg font-bold rounded-2xl bg-white border border-stone-200 text-stone-600 hover:bg-bible-leather hover:text-white hover:border-bible-leather hover:shadow-2xl transition-all transform hover:-translate-y-1"
                                >
                                   {chap}
                                </button>
                             ))}
                          </div>
                       </div>
                    )}
                 </div>
              )}

              {loadingState === LoadingState.LOADING && ( <div className="space-y-8 animate-pulse pt-20"><div className="h-16 bg-stone-200 rounded-3xl w-1/3 mx-auto"></div><div className="space-y-4 mt-16"><div className="h-4 bg-stone-200 rounded-full w-full"></div><div className="h-4 bg-stone-200 rounded-full w-5/6"></div></div></div> )}

              {loadingState === LoadingState.SUCCESS && data && (
                <div className="animate-fade-in pb-32 relative">
                  <div className="text-center mb-12">
                    <span className="text-bible-accent uppercase tracking-[0.5em] text-[10px] font-bold mb-4 block">Capítulo {data.metadata.chapter_number}</span>
                    <h1 className="text-5xl lg:text-7xl font-display font-bold text-bible-ink leading-tight">{data.metadata.book_name}</h1>
                  </div>

                  <div className="mb-12 max-w-xl mx-auto sticky top-4 z-20 shadow-2xl rounded-[2.5rem] overflow-hidden bg-white/95 backdrop-blur-md border border-stone-200 p-1 flex items-center gap-4 pr-6">
                    <div className="flex-1"><TextAudioPlayer text={data.verses.map(v => v.text).join(' ')} title="Voz de la Palabra" className="border-none" showText={false} onBoundary={handleAudioProgress} /></div>
                    <div className="flex gap-2">
                       <button onClick={() => setFontSize(s => Math.max(14, s - 2))} className="w-8 h-8 flex items-center justify-center bg-stone-100 rounded-full hover:bg-stone-200 transition-colors text-xs font-serif">A-</button>
                       <button onClick={() => setFontSize(s => Math.min(32, s + 2))} className="w-8 h-8 flex items-center justify-center bg-stone-100 rounded-full hover:bg-stone-200 transition-colors text-lg font-serif">A+</button>
                    </div>
                  </div>

                  <div className="space-y-10">
                    {data.verses.map((verse) => {
                      const noteKey = getNoteKey(data.metadata.book_name, data.metadata.chapter_number, verse.number);
                      const highlightKey = getHighlightKey(data.metadata.book_name, data.metadata.chapter_number, verse.number);
                      const note = userNotes[noteKey];
                      const currentVerseHighlights = verseHighlights[highlightKey] || [];
                      const isEditing = editingNote === noteKey;
                      const isAudioActive = audioActiveVerse === verse.number;
                      let activeCharIndexForVerse = null;
                      if (isAudioActive) {
                          const offsetData = verseOffsets.find(v => v.verse === verse.number);
                          if (offsetData) {
                              const localIndex = globalAudioCharIndex - offsetData.start;
                              if (localIndex >= 0 && localIndex <= (offsetData.end - offsetData.start)) activeCharIndexForVerse = localIndex;
                          }
                      }
                      return (
                        <div id={`verse-${verse.number}`} key={verse.number} className={`relative group transition-all duration-700 rounded-[2rem] p-6 -mx-6 ${isAudioActive ? 'bg-bible-gold/10 border-l-8 border-bible-gold shadow-md' : 'border-l-8 border-transparent'}`} data-verse-number={verse.number}>
                          <div className="absolute -left-12 lg:-left-16 top-6 flex flex-col items-end gap-3 w-10 z-10">
                             <span className={`text-xs font-bold font-sans select-none mb-1 transition-all ${isAudioActive ? 'text-bible-gold scale-150' : 'text-bible-gold/30'}`}>{verse.number}</span>
                             <div className={`flex flex-col gap-3 transition-opacity duration-300 ${note ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                                <button onClick={() => setEditingNote(isEditing ? null : noteKey)} className={`p-2 rounded-full shadow-sm bg-white border border-stone-100 ${note ? 'text-yellow-600' : 'text-stone-300 hover:text-bible-accent'}`} title="Nota"><svg xmlns="http://www.w3.org/2000/svg" fill={note ? "currentColor" : "none"} viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path d="M16.862 4.487l1.687-1.688a1.875 1.875 0 112.652 2.652L10.582 16.07a4.5 4.5 0 01-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 011.13-1.897l8.932-8.931zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0115.75 21H5.25A2.25 2.25 0 013 18.75V8.25A2.25 2.25 0 015.25 6H10" /></svg></button>
                                <button onClick={() => handlePlayVerse(verse.number, verse.text)} className={`p-2 rounded-full shadow-sm bg-white border border-stone-100 ${playingVerse === verse.number ? 'text-bible-gold' : 'text-stone-300 hover:text-green-500'}`} title="Oír">{playingVerse === verse.number ? '🔊' : <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path d="M19.114 5.636a9 9 0 010 12.728M16.463 8.288a5.25 5.25 0 010 7.424M6.75 8.25l4.72-4.72a.75.75 0 011.28.53v15.88a.75.75 0 01-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 012.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75z" /></svg>}</button>
                             </div>
                          </div>
                          <div className="rounded-lg px-2"><HighlightableVerse text={verse.text} highlights={currentVerseHighlights} fontSize={fontSize} lineHeight={lineHeight} activeCharIndex={activeCharIndexForVerse} /></div>
                          {isEditing && ( <NoteEditor initialNote={note || ''} onSave={(c) => { localStorage.setItem(noteKey, c); setUserNotes(prev => ({ ...prev, [noteKey]: c })); setEditingNote(null); }} onCancel={() => setEditingNote(null)} onDelete={() => { localStorage.removeItem(noteKey); setUserNotes(p => { const n = {...p}; delete n[noteKey]; return n; }); setEditingNote(null); }} /> )}
                          {!isEditing && note && ( <div onClick={() => setEditingNote(noteKey)} className="ml-4 lg:ml-10 mb-8 p-6 bg-yellow-50 rounded-[2rem] border-l-4 border-yellow-400 cursor-pointer hover:bg-yellow-100 transition-all shadow-sm relative"><div className="absolute -top-4 -left-3 text-3xl">📝</div><p className="font-handwriting text-stone-800 text-base italic leading-relaxed">"{note}"</p></div> )}
                        </div>
                      );
                    })}
                  </div>

                  <div className="mt-20 pt-12 border-t border-stone-200"><ChapterExplanation explanation={data.metadata.detailed_explanation} /></div>
                  <div className="mt-12 flex justify-center"><button onClick={() => handleSelectChapter(currentChapter + 1)} className="px-14 py-5 bg-bible-leather text-white rounded-full hover:bg-bible-ink transition-all font-display shadow-2xl hover:scale-105 active:scale-95 text-xs tracking-widest uppercase">Siguiente Capítulo</button></div>

                  {/* Floating Academic Assistant */}
                  <div className="fixed bottom-8 right-8 z-30 flex flex-col gap-4 animate-fade-in-up">
                    <button 
                      onClick={() => { setTutorTopic(`${data.metadata.book_name} Capítulo ${data.metadata.chapter_number}`); setIsReaderTutorOpen(true); }} 
                      className="group flex items-center gap-4 px-6 py-4 bg-bible-ink text-white rounded-full shadow-2xl hover:bg-stone-800 transition-all border-2 border-bible-gold/30"
                    >
                      <span className="text-[10px] font-bold tracking-widest uppercase hidden md:block">Consultar Teología</span>
                      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-6 h-6 text-bible-gold"><path d="M11.25 4.533A9.707 9.707 0 006 3.75c-2.389 0-4.575.683-6.406 1.858a.75.75 0 01-.437-.695V3.75a.75.75 0 01.75-.75h14.25a.75.75 0 01.75.75v.916c0 .124-.034.24-.094.34a9.712 9.712 0 00-3.563-.467z" /><path fillRule="evenodd" d="M2.25 7.5a.75.75 0 01.75-.75h18a.75.75 0 01.75.75v.784a9.757 9.757 0 01-9.75 9.75A9.757 9.757 0 012.25 8.284V7.5zM9.994 17.585a.75.75 0 01.728.568A11.258 11.258 0 0012 21a11.258 11.258 0 001.278-2.847.75.75 0 011.456.368A12.76 12.76 0 0112 22.5c-1.25 0-2.436-.217-3.55-.615a.75.75 0 01.544-1.299z" clipRule="evenodd" /></svg>
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {viewMode === 'saved' && ( <SavedContent onNavigateToVerse={handleSelectVerse} onDeleteItem={(k) => { localStorage.removeItem(k); handleNavigate('saved'); }} /> )}
          {viewMode === 'study' && ( <StudyMode /> )}
          {viewMode === 'mood' && (
             <div className="max-w-4xl mx-auto pt-4 lg:pt-8">
                {selectedMood ? (
                   <div className="animate-fade-in">
                      <div className="flex items-center gap-2 mb-10 border-b border-stone-200 pb-6">
                        <button onClick={() => { setSelectedMood(''); setMoodResults([]); }} className="text-stone-500 hover:text-bible-gold transition-colors"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-7 h-7"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg></button>
                        <h3 className="text-3xl font-bold text-bible-ink">Versículos para: <span className="text-bible-accent italic">{selectedMood}</span></h3>
                      </div>
                      <div className="space-y-10 pb-20">{moodResults.map((item, idx) => (<div key={idx} className="bg-white p-10 rounded-[3rem] shadow-sm border border-stone-100 hover:shadow-2xl transition-all"><h4 className="font-bold text-bible-leather mb-3 text-xl">{item.verseReference}</h4><p className="font-serif text-3xl text-bible-ink mb-8 italic">"{item.text}"</p><div className="text-base text-stone-600 bg-stone-50 p-8 rounded-3xl border border-stone-100 leading-relaxed font-serif text-justify">{item.explanation}</div></div>))}</div>
                   </div>
                ) : ( <MoodSelector onSelectMood={async (m) => { setSelectedMood(m); setLoadingMood(true); const r = await getVersesByMood(m); setMoodResults(r); setLoadingMood(false); }} /> )}
             </div>
          )}
          {viewMode === 'plan' && ( <div className="max-w-4xl mx-auto"><div className="text-center mb-14 font-display font-bold text-5xl text-bible-ink">Planes de Lectura</div><ReadingGoalSelector onSelect={() => {}} /></div> )}
          {viewMode === 'devotional' && (
            <div className="max-w-3xl mx-auto pt-8 animate-fade-in">
               <div className="text-center mb-14"><h1 className="text-5xl font-display font-bold text-bible-ink mb-2 tracking-tighter">DEVOCIONAL</h1><p className="text-stone-500 font-bold uppercase tracking-[0.3em] text-[10px]">{new Date().toLocaleDateString('es-ES', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p></div>
               {loadingDevotional ? ( <div className="h-80 bg-white rounded-[4rem] animate-pulse"></div> ) : devotional ? (
                <div className="space-y-12 pb-20 animate-fade-in-up">
                  <div className="bg-white p-16 rounded-[4rem] shadow-2xl border-t-[14px] border-bible-gold text-center relative overflow-hidden"><div className="absolute top-4 left-4 text-stone-100 text-9xl font-serif select-none">"</div><h2 className="text-4xl lg:text-5xl font-serif text-bible-ink leading-tight mb-10 italic relative z-10">"{devotional.verseText}"</h2><p className="text-bible-accent font-bold tracking-[0.5em] uppercase text-xs">{devotional.verseReference}</p></div>
                  <div className="bg-white p-12 rounded-[3rem] shadow-sm border border-stone-100"><TextAudioPlayer text={devotional.reflection} title="Reflexión Pastoral" /></div>
                </div>
               ) : ( <div className="text-center py-24"><button onClick={loadDevotional} className="px-16 py-6 bg-bible-gold text-white rounded-full font-bold shadow-2xl hover:scale-105 active:scale-95 transition-all text-xs tracking-[0.3em]">RECIBIR PALABRA DE HOY</button></div> )}
            </div>
          )}
        </div>
      </div>

      <ContextPanel metadata={data ? data.metadata : null} isOpen={isContextOpen} onClose={() => setContextOpen(false)} isLoading={loadingState === LoadingState.LOADING} />
      <TheologyTutor topic={tutorTopic} isOpen={isReaderTutorOpen} onClose={() => setIsReaderTutorOpen(false)} />
    </div>
  );
}

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { BIBLE_BOOKS, CATEGORY_LABELS, VERSE_COUNTS } from '../constants';
import { BibleBook } from '../types';

interface SidebarProps {
  currentBook: string;
  onSelectBook: (bookName: string) => void;
  onSelectChapter: (chapter: number) => void;
  onSelectVerse: (book: string, chapter: number, verse: number) => void;
  isOpen: boolean;
  onClose: () => void;
  streak?: number;
}

type SidebarView = 'books' | 'chapters' | 'verses';

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentBook, onSelectBook, onSelectChapter, onSelectVerse, isOpen, onClose, streak = 0 
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [view, setView] = useState<SidebarView>('books');
  const [selectedChapter, setSelectedChapter] = useState<number | null>(null);

  useEffect(() => {
    if (currentBook) {
      if (view === 'books') setView('chapters');
    } else {
      setView('books');
      setSelectedChapter(null);
    }
  }, [currentBook]);

  const groupedBooks = useMemo<Record<string, BibleBook[]>>(() => {
    const filtered = BIBLE_BOOKS.filter(b => b.name.toLowerCase().includes(searchTerm.toLowerCase()));
    const groups: Record<string, BibleBook[]> = {};
    filtered.forEach(book => {
      if (!groups[book.category]) groups[book.category] = [];
      groups[book.category].push(book);
    });
    return groups;
  }, [searchTerm]);

  const activeBookData = BIBLE_BOOKS.find(b => b.name === currentBook);

  const handleBookClick = (bookName: string) => {
    onSelectBook(bookName);
    setView('chapters');
    setSelectedChapter(null);
    setSearchTerm('');
  };

  const handleChapterClick = (chapter: number) => {
    setSelectedChapter(chapter);
    setView('verses');
  };

  const handleVerseClick = (verse: number) => {
    if (activeBookData && selectedChapter) {
      onSelectVerse(activeBookData.name, selectedChapter, verse);
      if (window.innerWidth < 1024) onClose();
    }
  };

  const handleBack = () => {
    if (view === 'verses') { setView('chapters'); setSelectedChapter(null); }
    else if (view === 'chapters') { setView('books'); onSelectBook(''); }
  };

  const verseCount = (activeBookData && selectedChapter) 
    ? (VERSE_COUNTS[activeBookData.name]?.[selectedChapter - 1] || 20) 
    : 0;

  return (
    <div className={`fixed inset-y-0 left-0 transform ${isOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 lg:static lg:w-80 bg-white border-r border-stone-200 z-40 transition-transform duration-300 ease-in-out flex flex-col h-full shadow-2xl lg:shadow-none`}>
      <div className="p-6 border-b border-stone-100 bg-bible-paper">
        <div className="flex items-center justify-between mb-8">
           {view === 'books' ? (
             <div className="flex items-center justify-between w-full">
               <h2 className="text-xl font-display font-bold text-bible-ink uppercase tracking-widest">Índice Bíblico</h2>
               <button onClick={onClose} className="lg:hidden p-2 text-stone-400">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
               </button>
             </div>
           ) : (
             <div className="flex items-center gap-3">
               <button onClick={handleBack} className="p-2.5 rounded-full hover:bg-stone-100 text-stone-500 transition-all">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg>
               </button>
               <h2 className="text-lg font-display font-bold text-bible-ink truncate max-w-[180px]">
                 {view === 'chapters' ? activeBookData?.name : `${activeBookData?.name} ${selectedChapter}`}
               </h2>
             </div>
           )}
        </div>

        {view === 'books' && (
          <div className="relative">
            <input type="text" placeholder="Filtrar libros..." className="w-full px-5 py-3 rounded-2xl bg-stone-100 border-none focus:ring-2 focus:ring-bible-gold outline-none text-sm font-sans" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4 absolute right-4 top-3.5 text-stone-400"><path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" /></svg>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-y-auto p-5 space-y-6 bg-bible-paper custom-scrollbar">
        {view === 'books' && Object.entries(groupedBooks).map(([category, books]: any) => (
          <div key={category} className="mb-8">
            <h3 className="text-[9px] font-bold text-bible-accent uppercase tracking-[0.4em] mb-4 ml-2 opacity-60">{CATEGORY_LABELS[category]}</h3>
            <div className="grid grid-cols-1 gap-1.5">
              {books.map((book: any) => (
                <button key={book.name} onClick={() => handleBookClick(book.name)} className={`w-full text-left px-5 py-3.5 rounded-2xl text-sm font-medium transition-all ${currentBook === book.name ? 'bg-bible-leather text-white shadow-lg' : 'text-stone-600 hover:bg-stone-50 hover:pl-6'}`}>{book.name}</button>
              ))}
            </div>
          </div>
        ))}

        {view === 'chapters' && activeBookData && (
          <div className="animate-fade-in">
            <h3 className="text-[10px] font-bold text-stone-400 uppercase tracking-widest mb-6 px-2">Capítulos:</h3>
            <div className="grid grid-cols-4 gap-2.5">{Array.from({ length: activeBookData.chapters }, (_, i) => i + 1).map(chap => (
                <button key={chap} onClick={() => handleChapterClick(chap)} className="aspect-square flex items-center justify-center text-sm font-bold rounded-2xl hover:bg-bible-gold hover:text-white transition-all bg-white border border-stone-100 text-stone-600 shadow-sm">{chap}</button>
              ))}</div>
          </div>
        )}

        {view === 'verses' && activeBookData && selectedChapter && (
           <div className="animate-fade-in">
              <button onClick={() => { onSelectChapter(selectedChapter); if (window.innerWidth < 1024) onClose(); }} className="w-full mb-8 py-5 bg-bible-gold text-white font-bold text-[10px] uppercase tracking-[0.2em] rounded-[1.5rem] hover:bg-bible-accent transition-all shadow-xl">
                Leer Capítulo
              </button>
              <h3 className="text-[10px] font-bold text-stone-400 uppercase tracking-widest mb-6 px-2">Versículos:</h3>
              <div className="grid grid-cols-5 gap-2">{Array.from({ length: verseCount }, (_, i) => i + 1).map(verse => (
                  <button key={verse} onClick={() => handleVerseClick(verse)} className="aspect-square flex items-center justify-center text-[11px] font-bold rounded-xl hover:bg-bible-accent hover:text-white transition-all bg-white border border-stone-100 text-stone-500 shadow-sm">{verse}</button>
                ))}</div>
           </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Sidebar } from './components/Sidebar';
import { ContextPanel } from './components/ContextPanel';
import { NoteEditor } from './components/NoteEditor';
import { ChapterExplanation } from './components/ChapterExplanation';
import { HighlightableVerse } from './components/HighlightableVerse';
import { TextAudioPlayer } from './components/TextAudioPlayer';
import { MoodSelector } from './components/MoodSelector';
import { SavedContent } from './components/SavedContent';
import { StudyMode } from './components/StudyMode';
import { ShareableImage } from './components/ShareableImage';
import { ReadingGoalSelector } from './components/ReadingGoalSelector';
import { TheologyTutor } from './components/TheologyTutor';
import { getBibleChapter, getChronologicalPlan, searchBible, getDailyDevotional, getVersesByMood } from './services/geminiService';
import { ChapterResponse, LoadingState, ReadingPlanItem, SearchResult, DailyDevotional, Highlight, MoodResult } from './types';
import { BIBLE_BOOKS, CATEGORY_LABELS } from './constants';

const getNoteKey = (book: string, chapter: number, verse: number) => `note-${book}-${chapter}-${verse}`;
const getHighlightKey = (book: string, chapter: number, verse: number) => `highlights-v2-${book}-${chapter}-${verse}`;

interface SelectionMenuPosition {
  top: number;
  left: number;
  verseNumber: number;
  range: Range;
}

function App() {
  const [currentBook, setCurrentBook] = useState<string>('');
  const [currentChapter, setCurrentChapter] = useState<number>(1);
  const [data, setData] = useState<ChapterResponse | null>(null);
  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isContextOpen, setContextOpen] = useState(false);
  const [viewMode, setViewMode] = useState<'home' | 'reader' | 'plan' | 'search' | 'devotional' | 'mood' | 'saved' | 'study'>('home');
  const [chronoPlan, setChronoPlan] = useState<ReadingPlanItem[]>([]);
  const [loadingPlan, setLoadingPlan] = useState(false);
  const [devotional, setDevotional] = useState<DailyDevotional | null>(null);
  const [loadingDevotional, setLoadingDevotional] = useState(false);
  const [moodResults, setMoodResults] = useState<MoodResult[]>([]);
  const [loadingMood, setLoadingMood] = useState(false);
  const [selectedMood, setSelectedMood] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [userNotes, setUserNotes] = useState<Record<string, string>>({});
  const [editingNote, setEditingNote] = useState<string | null>(null); 
  const [verseHighlights, setVerseHighlights] = useState<Record<string, Highlight[]>>({});
  const [selectionMenu, setSelectionMenu] = useState<SelectionMenuPosition | null>(null);
  const [fontSize, setFontSize] = useState<number>(18); 
  const [lineHeight, setLineHeight] = useState<number>(1.625); 
  const [isImageCreatorOpen, setImageCreatorOpen] = useState(false);
  const [selectedVerseForAction, setSelectedVerseForAction] = useState<{number: number, text: string} | null>(null);
  const [isReaderTutorOpen, setIsReaderTutorOpen] = useState(false);
  const [tutorTopic, setTutorTopic] = useState<string>('');
  const [playingVerse, setPlayingVerse] = useState<number | null>(null);
  const [audioActiveVerse, setAudioActiveVerse] = useState<number | null>(null);
  const [globalAudioCharIndex, setGlobalAudioCharIndex] = useState<number>(0);
  const [streakDays, setStreakDays] = useState(0);
  const [bibleBrowserView, setBibleBrowserView] = useState<'books' | 'chapters'>('books');

  const verseOffsets = useMemo(() => {
    if (!data) return [];
    let currentOffset = 0;
    return data.verses.map(v => {
        const start = currentOffset;
        const length = v.text.length;
        currentOffset += length + 1; 
        return { verse: v.number, start, end: start + length };
    });
  }, [data]);

  const handleAudioProgress = (charIndex: number) => {
     setGlobalAudioCharIndex(charIndex); 
     if (!verseOffsets.length) return;
     const match = verseOffsets.find(v => charIndex >= v.start && charIndex <= v.end);
     if (match && match.verse !== audioActiveVerse) {
        setAudioActiveVerse(match.verse);
        const el = document.getElementById(`verse-${match.verse}`);
        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
     }
  };

  useEffect(() => {
    const loadedNotes: Record<string, string> = {};
    const loadedHighlights: Record<string, Highlight[]> = {};
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key) {
        if (key.startsWith('note-')) loadedNotes[key] = localStorage.getItem(key) || '';
        else if (key.startsWith('highlights-v2-')) {
          try { loadedHighlights[key] = JSON.parse(localStorage.getItem(key) || '[]'); } catch (e) {}
        }
      }
    }
    setUserNotes(loadedNotes);
    setVerseHighlights(loadedHighlights);

    const today = new Date().toDateString();
    const streak = parseInt(localStorage.getItem('currentStreak') || '1');
    setStreakDays(streak);
  }, []);

  const fetchChapter = async (book: string, chapter: number) => {
    setLoadingState(LoadingState.LOADING);
    setData(null);
    setAudioActiveVerse(null);
    setGlobalAudioCharIndex(0);
    setContextOpen(false); // ALWAYS START CLOSED
    try {
      const result = await getBibleChapter(book, chapter);
      setData(result);
      setLoadingState(LoadingState.SUCCESS);
      setTutorTopic(`${result.metadata.book_name} Capítulo ${result.metadata.chapter_number}`);
    } catch (error) {
      setLoadingState(LoadingState.ERROR);
    }
  };

  const handleSelectBook = (book: string) => { 
    setCurrentBook(book); 
    setBibleBrowserView('chapters');
  };

  const handleSelectChapter = (chapter: number) => {
    setCurrentChapter(chapter);
    fetchChapter(currentBook, chapter);
    setSidebarOpen(false); 
    setViewMode('reader');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSelectVerse = (book: string, chapter: number, verse: number) => {
    if (currentBook === book && currentChapter === chapter && data) {
       setSidebarOpen(false);
       setViewMode('reader');
       const el = document.getElementById(`verse-${verse}`);
       if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    } else {
       setCurrentBook(book); setCurrentChapter(chapter);
       fetchChapter(book, chapter); setSidebarOpen(false); setViewMode('reader');
    }
  };

  const handleGoHome = () => {
    setData(null); setLoadingState(LoadingState.IDLE); setViewMode('home');
    setCurrentBook(''); setCurrentChapter(1); setSearchQuery('');
    setBibleBrowserView('books');
    setSidebarOpen(false); setContextOpen(false);
  };

  const handleNavigate = (mode: 'reader' | 'plan' | 'devotional' | 'mood' | 'saved' | 'study') => {
    if (mode === 'reader') { 
      setViewMode('reader');
      if (!data) setBibleBrowserView('books');
    }
    else if (mode === 'plan') loadChronologicalPlan();
    else if (mode === 'devotional') loadDevotional();
    else if (mode === 'mood') loadMoodSelector();
    else if (mode === 'saved') { setViewMode('saved'); setSidebarOpen(false); }
    else if (mode === 'study') { setViewMode('study'); setSidebarOpen(false); }
  };

  const loadChronologicalPlan = async () => {
    setViewMode('plan'); setSidebarOpen(false);
    if (chronoPlan.length === 0) {
      setLoadingPlan(true);
      try { const plan = await getChronologicalPlan(); setChronoPlan(plan); } catch (e) {} finally { setLoadingPlan(false); }
    }
  };

  const loadDevotional = async () => {
    setViewMode('devotional'); setSidebarOpen(false);
    if (!devotional) {
      setLoadingDevotional(true);
      try { const result = await getDailyDevotional(); setDevotional(result); } catch (e) {} finally { setLoadingDevotional(false); }
    }
  };

  const loadMoodSelector = () => { setViewMode('mood'); setSidebarOpen(false); setSelectedMood(''); setMoodResults([]); };

  const handleSearch = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!searchQuery.trim()) return;
    setViewMode('search'); setSidebarOpen(false); setIsSearching(true); setSearchResults([]);
    try { const results = await searchBible(searchQuery); setSearchResults(results); } catch (error) {} finally { setIsSearching(false); }
  };

  const addHighlight = (color: string) => {
    if (!selectionMenu || !data) return;
    const { verseNumber, range } = selectionMenu;
    const selectedText = range.toString();
    const verseEl = document.querySelector(`[data-verse-number="${verseNumber}"]`);
    if (!verseEl) return;
    const preCaretRange = range.cloneRange();
    preCaretRange.selectNodeContents(verseEl);
    preCaretRange.setEnd(range.startContainer, range.startOffset);
    const start = preCaretRange.toString().length;
    const end = start + selectedText.length;
    const key = getHighlightKey(data.metadata.book_name, data.metadata.chapter_number, verseNumber);
    const updatedHighlights = [...(verseHighlights[key] || []), { id: Date.now().toString(), start, end, color, text: selectedText }];
    setVerseHighlights(prev => ({ ...prev, [key]: updatedHighlights }));
    localStorage.setItem(key, JSON.stringify(updatedHighlights));
    setSelectionMenu(null);
    window.getSelection()?.removeAllRanges();
  };

  const handlePlayVerse = (verseNumber: number, text: string) => {
    window.speechSynthesis.cancel();
    if (playingVerse === verseNumber) { setPlayingVerse(null); return; }
    setPlayingVerse(verseNumber);
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'es-ES';
    utterance.onend = () => setPlayingVerse(null);
    window.speechSynthesis.speak(utterance);
  };

  const activeBookData = BIBLE_BOOKS.find(b => b.name === currentBook);

  return (
    <div className="flex h-screen bg-stone-100 overflow-hidden font-sans" onClick={(e) => {
        const target = e.target as HTMLElement;
        if (!target.closest('#highlight-menu') && (!window.getSelection() || window.getSelection()?.isCollapsed)) setSelectionMenu(null);
    }}>

      {selectionMenu && (
        <div id="highlight-menu" className="fixed z-50 bg-white rounded-full shadow-xl border border-stone-200 p-2 flex gap-2 animate-fade-in" style={{ top: selectionMenu.top, left: selectionMenu.left }}>
          {['yellow', 'green', 'blue', 'pink'].map(color => (
            <button key={color} onMouseDown={(e) => { e.preventDefault(); addHighlight(color); }} className={`w-8 h-8 rounded-full bg-${color}-400 hover:scale-110 transition-transform border border-stone-100`} />
          ))}
          <div className="w-px h-8 bg-stone-200 mx-1"></div>
          <button onMouseDown={(e) => { e.preventDefault(); 
             const key = getHighlightKey(data!.metadata.book_name, data!.metadata.chapter_number, selectionMenu.verseNumber);
             setVerseHighlights(prev => ({ ...prev, [key]: [] })); localStorage.removeItem(key); setSelectionMenu(null); window.getSelection()?.removeAllRanges();
          }} className="px-3 py-1 text-xs font-bold text-red-500 hover:bg-red-50 rounded-full">Borrar</button>
        </div>
      )}

      {isImageCreatorOpen && selectedVerseForAction && data && (
         <ShareableImage verseText={selectedVerseForAction.text} verseReference={`${data.metadata.book_name} ${data.metadata.chapter_number}:${selectedVerseForAction.number}`} onClose={() => setImageCreatorOpen(false)} />
      )}

      <Sidebar 
        currentBook={currentBook} 
        onSelectBook={handleSelectBook} 
        onSelectChapter={handleSelectChapter}
        onSelectVerse={handleSelectVerse}
        isOpen={isSidebarOpen}
        onClose={() => setSidebarOpen(false)}
        streak={streakDays}
      />

      <div className="flex-1 flex flex-col h-full overflow-hidden relative">
        <header className="bg-white border-b border-stone-200 p-4 flex items-center justify-between shadow-sm z-30">
          <div className="flex items-center gap-2">
            {viewMode !== 'home' && (
              <button onClick={handleGoHome} className="p-2 text-bible-leather flex items-center gap-2 bg-stone-100 rounded-full pr-4 hover:bg-stone-200 transition-colors">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg>
                 <span className="text-xs font-bold uppercase tracking-widest">Inicio</span>
              </button>
            )}
            {viewMode === 'home' && (
              <div className="flex items-center gap-2 px-2">
                <span className="text-xl">🔥</span>
                <span className="text-sm font-bold text-orange-600">{streakDays} días</span>
              </div>
            )}
          </div>

          <form onSubmit={handleSearch} className="flex-1 max-w-md mx-4">
              <div className="relative">
                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Buscar en las Escrituras..." className="w-full bg-stone-100 border-none rounded-full py-2 px-10 text-sm focus:ring-2 focus:ring-bible-gold outline-none" />
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4 absolute left-3.5 top-2.5 text-stone-400"><path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" /></svg>
              </div>
          </form>

          <div className="flex items-center gap-2">
            {viewMode === 'reader' && (
               <div className="flex items-center bg-stone-100 rounded-full p-1 gap-1">
                 <button 
                    onClick={() => setContextOpen(!isContextOpen)} 
                    className={`p-2 rounded-full transition-all ${isContextOpen ? 'bg-bible-gold text-white shadow-md' : 'text-stone-400 hover:text-bible-gold'}`}
                    title="Análisis Contextual"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                      <path strokeLinecap="round" strokeLinejoin="round" d="M12 18v-5.25m0 0a6.001 6.001 0 00-5.304-7.618 6.002 6.002 0 019.957 5.304c.42 2.15-1.65 4.314-4.653 2.314zm0 0l-7.05 4.633a1.125 1.125 0 01-1.373-1.634l-.75-7.5M12 18l7.05 4.633a1.125 1.125 0 001.373-1.634l-.75-7.5" />
                    </svg>
                  </button>
                  <button 
                    onClick={() => setIsReaderTutorOpen(true)}
                    className="p-2 text-stone-400 hover:text-bible-leather rounded-full transition-all"
                    title="Asistente Teológico"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09zM18.259 8.715L18 9.75l-.259-1.035a3.375 3.375 0 00-2.455-2.456L14.25 6l1.036-.259a3.375 3.375 0 002.455-2.456L18 2.25l.259 1.035a3.375 3.375 0 002.456 2.456L21.75 6l-1.035.259a3.375 3.375 0 00-2.456 2.456z" /></svg>
                  </button>
                  <button onClick={() => setSidebarOpen(true)} className="p-2 text-stone-400 hover:text-bible-ink" title="Índice"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" /></svg></button>
               </div>
            )}
          </div>
        </header>

        <div id="bible-content-area" className="flex-1 overflow-y-auto bg-bible-paper p-4 lg:p-10 relative scroll-smooth">

          {viewMode === 'home' && (
             <div className="max-w-6xl mx-auto py-4 animate-fade-in">
                <div className="text-center mb-12">
                   <div className="w-20 h-20 bg-bible-leather rounded-full flex items-center justify-center mx-auto mb-6 shadow-xl border-2 border-bible-gold/20">
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-12 h-12 text-bible-gold">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" />
                      </svg>
                   </div>
                   <h1 className="text-4xl md:text-5xl font-display font-bold text-bible-ink mb-2 tracking-tighter uppercase">ABBA BIBLIA</h1>
                   <p className="text-stone-500 text-base max-w-xl mx-auto italic font-serif opacity-80 leading-relaxed">"Tu palabra es una lámpara que guía mis pies y una luz para mi camino."</p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 px-4">
                   {[
                      { mode: 'reader', label: 'Explorar Biblia', sub: 'Lectura y Contexto', icon: '📖', color: 'from-amber-50 to-orange-50' },
                      { mode: 'devotional', label: 'Devocional', sub: 'Palabra del Día', icon: '🙏', color: 'from-emerald-50 to-teal-50' },
                      { mode: 'plan', label: 'Rutas de Lectura', sub: 'Cronología Bíblica', icon: '📅', color: 'from-blue-50 to-indigo-50' },
                      { mode: 'study', label: 'Academia Bíblica', sub: 'Cursos y Quizzes', icon: '🎓', color: 'from-purple-50 to-fuchsia-50' },
                      { mode: 'mood', label: 'Guía Espiritual', sub: 'Según tu Sentir', icon: '❤️', color: 'from-rose-50 to-red-50' },
                      { mode: 'saved', label: 'Mis Tesoros', sub: 'Notas y Marcas', icon: '🔖', color: 'from-stone-100 to-stone-200' },
                   ].map((item: any) => (
                      <button 
                        key={item.mode} 
                        onClick={() => handleNavigate(item.mode)} 
                        className={`bg-gradient-to-br ${item.color} p-8 rounded-[2.5rem] shadow-sm border border-black/5 hover:shadow-2xl hover:-translate-y-1 transition-all flex flex-col items-center text-center group relative overflow-hidden h-full`}
                      >
                         <span className="text-5xl mb-5 group-hover:scale-110 transition-transform duration-500 block">{item.icon}</span>
                         <h3 className="text-xl font-display font-bold text-bible-ink mb-1">{item.label}</h3>
                         <p className="text-stone-500 text-[10px] font-bold uppercase tracking-widest opacity-60">{item.sub}</p>
                         <div className="absolute -bottom-4 -right-4 w-16 h-16 bg-black/5 rounded-full group-hover:scale-150 transition-transform duration-700"></div>
                      </button>
                   ))}
                </div>

                <div className="mt-12 bg-white/40 backdrop-blur-sm border border-stone-200 p-10 rounded-[3rem] text-center shadow-inner mx-4">
                   <h2 className="text-2xl font-display font-bold text-bible-ink mb-2 tracking-wide">Continúa tu estudio</h2>
                   <p className="text-stone-500 mb-8 text-sm max-w-sm mx-auto">Sumérgete en el conocimiento de Dios a través de las Sagradas Escrituras.</p>
                   <button onClick={() => handleNavigate('reader')} className="bg-bible-leather text-white px-12 py-4 rounded-full font-bold shadow-2xl hover:bg-bible-ink hover:scale-105 transition-all text-xs tracking-widest uppercase">Iniciar Biblia</button>
                </div>
             </div>
          )}

          {viewMode === 'reader' && (
            <div className="max-w-4xl mx-auto">
              {loadingState === LoadingState.IDLE && (
                 <div className="animate-fade-in py-4">
                    <div className="flex flex-col md:flex-row md:items-center justify-between mb-10 border-b border-stone-200 pb-8 gap-4 px-4">
                       <div>
                          <h1 className="text-4xl font-display font-bold text-bible-ink mb-1">Biblioteca Sagrada</h1>
                          <p className="text-stone-500 text-xs tracking-[0.2em] uppercase">Selecciona el Libro del Señor</p>
                       </div>
                       {bibleBrowserView === 'chapters' && (
                          <button 
                            onClick={() => setBibleBrowserView('books')}
                            className="flex items-center gap-2 text-bible-leather font-bold text-xs uppercase tracking-widest bg-stone-200/50 px-6 py-3 rounded-full hover:bg-stone-200 transition-colors"
                          >
                             &larr; Volver a Libros
                          </button>
                       )}
                    </div>

                    {bibleBrowserView === 'books' ? (
                       <div className="space-y-12">
                          {Object.entries(CATEGORY_LABELS).map(([catId, label]) => {
                             const booksInCategory = BIBLE_BOOKS.filter(b => b.category === catId);
                             if (booksInCategory.length === 0) return null;
                             return (
                                <div key={catId} className="px-4">
                                   <h3 className="text-[10px] font-bold text-bible-accent uppercase tracking-[0.4em] mb-6 pl-4 border-l-4 border-bible-gold">{label}</h3>
                                   <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                                      {booksInCategory.map(book => (
                                         <button 
                                           key={book.name}
                                           onClick={() => handleSelectBook(book.name)}
                                           className="p-6 bg-white border border-stone-100 rounded-3xl text-left hover:border-bible-gold hover:shadow-xl transition-all group relative overflow-hidden"
                                         >
                                            <span className="block text-stone-800 font-bold group-hover:text-bible-leather transition-colors relative z-10">{book.name}</span>
                                            <span className="text-[10px] text-stone-400 font-bold uppercase tracking-widest relative z-10">{book.chapters} caps</span>
                                            <div className="absolute -bottom-2 -right-2 text-stone-50 text-4xl font-display font-bold group-hover:text-bible-gold/5 transition-colors">{book.name[0]}</div>
                                         </button>
                                      ))}
                                   </div>
                                </div>
                             )
                          })}
                       </div>
                    ) : (
                       <div className="animate-fade-in text-center py-10">
                          <span className="text-bible-accent text-xs font-bold uppercase tracking-[0.5em] mb-4 block">Libro de</span>
                          <h2 className="text-6xl font-display font-bold text-bible-ink mb-4">{activeBookData?.name}</h2>
                          <div className="w-20 h-1 bg-bible-gold mx-auto mb-12"></div>
                          <div className="grid grid-cols-4 sm:grid-cols-6 md:grid-cols-8 lg:grid-cols-10 gap-4 px-4">
                             {Array.from({ length: activeBookData?.chapters || 0 }, (_, i) => i + 1).map(chap => (
                                <button
                                  key={chap}
                                  onClick={() => handleSelectChapter(chap)}
                                  className="aspect-square flex items-center justify-center text-lg font-bold rounded-2xl bg-white border border-stone-200 text-stone-600 hover:bg-bible-leather hover:text-white hover:border-bible-leather hover:shadow-2xl transition-all transform hover:-translate-y-1"
                                >
                                   {chap}
                                </button>
                             ))}
                          </div>
                       </div>
                    )}
                 </div>
              )}

              {loadingState === LoadingState.LOADING && ( <div className="space-y-8 animate-pulse pt-20 px-4"><div className="h-16 bg-stone-200 rounded-3xl w-1/3 mx-auto"></div><div className="space-y-4 mt-16"><div className="h-4 bg-stone-200 rounded-full w-full"></div><div className="h-4 bg-stone-200 rounded-full w-5/6"></div></div></div> )}

              {loadingState === LoadingState.SUCCESS && data && (
                <div className="animate-fade-in pb-32 relative">
                  <div className="text-center mb-10">
                    <span className="text-bible-accent uppercase tracking-[0.5em] text-[10px] font-bold mb-4 block">Capítulo {data.metadata.chapter_number}</span>
                    <h1 className="text-5xl lg:text-7xl font-display font-bold text-bible-ink leading-tight px-4">{data.metadata.book_name}</h1>
                  </div>

                  <div className="mb-10 max-w-xl mx-auto sticky top-4 z-20 shadow-2xl rounded-[2.5rem] overflow-hidden bg-white/95 backdrop-blur-md border border-stone-200 p-1 flex items-center gap-4 pr-6">
                    <div className="flex-1"><TextAudioPlayer text={data.verses.map(v => v.text).join(' ')} title="Voz de la Palabra" className="border-none" showText={false} onBoundary={handleAudioProgress} /></div>
                    <div className="flex gap-2">
                       <button onClick={() => setFontSize(s => Math.max(14, s - 2))} className="w-8 h-8 flex items-center justify-center bg-stone-100 rounded-full hover:bg-stone-200 transition-colors text-xs font-serif">A-</button>
                       <button onClick={() => setFontSize(s => Math.min(32, s + 2))} className="w-8 h-8 flex items-center justify-center bg-stone-100 rounded-full hover:bg-stone-200 transition-colors text-lg font-serif">A+</button>
                    </div>
                  </div>

                  <div className="space-y-10 px-4">
                    {data.verses.map((verse) => {
                      const noteKey = getNoteKey(data.metadata.book_name, data.metadata.chapter_number, verse.number);
                      const highlightKey = getHighlightKey(data.metadata.book_name, data.metadata.chapter_number, verse.number);
                      const note = userNotes[noteKey];
                      const currentVerseHighlights = verseHighlights[highlightKey] || [];
                      const isEditing = editingNote === noteKey;
                      const isAudioActive = audioActiveVerse === verse.number;
                      let activeCharIndexForVerse = null;
                      if (isAudioActive) {
                          const offsetData = verseOffsets.find(v => v.verse === verse.number);
                          if (offsetData) {
                              const localIndex = globalAudioCharIndex - offsetData.start;
                              if (localIndex >= 0 && localIndex <= (offsetData.end - offsetData.start)) activeCharIndexForVerse = localIndex;
                          }
                      }
                      return (
                        <div id={`verse-${verse.number}`} key={verse.number} className={`relative group transition-all duration-700 rounded-[2rem] p-6 -mx-6 ${isAudioActive ? 'bg-bible-gold/10 border-l-8 border-bible-gold shadow-md' : 'border-l-8 border-transparent'}`} data-verse-number={verse.number}>
                          <div className="absolute -left-8 lg:-left-12 top-6 flex flex-col items-end gap-3 w-8 z-10">
                             <span className={`text-[10px] font-bold font-sans select-none mb-1 transition-all ${isAudioActive ? 'text-bible-gold scale-150' : 'text-bible-gold/30'}`}>{verse.number}</span>
                             <div className={`flex flex-col gap-3 transition-opacity duration-300 ${note ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                                <button onClick={() => setEditingNote(isEditing ? null : noteKey)} className={`p-2 rounded-full shadow-sm bg-white border border-stone-100 ${note ? 'text-yellow-600' : 'text-stone-300 hover:text-bible-accent'}`} title="Nota"><svg xmlns="http://www.w3.org/2000/svg" fill={note ? "currentColor" : "none"} viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path d="M16.862 4.487l1.687-1.688a1.875 1.875 0 112.652 2.652L10.582 16.07a4.5 4.5 0 01-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 011.13-1.897l8.932-8.931zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0115.75 21H5.25A2.25 2.25 0 013 18.75V8.25A2.25 2.25 0 015.25 6H10" /></svg></button>
                                <button onClick={() => handlePlayVerse(verse.number, verse.text)} className={`p-2 rounded-full shadow-sm bg-white border border-stone-100 ${playingVerse === verse.number ? 'text-bible-gold' : 'text-stone-300 hover:text-green-500'}`} title="Oír">{playingVerse === verse.number ? '🔊' : <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path d="M19.114 5.636a9 9 0 010 12.728M16.463 8.288a5.25 5.25 0 010 7.424M6.75 8.25l4.72-4.72a.75.75 0 011.28.53v15.88a.75.75 0 01-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 012.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75z" /></svg>}</button>
                             </div>
                          </div>
                          <div className="rounded-lg px-2"><HighlightableVerse text={verse.text} highlights={currentVerseHighlights} fontSize={fontSize} lineHeight={lineHeight} activeCharIndex={activeCharIndexForVerse} /></div>
                          {isEditing && ( <NoteEditor initialNote={note || ''} onSave={(c) => { localStorage.setItem(noteKey, c); setUserNotes(prev => ({ ...prev, [noteKey]: c })); setEditingNote(null); }} onCancel={() => setEditingNote(null)} onDelete={() => { localStorage.removeItem(noteKey); setUserNotes(p => { const n = {...p}; delete n[noteKey]; return n; }); setEditingNote(null); }} /> )}
                          {!isEditing && note && ( <div onClick={() => setEditingNote(noteKey)} className="ml-4 lg:ml-10 mb-8 p-6 bg-yellow-50 rounded-[2rem] border-l-4 border-yellow-400 cursor-pointer hover:bg-yellow-100 transition-all shadow-sm relative"><div className="absolute -top-4 -left-3 text-3xl">📝</div><p className="font-handwriting text-stone-800 text-base italic leading-relaxed">"{note}"</p></div> )}
                        </div>
                      );
                    })}
                  </div>

                  <div className="mt-20 pt-12 border-t border-stone-200 px-4"><ChapterExplanation explanation={data.metadata.detailed_explanation} /></div>
                  <div className="mt-12 flex justify-center"><button onClick={() => handleSelectChapter(currentChapter + 1)} className="px-14 py-5 bg-bible-leather text-white rounded-full hover:bg-bible-ink transition-all font-display shadow-2xl text-xs tracking-widest uppercase">Siguiente Capítulo</button></div>
                </div>
              )}
            </div>
          )}

          {viewMode === 'saved' && ( <SavedContent onNavigateToVerse={handleSelectVerse} onDeleteItem={(k) => { localStorage.removeItem(k); handleNavigate('saved'); }} /> )}
          {viewMode === 'study' && ( <StudyMode /> )}
          {viewMode === 'mood' && (
             <div className="max-w-4xl mx-auto pt-4 lg:pt-8 px-4">
                {selectedMood ? (
                   <div className="animate-fade-in">
                      <div className="flex items-center gap-2 mb-10 border-b border-stone-200 pb-6">
                        <button onClick={() => { setSelectedMood(''); setMoodResults([]); }} className="text-stone-500 hover:text-bible-gold transition-colors"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-7 h-7"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg></button>
                        <h3 className="text-3xl font-bold text-bible-ink">Versículos para: <span className="text-bible-accent italic">{selectedMood}</span></h3>
                      </div>
                      <div className="space-y-10 pb-20">{moodResults.map((item, idx) => (<div key={idx} className="bg-white p-10 rounded-[3rem] shadow-sm border border-stone-100 hover:shadow-2xl transition-all"><h4 className="font-bold text-bible-leather mb-3 text-xl">{item.verseReference}</h4><p className="font-serif text-3xl text-bible-ink mb-8 italic">"{item.text}"</p><div className="text-base text-stone-600 bg-stone-50 p-8 rounded-3xl border border-stone-100 leading-relaxed font-serif text-justify">{item.explanation}</div></div>))}</div>
                   </div>
                ) : ( <MoodSelector onSelectMood={async (m) => { setSelectedMood(m); setLoadingMood(true); const r = await getVersesByMood(m); setMoodResults(r); setLoadingMood(false); }} /> )}
             </div>
          )}
          {viewMode === 'plan' && ( <div className="max-w-4xl mx-auto px-4"><div className="text-center mb-14 font-display font-bold text-5xl text-bible-ink">Rutas de Lectura</div><ReadingGoalSelector onSelect={() => {}} /></div> )}
          {viewMode === 'devotional' && (
            <div className="max-w-3xl mx-auto pt-8 animate-fade-in px-4">
               <div className="text-center mb-14"><h1 className="text-5xl font-display font-bold text-bible-ink mb-2 tracking-tighter">DEVOCIONAL</h1><p className="text-stone-500 font-bold uppercase tracking-[0.3em] text-[10px]">{new Date().toLocaleDateString('es-ES', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p></div>
               {loadingDevotional ? ( <div className="h-80 bg-white rounded-[4rem] animate-pulse"></div> ) : devotional ? (
                <div className="space-y-12 pb-20 animate-fade-in-up">
                  <div className="bg-white p-16 rounded-[4rem] shadow-2xl border-t-[14px] border-bible-gold text-center relative overflow-hidden"><div className="absolute top-4 left-4 text-stone-100 text-9xl font-serif select-none">"</div><h2 className="text-4xl lg:text-5xl font-serif text-bible-ink leading-tight mb-10 italic relative z-10">"{devotional.verseText}"</h2><p className="text-bible-accent font-bold tracking-[0.5em] uppercase text-xs">{devotional.verseReference}</p></div>
                  <div className="bg-white p-12 rounded-[3rem] shadow-sm border border-stone-100"><TextAudioPlayer text={devotional.reflection} title="Reflexión Pastoral" /></div>
                </div>
               ) : ( <div className="text-center py-24"><button onClick={loadDevotional} className="px-16 py-6 bg-bible-gold text-white rounded-full font-bold shadow-2xl hover:scale-105 active:scale-95 transition-all text-xs tracking-[0.3em]">RECIBIR PALABRA DE HOY</button></div> )}
            </div>
          )}
        </div>
      </div>

      <ContextPanel metadata={data ? data.metadata : null} isOpen={isContextOpen} onClose={() => setContextOpen(false)} isLoading={loadingState === LoadingState.LOADING} />
      <TheologyTutor topic={tutorTopic} isOpen={isReaderTutorOpen} onClose={() => setIsReaderTutorOpen(false)} />
    </div>
  );
}

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { BIBLE_BOOKS, CATEGORY_LABELS, VERSE_COUNTS } from '../constants';
import { BibleBook } from '../types';

interface SidebarProps {
  currentBook: string;
  onSelectBook: (bookName: string) => void;
  onSelectChapter: (chapter: number) => void;
  onSelectVerse: (book: string, chapter: number, verse: number) => void;
  isOpen: boolean;
  onClose: () => void;
  streak?: number;
}

type SidebarView = 'books' | 'chapters' | 'verses';

export const Sidebar: React.FC<SidebarProps> = ({ 
  currentBook, onSelectBook, onSelectChapter, onSelectVerse, isOpen, onClose, streak = 0 
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [view, setView] = useState<SidebarView>('books');
  const [selectedChapter, setSelectedChapter] = useState<number | null>(null);

  useEffect(() => {
    if (currentBook) {
      if (view === 'books') setView('chapters');
    } else {
      setView('books');
      setSelectedChapter(null);
    }
  }, [currentBook]);

  const groupedBooks = useMemo<Record<string, BibleBook[]>>(() => {
    const filtered = BIBLE_BOOKS.filter(b => b.name.toLowerCase().includes(searchTerm.toLowerCase()));
    const groups: Record<string, BibleBook[]> = {};
    filtered.forEach(book => {
      if (!groups[book.category]) groups[book.category] = [];
      groups[book.category].push(book);
    });
    return groups;
  }, [searchTerm]);

  const activeBookData = BIBLE_BOOKS.find(b => b.name === currentBook);

  const handleBookClick = (bookName: string) => {
    onSelectBook(bookName);
    setView('chapters');
    setSelectedChapter(null);
    setSearchTerm('');
  };

  const handleChapterClick = (chapter: number) => {
    setSelectedChapter(chapter);
    setView('verses');
  };

  const handleVerseClick = (verse: number) => {
    if (activeBookData && selectedChapter) {
      onSelectVerse(activeBookData.name, selectedChapter, verse);
      if (window.innerWidth < 1024) onClose();
    }
  };

  const handleBack = () => {
    if (view === 'verses') { setView('chapters'); setSelectedChapter(null); }
    else if (view === 'chapters') { setView('books'); onSelectBook(''); }
  };

  const verseCount = (activeBookData && selectedChapter) 
    ? (VERSE_COUNTS[activeBookData.name]?.[selectedChapter - 1] || 20) 
    : 0;

  return (
    <div className={`fixed inset-y-0 left-0 transform ${isOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 lg:static lg:w-80 bg-white border-r border-stone-200 z-50 transition-transform duration-300 ease-in-out flex flex-col h-full shadow-2xl lg:shadow-none`}>
      <div className="p-6 border-b border-stone-100 bg-bible-paper">
        <div className="flex items-center justify-between mb-8">
           {view === 'books' ? (
             <div className="flex items-center justify-between w-full">
               <h2 className="text-xl font-display font-bold text-bible-ink uppercase tracking-widest">Índice</h2>
               <button onClick={onClose} className="lg:hidden p-2 text-stone-400">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
               </button>
             </div>
           ) : (
             <div className="flex items-center gap-3">
               <button onClick={handleBack} className="p-2.5 rounded-full hover:bg-stone-100 text-stone-500 transition-all">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg>
               </button>
               <h2 className="text-lg font-display font-bold text-bible-ink truncate max-w-[180px]">
                 {view === 'chapters' ? activeBookData?.name : `${activeBookData?.name} ${selectedChapter}`}
               </h2>
             </div>
           )}
        </div>

        {view === 'books' && (
          <div className="relative">
            <input type="text" placeholder="Filtrar libros..." className="w-full px-5 py-3 rounded-2xl bg-stone-100 border-none focus:ring-2 focus:ring-bible-gold outline-none text-sm font-sans" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4 absolute right-4 top-3.5 text-stone-400"><path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" /></svg>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-y-auto p-5 space-y-6 bg-bible-paper custom-scrollbar">
        {view === 'books' && Object.entries(groupedBooks).map(([category, books]: any) => (
          <div key={category} className="mb-8">
            <h3 className="text-[9px] font-bold text-bible-accent uppercase tracking-[0.4em] mb-4 ml-2 opacity-60">{CATEGORY_LABELS[category]}</h3>
            <div className="grid grid-cols-1 gap-1.5">
              {books.map((book: any) => (
                <button key={book.name} onClick={() => handleBookClick(book.name)} className={`w-full text-left px-5 py-3.5 rounded-2xl text-sm font-medium transition-all ${currentBook === book.name ? 'bg-bible-leather text-white shadow-lg' : 'text-stone-600 hover:bg-stone-50 hover:pl-6'}`}>{book.name}</button>
              ))}
            </div>
          </div>
        ))}

        {view === 'chapters' && activeBookData && (
          <div className="animate-fade-in">
            <h3 className="text-[10px] font-bold text-stone-400 uppercase tracking-widest mb-6 px-2">Capítulos:</h3>
            <div className="grid grid-cols-4 gap-2.5">{Array.from({ length: activeBookData.chapters }, (_, i) => i + 1).map(chap => (
                <button key={chap} onClick={() => handleChapterClick(chap)} className="aspect-square flex items-center justify-center text-sm font-bold rounded-2xl hover:bg-bible-gold hover:text-white transition-all bg-white border border-stone-100 text-stone-600 shadow-sm">{chap}</button>
              ))}</div>
          </div>
        )}

        {view === 'verses' && activeBookData && selectedChapter && (
           <div className="animate-fade-in">
              <button onClick={() => { onSelectChapter(selectedChapter); if (window.innerWidth < 1024) onClose(); }} className="w-full mb-8 py-5 bg-bible-gold text-white font-bold text-[10px] uppercase tracking-[0.2em] rounded-[1.5rem] hover:bg-bible-accent transition-all shadow-xl">
                Leer Capítulo
              </button>
              <h3 className="text-[10px] font-bold text-stone-400 uppercase tracking-widest mb-6 px-2">Versículos:</h3>
              <div className="grid grid-cols-5 gap-2">{Array.from({ length: verseCount }, (_, i) => i + 1).map(verse => (
                  <button key={verse} onClick={() => handleVerseClick(verse)} className="aspect-square flex items-center justify-center text-[11px] font-bold rounded-xl hover:bg-bible-accent hover:text-white transition-all bg-white border border-stone-100 text-stone-500 shadow-sm">{verse}</button>
                ))}</div>
           </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ContextPanel } from './components/ContextPanel';
import { NoteEditor } from './components/NoteEditor';
import { ChapterExplanation } from './components/ChapterExplanation';
import { HighlightableVerse } from './components/HighlightableVerse';
import { TextAudioPlayer } from './components/TextAudioPlayer';
import { MoodSelector } from './components/MoodSelector';
import { SavedContent } from './components/SavedContent';
import { StudyMode } from './components/StudyMode';
import { ShareableImage } from './components/ShareableImage';
import { ReadingGoalSelector } from './components/ReadingGoalSelector';
import { TheologyTutor } from './components/TheologyTutor';
import { getBibleChapter, getChronologicalPlan, searchBible, getDailyDevotional, getVersesByMood } from './services/geminiService';
import { ChapterResponse, LoadingState, ReadingPlanItem, SearchResult, DailyDevotional, Highlight, MoodResult } from './types';
import { BIBLE_BOOKS, CATEGORY_LABELS } from './constants';

const getNoteKey = (book: string, chapter: number, verse: number) => `note-${book}-${chapter}-${verse}`;
const getHighlightKey = (book: string, chapter: number, verse: number) => `highlights-v2-${book}-${chapter}-${verse}`;

interface SelectionMenuPosition {
  top: number;
  left: number;
  verseNumber: number;
  range: Range;
}

function App() {
  const [currentBook, setCurrentBook] = useState<string>('');
  const [currentChapter, setCurrentChapter] = useState<number>(1);
  const [data, setData] = useState<ChapterResponse | null>(null);
  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [isContextOpen, setContextOpen] = useState(false);
  const [viewMode, setViewMode] = useState<'home' | 'reader' | 'plan' | 'search' | 'devotional' | 'mood' | 'saved' | 'study'>('home');
  const [chronoPlan, setChronoPlan] = useState<ReadingPlanItem[]>([]);
  const [loadingPlan, setLoadingPlan] = useState(false);
  const [devotional, setDevotional] = useState<DailyDevotional | null>(null);
  const [loadingDevotional, setLoadingDevotional] = useState(false);
  const [moodResults, setMoodResults] = useState<MoodResult[]>([]);
  const [loadingMood, setLoadingMood] = useState(false);
  const [selectedMood, setSelectedMood] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [userNotes, setUserNotes] = useState<Record<string, string>>({});
  const [editingNote, setEditingNote] = useState<string | null>(null); 
  const [verseHighlights, setVerseHighlights] = useState<Record<string, Highlight[]>>({});
  const [selectionMenu, setSelectionMenu] = useState<SelectionMenuPosition | null>(null);
  const [fontSize, setFontSize] = useState<number>(18); 
  const [lineHeight, setLineHeight] = useState<number>(1.625); 
  const [isImageCreatorOpen, setImageCreatorOpen] = useState(false);
  const [selectedVerseForAction, setSelectedVerseForAction] = useState<{number: number, text: string} | null>(null);
  const [isReaderTutorOpen, setIsReaderTutorOpen] = useState(false);
  const [tutorTopic, setTutorTopic] = useState<string>('');
  const [playingVerse, setPlayingVerse] = useState<number | null>(null);
  const [audioActiveVerse, setAudioActiveVerse] = useState<number | null>(null);
  const [globalAudioCharIndex, setGlobalAudioCharIndex] = useState<number>(0);
  const [streakDays, setStreakDays] = useState(0);
  const [bibleBrowserView, setBibleBrowserView] = useState<'books' | 'chapters'>('books');

  const verseOffsets = useMemo(() => {
    if (!data) return [];
    let currentOffset = 0;
    return data.verses.map(v => {
        const start = currentOffset;
        const length = v.text.length;
        currentOffset += length + 1; 
        return { verse: v.number, start, end: start + length };
    });
  }, [data]);

  const handleAudioProgress = (charIndex: number) => {
     setGlobalAudioCharIndex(charIndex); 
     if (!verseOffsets.length) return;
     const match = verseOffsets.find(v => charIndex >= v.start && charIndex <= v.end);
     if (match && match.verse !== audioActiveVerse) {
        setAudioActiveVerse(match.verse);
        const el = document.getElementById(`verse-${match.verse}`);
        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
     }
  };

  useEffect(() => {
    const loadedNotes: Record<string, string> = {};
    const loadedHighlights: Record<string, Highlight[]> = {};
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key) {
        if (key.startsWith('note-')) loadedNotes[key] = localStorage.getItem(key) || '';
        else if (key.startsWith('highlights-v2-')) {
          try { loadedHighlights[key] = JSON.parse(localStorage.getItem(key) || '[]'); } catch (e) {}
        }
      }
    }
    setUserNotes(loadedNotes);
    setVerseHighlights(loadedHighlights);

    const streak = parseInt(localStorage.getItem('currentStreak') || '1');
    setStreakDays(streak);
  }, []);

  const fetchChapter = async (book: string, chapter: number) => {
    setLoadingState(LoadingState.LOADING);
    setData(null);
    setAudioActiveVerse(null);
    setGlobalAudioCharIndex(0);
    setContextOpen(false); 
    try {
      const result = await getBibleChapter(book, chapter);
      setData(result);
      setLoadingState(LoadingState.SUCCESS);
      setTutorTopic(`${result.metadata.book_name} Capítulo ${result.metadata.chapter_number}`);
    } catch (error) {
      setLoadingState(LoadingState.ERROR);
    }
  };

  const handleSelectBook = (book: string) => { 
    setCurrentBook(book); 
    setBibleBrowserView('chapters');
  };

  const handleSelectChapter = (chapter: number) => {
    setCurrentChapter(chapter);
    fetchChapter(currentBook, chapter);
    setViewMode('reader');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSelectVerse = (book: string, chapter: number, verse: number) => {
    if (currentBook === book && currentChapter === chapter && data) {
       setViewMode('reader');
       const el = document.getElementById(`verse-${verse}`);
       if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    } else {
       setCurrentBook(book); setCurrentChapter(chapter);
       fetchChapter(book, chapter); setViewMode('reader');
    }
  };

  const handleGoHome = () => {
    setData(null); setLoadingState(LoadingState.IDLE); setViewMode('home');
    setCurrentBook(''); setCurrentChapter(1); setSearchQuery('');
    setBibleBrowserView('books');
    setContextOpen(false);
  };

  const handleNavigate = (mode: 'reader' | 'plan' | 'devotional' | 'mood' | 'saved' | 'study') => {
    if (mode === 'reader') { 
      setViewMode('reader');
      if (!data) setBibleBrowserView('books');
    }
    else if (mode === 'plan') loadChronologicalPlan();
    else if (mode === 'devotional') loadDevotional();
    else if (mode === 'mood') loadMoodSelector();
    else if (mode === 'saved') { setViewMode('saved'); }
    else if (mode === 'study') { setViewMode('study'); }
  };

  const loadChronologicalPlan = async () => {
    setViewMode('plan');
    if (chronoPlan.length === 0) {
      setLoadingPlan(true);
      try { const plan = await getChronologicalPlan(); setChronoPlan(plan); } catch (e) {} finally { setLoadingPlan(false); }
    }
  };

  const loadDevotional = async () => {
    setViewMode('devotional');
    if (!devotional) {
      setLoadingDevotional(true);
      try { const result = await getDailyDevotional(); setDevotional(result); } catch (e) {} finally { setLoadingDevotional(false); }
    }
  };

  const loadMoodSelector = () => { setViewMode('mood'); setSelectedMood(''); setMoodResults([]); };

  const handleSearch = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!searchQuery.trim()) return;
    setViewMode('search'); setIsSearching(true); setSearchResults([]);
    try { const results = await searchBible(searchQuery); setSearchResults(results); } catch (error) {} finally { setIsSearching(false); }
  };

  const addHighlight = (color: string) => {
    if (!selectionMenu || !data) return;
    const { verseNumber, range } = selectionMenu;
    const selectedText = range.toString();
    const verseEl = document.querySelector(`[data-verse-number="${verseNumber}"]`);
    if (!verseEl) return;
    const preCaretRange = range.cloneRange();
    preCaretRange.selectNodeContents(verseEl);
    preCaretRange.setEnd(range.startContainer, range.startOffset);
    const start = preCaretRange.toString().length;
    const end = start + selectedText.length;
    const key = getHighlightKey(data.metadata.book_name, data.metadata.chapter_number, verseNumber);
    const updatedHighlights = [...(verseHighlights[key] || []), { id: Date.now().toString(), start, end, color, text: selectedText }];
    setVerseHighlights(prev => ({ ...prev, [key]: updatedHighlights }));
    localStorage.setItem(key, JSON.stringify(updatedHighlights));
    setSelectionMenu(null);
    window.getSelection()?.removeAllRanges();
  };

  const handlePlayVerse = (verseNumber: number, text: string) => {
    window.speechSynthesis.cancel();
    if (playingVerse === verseNumber) { setPlayingVerse(null); return; }
    setPlayingVerse(verseNumber);
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'es-ES';
    utterance.onend = () => setPlayingVerse(null);
    window.speechSynthesis.speak(utterance);
  };

  const activeBookData = BIBLE_BOOKS.find(b => b.name === currentBook);

  return (
    <div className="flex h-screen bg-stone-100 overflow-hidden font-sans" onClick={(e) => {
        const target = e.target as HTMLElement;
        if (!target.closest('#highlight-menu') && (!window.getSelection() || window.getSelection()?.isCollapsed)) setSelectionMenu(null);
    }}>

      {selectionMenu && (
        <div id="highlight-menu" className="fixed z-50 bg-white rounded-full shadow-xl border border-stone-200 p-2 flex gap-2 animate-fade-in" style={{ top: selectionMenu.top, left: selectionMenu.left }}>
          {['yellow', 'green', 'blue', 'pink'].map(color => (
            <button key={color} onMouseDown={(e) => { e.preventDefault(); addHighlight(color); }} className={`w-8 h-8 rounded-full bg-${color}-400 hover:scale-110 transition-transform border border-stone-100`} />
          ))}
          <div className="w-px h-8 bg-stone-200 mx-1"></div>
          <button onMouseDown={(e) => { e.preventDefault(); 
             const key = getHighlightKey(data!.metadata.book_name, data!.metadata.chapter_number, selectionMenu.verseNumber);
             setVerseHighlights(prev => ({ ...prev, [key]: [] })); localStorage.removeItem(key); setSelectionMenu(null); window.getSelection()?.removeAllRanges();
          }} className="px-3 py-1 text-xs font-bold text-red-500 hover:bg-red-50 rounded-full">Borrar</button>
        </div>
      )}

      {isImageCreatorOpen && selectedVerseForAction && data && (
         <ShareableImage verseText={selectedVerseForAction.text} verseReference={`${data.metadata.book_name} ${data.metadata.chapter_number}:${selectedVerseForAction.number}`} onClose={() => setImageCreatorOpen(false)} />
      )}

      <div className="flex-1 flex flex-col h-full overflow-hidden relative">
        <header className="bg-white border-b border-stone-200 p-4 flex items-center justify-between shadow-sm z-30">
          <div className="flex items-center gap-2">
            {viewMode !== 'home' && (
              <button onClick={handleGoHome} className="p-2 text-bible-leather flex items-center gap-2 bg-stone-100 rounded-full pr-4 hover:bg-stone-200 transition-colors">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg>
                 <span className="text-xs font-bold uppercase tracking-widest">Inicio</span>
              </button>
            )}
            {viewMode === 'home' && (
              <div className="flex items-center gap-2 px-2">
                <span className="text-xl">🔥</span>
                <span className="text-sm font-bold text-orange-600">{streakDays} días</span>
              </div>
            )}
          </div>

          <form onSubmit={handleSearch} className="flex-1 max-w-md mx-4">
              <div className="relative">
                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Buscar en las Escrituras..." className="w-full bg-stone-100 border-none rounded-full py-2 px-10 text-sm focus:ring-2 focus:ring-bible-gold outline-none" />
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4 absolute left-3.5 top-2.5 text-stone-400"><path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" /></svg>
              </div>
          </form>

          <div className="flex items-center gap-2">
            {viewMode === 'reader' && (
               <div className="flex items-center bg-stone-100 rounded-full p-1 gap-1">
                 {/* BOTÓN ÍNDICE (Reemplaza Sidebar) */}
                 <button onClick={() => { setData(null); setBibleBrowserView('books'); }} className="p-2 text-stone-400 hover:text-bible-ink" title="Índice Bíblico">
                   <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" /></svg>
                 </button>

                 {data && (
                    <>
                      <button 
                        onClick={() => setContextOpen(!isContextOpen)} 
                        className={`p-2 rounded-full transition-all ${isContextOpen ? 'bg-bible-gold text-white shadow-md' : 'text-stone-400 hover:text-bible-gold'}`}
                        title="Análisis Contextual"
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                          <path strokeLinecap="round" strokeLinejoin="round" d="M12 18v-5.25m0 0a6.001 6.001 0 00-5.304-7.618 6.002 6.002 0 019.957 5.304c.42 2.15-1.65 4.314-4.653 2.314zm0 0l-7.05 4.633a1.125 1.125 0 01-1.373-1.634l-.75-7.5M12 18l7.05 4.633a1.125 1.125 0 001.373-1.634l-.75-7.5" />
                        </svg>
                      </button>
                      <button 
                        onClick={() => setIsReaderTutorOpen(true)}
                        className="p-2 text-stone-400 hover:text-bible-leather rounded-full transition-all"
                        title="Asistente Teológico"
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09zM18.259 8.715L18 9.75l-.259-1.035a3.375 3.375 0 00-2.455-2.456L14.25 6l1.036-.259a3.375 3.375 0 002.455-2.456L18 2.25l.259 1.035a3.375 3.375 0 002.456 2.456L21.75 6l-1.035.259a3.375 3.375 0 00-2.456 2.456z" /></svg>
                      </button>
                    </>
                 )}
               </div>
            )}
          </div>
        </header>

        <div id="bible-content-area" className="flex-1 overflow-y-auto bg-bible-paper p-4 lg:p-10 relative scroll-smooth">

          {viewMode === 'home' && (
             <div className="max-w-6xl mx-auto py-4 animate-fade-in">
                <div className="text-center mb-12">
                   <div className="w-20 h-20 bg-bible-leather rounded-full flex items-center justify-center mx-auto mb-6 shadow-xl border-2 border-bible-gold/20">
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-12 h-12 text-bible-gold">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18-3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" />
                      </svg>
                   </div>
                   <h1 className="text-4xl md:text-5xl font-display font-bold text-bible-ink mb-2 tracking-tighter uppercase">ABBA BIBLIA</h1>
                   <p className="text-stone-500 text-base max-w-xl mx-auto italic font-serif opacity-80 leading-relaxed">"Tu palabra es una lámpara que guía mis pies y una luz para mi camino."</p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 px-4">
                   {[
                      { mode: 'reader', label: 'Explorar Biblia', sub: 'Lectura y Contexto', icon: '📖', color: 'from-amber-50 to-orange-50' },
                      { mode: 'devotional', label: 'Devocional', sub: 'Palabra del Día', icon: '🙏', color: 'from-emerald-50 to-teal-50' },
                      { mode: 'plan', label: 'Rutas de Lectura', sub: 'Cronología Bíblica', icon: '📅', color: 'from-blue-50 to-indigo-50' },
                      { mode: 'study', label: 'Academia Bíblica', sub: 'Cursos y Quizzes', icon: '🎓', color: 'from-purple-50 to-fuchsia-50' },
                      { mode: 'mood', label: 'Guía Espiritual', sub: 'Según tu Sentir', icon: '❤️', color: 'from-rose-50 to-red-50' },
                      { mode: 'saved', label: 'Mis Tesoros', sub: 'Notas y Marcas', icon: '🔖', color: 'from-stone-100 to-stone-200' },
                   ].map((item: any) => (
                      <button 
                        key={item.mode} 
                        onClick={() => handleNavigate(item.mode)} 
                        className={`bg-gradient-to-br ${item.color} p-8 rounded-[2.5rem] shadow-sm border border-black/5 hover:shadow-2xl hover:-translate-y-1 transition-all flex flex-col items-center text-center group relative overflow-hidden h-full`}
                      >
                         <span className="text-5xl mb-5 group-hover:scale-110 transition-transform duration-500 block">{item.icon}</span>
                         <h3 className="text-xl font-display font-bold text-bible-ink mb-1">{item.label}</h3>
                         <p className="text-stone-500 text-[10px] font-bold uppercase tracking-widest opacity-60">{item.sub}</p>
                         <div className="absolute -bottom-4 -right-4 w-16 h-16 bg-black/5 rounded-full group-hover:scale-150 transition-transform duration-700"></div>
                      </button>
                   ))}
                </div>
             </div>
          )}

          {viewMode === 'reader' && (
            <div className="max-w-4xl mx-auto">
              {!data && (
                 <div className="animate-fade-in py-4">
                    <div className="flex flex-col md:flex-row md:items-center justify-between mb-10 border-b border-stone-200 pb-8 gap-4 px-4">
                       <div>
                          <h1 className="text-4xl font-display font-bold text-bible-ink mb-1">Biblioteca Sagrada</h1>
                          <p className="text-stone-500 text-xs tracking-[0.2em] uppercase">Selecciona el Libro del Señor</p>
                       </div>
                       {bibleBrowserView === 'chapters' && (
                          <button 
                            onClick={() => setBibleBrowserView('books')}
                            className="flex items-center gap-2 text-bible-leather font-bold text-xs uppercase tracking-widest bg-stone-200/50 px-6 py-3 rounded-full hover:bg-stone-200 transition-colors"
                          >
                             &larr; Volver a Libros
                          </button>
                       )}
                    </div>

                    {bibleBrowserView === 'books' ? (
                       <div className="space-y-12">
                          {Object.entries(CATEGORY_LABELS).map(([catId, label]) => {
                             const booksInCategory = BIBLE_BOOKS.filter(b => b.category === catId);
                             if (booksInCategory.length === 0) return null;
                             return (
                                <div key={catId} className="px-4">
                                   <h3 className="text-[10px] font-bold text-bible-accent uppercase tracking-[0.4em] mb-6 pl-4 border-l-4 border-bible-gold">{label}</h3>
                                   <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                                      {booksInCategory.map(book => (
                                         <button 
                                           key={book.name}
                                           onClick={() => handleSelectBook(book.name)}
                                           className="p-6 bg-white border border-stone-100 rounded-3xl text-left hover:border-bible-gold hover:shadow-xl transition-all group relative overflow-hidden"
                                         >
                                            <span className="block text-stone-800 font-bold group-hover:text-bible-leather transition-colors relative z-10">{book.name}</span>
                                            <span className="text-[10px] text-stone-400 font-bold uppercase tracking-widest relative z-10">{book.chapters} caps</span>
                                            <div className="absolute -bottom-2 -right-2 text-stone-50 text-4xl font-display font-bold group-hover:text-bible-gold/5 transition-colors">{book.name[0]}</div>
                                         </button>
                                      ))}
                                   </div>
                                </div>
                             )
                          })}
                       </div>
                    ) : (
                       <div className="animate-fade-in text-center py-10">
                          <span className="text-bible-accent text-xs font-bold uppercase tracking-[0.5em] mb-4 block">Libro de</span>
                          <h2 className="text-6xl font-display font-bold text-bible-ink mb-4">{activeBookData?.name}</h2>
                          <div className="w-20 h-1 bg-bible-gold mx-auto mb-12"></div>
                          <div className="grid grid-cols-4 sm:grid-cols-6 md:grid-cols-8 lg:grid-cols-10 gap-4 px-4">
                             {Array.from({ length: activeBookData?.chapters || 0 }, (_, i) => i + 1).map(chap => (
                                <button
                                  key={chap}
                                  onClick={() => handleSelectChapter(chap)}
                                  className="aspect-square flex items-center justify-center text-lg font-bold rounded-2xl bg-white border border-stone-200 text-stone-600 hover:bg-bible-leather hover:text-white hover:border-bible-leather hover:shadow-2xl transition-all transform hover:-translate-y-1"
                                >
                                   {chap}
                                </button>
                             ))}
                          </div>
                       </div>
                    )}
                 </div>
              )}

              {loadingState === LoadingState.LOADING && ( <div className="space-y-8 animate-pulse pt-20 px-4"><div className="h-16 bg-stone-200 rounded-3xl w-1/3 mx-auto"></div><div className="space-y-4 mt-16"><div className="h-4 bg-stone-200 rounded-full w-full"></div><div className="h-4 bg-stone-200 rounded-full w-5/6"></div></div></div> )}

              {loadingState === LoadingState.SUCCESS && data && (
                <div className="animate-fade-in pb-32 relative">
                  <div className="text-center mb-10">
                    <span className="text-bible-accent uppercase tracking-[0.5em] text-[10px] font-bold mb-4 block">Capítulo {data.metadata.chapter_number}</span>
                    <h1 className="text-5xl lg:text-7xl font-display font-bold text-bible-ink leading-tight px-4">{data.metadata.book_name}</h1>
                  </div>

                  <div className="mb-10 max-w-xl mx-auto sticky top-4 z-20 shadow-2xl rounded-[2.5rem] overflow-hidden bg-white/95 backdrop-blur-md border border-stone-200 p-1 flex items-center gap-4 pr-6">
                    <div className="flex-1"><TextAudioPlayer text={data.verses.map(v => v.text).join(' ')} title="Voz de la Palabra" className="border-none" showText={false} onBoundary={handleAudioProgress} /></div>
                    <div className="flex gap-2">
                       <button onClick={() => setFontSize(s => Math.max(14, s - 2))} className="w-8 h-8 flex items-center justify-center bg-stone-100 rounded-full hover:bg-stone-200 transition-colors text-xs font-serif">A-</button>
                       <button onClick={() => setFontSize(s => Math.min(32, s + 2))} className="w-8 h-8 flex items-center justify-center bg-stone-100 rounded-full hover:bg-stone-200 transition-colors text-lg font-serif">A+</button>
                    </div>
                  </div>

                  <div className="space-y-10 px-4">
                    {data.verses.map((verse) => {
                      const noteKey = getNoteKey(data.metadata.book_name, data.metadata.chapter_number, verse.number);
                      const highlightKey = getHighlightKey(data.metadata.book_name, data.metadata.chapter_number, verse.number);
                      const note = userNotes[noteKey];
                      const currentVerseHighlights = verseHighlights[highlightKey] || [];
                      const isEditing = editingNote === noteKey;
                      const isAudioActive = audioActiveVerse === verse.number;
                      let activeCharIndexForVerse = null;
                      if (isAudioActive) {
                          const offsetData = verseOffsets.find(v => v.verse === verse.number);
                          if (offsetData) {
                              const localIndex = globalAudioCharIndex - offsetData.start;
                              if (localIndex >= 0 && localIndex <= (offsetData.end - offsetData.start)) activeCharIndexForVerse = localIndex;
                          }
                      }
                      return (
                        <div id={`verse-${verse.number}`} key={verse.number} className={`relative group transition-all duration-700 rounded-[2rem] p-6 -mx-6 ${isAudioActive ? 'bg-bible-gold/10 border-l-8 border-bible-gold shadow-md' : 'border-l-8 border-transparent'}`} data-verse-number={verse.number}>
                          <div className="absolute -left-8 lg:-left-12 top-6 flex flex-col items-end gap-3 w-8 z-10">
                             <span className={`text-[10px] font-bold font-sans select-none mb-1 transition-all ${isAudioActive ? 'text-bible-gold scale-150' : 'text-bible-gold/30'}`}>{verse.number}</span>
                             <div className={`flex flex-col gap-3 transition-opacity duration-300 ${note ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                                <button onClick={() => setEditingNote(isEditing ? null : noteKey)} className={`p-2 rounded-full shadow-sm bg-white border border-stone-100 ${note ? 'text-yellow-600' : 'text-stone-300 hover:text-bible-accent'}`} title="Nota"><svg xmlns="http://www.w3.org/2000/svg" fill={note ? "currentColor" : "none"} viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path d="M16.862 4.487l1.687-1.688a1.875 1.875 0 112.652 2.652L10.582 16.07a4.5 4.5 0 01-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 011.13-1.897l8.932-8.931zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0115.75 21H5.25A2.25 2.25 0 013 18.75V8.25A2.25 2.25 0 015.25 6H10" /></svg></button>
                                <button onClick={() => handlePlayVerse(verse.number, verse.text)} className={`p-2 rounded-full shadow-sm bg-white border border-stone-100 ${playingVerse === verse.number ? 'text-bible-gold' : 'text-stone-300 hover:text-green-500'}`} title="Oír">{playingVerse === verse.number ? '🔊' : <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path d="M19.114 5.636a9 9 0 010 12.728M16.463 8.288a5.25 5.25 0 010 7.424M6.75 8.25l4.72-4.72a.75.75 0 011.28.53v15.88a.75.75 0 01-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 012.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75z" /></svg>}</button>
                             </div>
                          </div>
                          <div className="rounded-lg px-2"><HighlightableVerse text={verse.text} highlights={currentVerseHighlights} fontSize={fontSize} lineHeight={lineHeight} activeCharIndex={activeCharIndexForVerse} /></div>
                          {isEditing && ( <NoteEditor initialNote={note || ''} onSave={(c) => { localStorage.setItem(noteKey, c); setUserNotes(prev => ({ ...prev, [noteKey]: c })); setEditingNote(null); }} onCancel={() => setEditingNote(null)} onDelete={() => { localStorage.removeItem(noteKey); setUserNotes(p => { const n = {...p}; delete n[noteKey]; return n; }); setEditingNote(null); }} /> )}
                          {!isEditing && note && ( <div onClick={() => setEditingNote(noteKey)} className="ml-4 lg:ml-10 mb-8 p-6 bg-yellow-50 rounded-[2rem] border-l-4 border-yellow-400 cursor-pointer hover:bg-yellow-100 transition-all shadow-sm relative"><div className="absolute -top-4 -left-3 text-3xl">📝</div><p className="font-handwriting text-stone-800 text-base italic leading-relaxed">"{note}"</p></div> )}
                        </div>
                      );
                    })}
                  </div>

                  <div className="mt-20 pt-12 border-t border-stone-200 px-4"><ChapterExplanation explanation={data.metadata.detailed_explanation} /></div>
                  <div className="mt-12 flex justify-center">
                    <button onClick={() => handleSelectChapter(currentChapter + 1)} className="px-14 py-5 bg-bible-leather text-white rounded-full hover:bg-bible-ink transition-all font-display shadow-2xl text-xs tracking-widest uppercase">
                       Siguiente Capítulo
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {viewMode === 'saved' && ( <SavedContent onNavigateToVerse={handleSelectVerse} onDeleteItem={(k) => { localStorage.removeItem(k); handleNavigate('saved'); }} /> )}
          {viewMode === 'study' && ( <StudyMode /> )}
          {viewMode === 'mood' && (
             <div className="max-w-4xl mx-auto pt-4 lg:pt-8 px-4">
                {selectedMood ? (
                   <div className="animate-fade-in">
                      <div className="flex items-center gap-2 mb-10 border-b border-stone-200 pb-6">
                        <button onClick={() => { setSelectedMood(''); setMoodResults([]); }} className="text-stone-500 hover:text-bible-gold transition-colors"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-7 h-7"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg></button>
                        <h3 className="text-3xl font-bold text-bible-ink">Versículos para: <span className="text-bible-accent italic">{selectedMood}</span></h3>
                      </div>
                      <div className="space-y-10 pb-20">{moodResults.map((item, idx) => (<div key={idx} className="bg-white p-10 rounded-[3rem] shadow-sm border border-stone-100 hover:shadow-2xl transition-all"><h4 className="font-bold text-bible-leather mb-3 text-xl">{item.verseReference}</h4><p className="font-serif text-3xl text-bible-ink mb-8 italic">"{item.text}"</p><div className="text-base text-stone-600 bg-stone-50 p-8 rounded-3xl border border-stone-100 leading-relaxed font-serif text-justify">{item.explanation}</div></div>))}</div>
                   </div>
                ) : ( <MoodSelector onSelectMood={async (m) => { setSelectedMood(m); setLoadingMood(true); const r = await getVersesByMood(m); setMoodResults(r); setLoadingMood(false); }} /> )}
             </div>
          )}
          {viewMode === 'plan' && ( <div className="max-w-4xl mx-auto px-4"><div className="text-center mb-14 font-display font-bold text-5xl text-bible-ink">Rutas de Lectura</div><ReadingGoalSelector onSelect={() => {}} /></div> )}
          {viewMode === 'devotional' && (
            <div className="max-w-3xl mx-auto pt-8 animate-fade-in px-4">
               <div className="text-center mb-14"><h1 className="text-5xl font-display font-bold text-bible-ink mb-2 tracking-tighter">DEVOCIONAL</h1><p className="text-stone-500 font-bold uppercase tracking-[0.3em] text-[10px]">{new Date().toLocaleDateString('es-ES', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p></div>
               {loadingDevotional ? ( <div className="h-80 bg-white rounded-[4rem] animate-pulse"></div> ) : devotional ? (
                <div className="space-y-12 pb-20 animate-fade-in-up">
                  <div className="bg-white p-16 rounded-[4rem] shadow-2xl border-t-[14px] border-bible-gold text-center relative overflow-hidden"><div className="absolute top-4 left-4 text-stone-100 text-9xl font-serif select-none">"</div><h2 className="text-4xl lg:text-5xl font-serif text-bible-ink leading-tight mb-10 italic relative z-10">"{devotional.verseText}"</h2><p className="text-bible-accent font-bold tracking-[0.5em] uppercase text-xs">{devotional.verseReference}</p></div>
                  <div className="bg-white p-12 rounded-[3rem] shadow-sm border border-stone-100"><TextAudioPlayer text={devotional.reflection} title="Reflexión Pastoral" /></div>
                </div>
               ) : ( <div className="text-center py-24"><button onClick={loadDevotional} className="px-16 py-6 bg-bible-gold text-white rounded-full font-bold shadow-2xl hover:scale-105 active:scale-95 transition-all text-xs tracking-[0.3em]">RECIBIR PALABRA DE HOY</button></div> )}
            </div>
          )}
        </div>
      </div>

      <ContextPanel metadata={data ? data.metadata : null} isOpen={isContextOpen} onClose={() => setContextOpen(false)} isLoading={loadingState === LoadingState.LOADING} />
      <TheologyTutor topic={tutorTopic} isOpen={isReaderTutorOpen} onClose={() => setIsReaderTutorOpen(false)} />
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { ChapterMetadata } from '../types';

interface ContextPanelProps {
  metadata: ChapterMetadata | null;
  isOpen: boolean;
  onClose: () => void;
  isLoading: boolean;
}

export const ContextPanel: React.FC<ContextPanelProps> = ({ metadata, isOpen, onClose, isLoading }) => {
  const [showCopyFeedback, setShowCopyFeedback] = useState(false);

  // El panel ahora siempre depende de isOpen para ser visible
  if (!isOpen) return null;

  const handleShare = async () => {
    try {
      await navigator.clipboard.writeText(window.location.href);
      setShowCopyFeedback(true);
      setTimeout(() => setShowCopyFeedback(false), 2000);
    } catch (err) {
      console.error('Failed to copy', err);
    }
  };

  return (
    <div className="fixed inset-y-0 right-0 w-full sm:w-96 bg-white border-l border-stone-200 z-[100] transition-transform duration-300 ease-in-out flex flex-col h-full shadow-2xl overflow-y-auto animate-slide-in-right">
      <div className="p-6">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-display font-bold text-bible-ink">Análisis Contextual</h2>

          <div className="flex items-center gap-2">
            <button 
              onClick={handleShare} 
              className="p-2 text-stone-400 hover:text-bible-gold transition-colors rounded-full hover:bg-stone-100 relative group"
              title="Copiar enlace"
            >
              {showCopyFeedback ? (
                <span className="text-xs font-bold text-green-600 animate-fade-in px-1">¡Copiado!</span>
