        {isLoading ? (
          <div className="space-y-6 animate-pulse">
            <div className="h-8 bg-stone-200 rounded w-3/4"></div>
            <div className="h-32 bg-stone-200 rounded"></div>
            <div className="h-20 bg-stone-200 rounded"></div>
            <div className="h-40 bg-stone-200 rounded"></div>
          </div>
        ) : metadata ? (
          <div className="space-y-8 pb-10">
            {/* Quick Stats */}
            <div className="bg-stone-50 p-4 rounded-xl border border-stone-100">
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div>
                  <span className="block text-[10px] text-stone-400 uppercase tracking-wider font-bold mb-1">Autor</span>
                  <p className="font-serif text-bible-leather">{metadata.author}</p>
                </div>
                <div>
                  <span className="block text-[10px] text-stone-400 uppercase tracking-wider font-bold mb-1">Fecha</span>
                  <p className="font-serif text-bible-leather">{metadata.estimated_date}</p>
                </div>
              </div>
            </div>

            {/* Audience & Setting */}
            <div>
              <h3 className="flex items-center gap-2 text-[10px] font-bold text-bible-accent uppercase tracking-widest mb-3">Audiencia Original</h3>
              <p className="text-stone-700 leading-relaxed text-sm bg-white p-4 rounded-xl border border-stone-100 shadow-sm">{metadata.target_audience}</p>
            </div>

            {/* Historical Context */}
            <div>
              <h3 className="flex items-center gap-2 text-[10px] font-bold text-bible-accent uppercase tracking-widest mb-3">Escenario Histórico</h3>
              <p className="text-stone-700 leading-relaxed text-sm bg-white p-4 rounded-xl border border-stone-100 shadow-sm">{metadata.historical_setting}</p>
            </div>

             {/* Theme */}
             <div>
              <h3 className="flex items-center gap-2 text-[10px] font-bold text-bible-accent uppercase tracking-widest mb-3">Tema Teológico</h3>
              <div className="bg-bible-gold/5 p-5 rounded-xl border-l-4 border-bible-gold shadow-sm">
                <p className="text-bible-ink italic font-serif text-sm leading-relaxed">{metadata.theological_theme}</p>
              </div>
            </div>

            {/* Key Quotes */}
            {metadata.key_quotes && metadata.key_quotes.length > 0 && (
              <div>
                <h3 className="flex items-center gap-2 text-[10px] font-bold text-bible-accent uppercase tracking-widest mb-3">Enseñanzas Clave</h3>
                <div className="space-y-3">
                  {metadata.key_quotes.map((quote, idx) => (
                    <blockquote key={idx} className="relative bg-stone-50 p-4 rounded-xl border-l-2 border-stone-300">
                      <p className="text-stone-600 font-serif italic text-sm leading-relaxed">
                        "{quote}"
