                        "{quote}"
                      </p>
                    </blockquote>
                  ))}
                </div>
              </div>
            )}
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center h-full text-center text-stone-400 p-8">
            <p>Selecciona un capítulo para ver el análisis contextual.</p>
          </div>
        )}
      </div>
    </div>
  );
};

