export const ReadingGoalSelector: React.FC<ReadingGoalSelectorProps> = ({ onNavigateToBible }) => {
  const [stats, setStats] = useState<UserStats>({
    points: 0,
    streak: 0,
    completedDays: [],
    rank: 'Principiante',
    unlockedBadges: [],
  });

  const [showReward, setShowReward] = useState<Badge | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem('abba_user_stats');
    if (saved) setStats(JSON.parse(saved));
  }, []);

  const saveStats = (newStats: UserStats) => {
    setStats(newStats);
    localStorage.setItem('abba_user_stats', JSON.stringify(newStats));
  };

  const handleSelectGoal = (goalId: string) => {
    saveStats({ ...stats, currentPlanId: goalId });
  };

  const completeToday = () => {
    const today = new Date().toISOString().split('T')[0];
    if (stats.completedDays.includes(today)) return;

    const newPoints = stats.points + 50;
    const newCompletedDays = [...stats.completedDays, today];

    // Check for rank up
    let newRank = stats.rank;
    if (newPoints > 1000) newRank = 'Maestro de la Palabra';
    else if (newPoints > 500) newRank = 'Experto';
    else if (newPoints > 200) newRank = 'Avanzado';

    // Check for badges
    let newBadges = [...stats.unlockedBadges];
    let justUnlocked: Badge | null = null;

    if (!newBadges.includes('first_day')) {
      newBadges.push('first_day');
      justUnlocked = ALL_BADGES.find(b => b.id === 'first_day')!;
    }

    const updatedStats: UserStats = {
      ...stats,
      points: newPoints,
      completedDays: newCompletedDays,
      rank: newRank,
      unlockedBadges: newBadges,
      streak: stats.streak + 1
    };

    saveStats(updatedStats);
    if (justUnlocked) {
      setShowReward(justUnlocked);
      setTimeout(() => setShowReward(null), 5000);
    }
  };

  const activeGoal = goals.find(g => g.id === stats.currentPlanId);

  // Simulación de lectura del día
  const getDailyReading = () => {
    const dayIndex = stats.completedDays.length;
    // En una app real esto vendría de una tabla de mapping
    return { book: 'Génesis', chapters: [1, 2, 3] };
  };

  if (!stats.currentPlanId) {
    return (
      <div className="animate-fade-in space-y-6">
        <div className="text-center mb-10">
          <p className="text-stone-500 max-w-md mx-auto">Elige la intensidad de tu viaje a través de las Escrituras. Podrás ganar insignias y subir de rango conforme avances.</p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {goals.map((goal) => (
            <button
              key={goal.id}
              onClick={() => handleSelectGoal(goal.id)}
              className="p-8 rounded-[2rem] bg-white border border-stone-200 text-left hover:border-bible-gold hover:shadow-xl transition-all group"
            >
              <div className="flex justify-between items-start mb-4">
                <span className="text-2xl font-display font-bold text-bible-ink">{goal.label}</span>
                <span className="text-[10px] font-bold bg-bible-gold/10 text-bible-gold px-3 py-1 rounded-full uppercase tracking-widest">{goal.days} días</span>
              </div>
              <p className="text-stone-500 text-sm mb-6 leading-relaxed">{goal.description}</p>
              <div className="flex items-center gap-2 text-bible-accent font-bold text-xs uppercase tracking-tighter">
                <span className="w-8 h-px bg-bible-accent/30"></span>
                Seleccionar Plan
              </div>
            </button>
          ))}
        </div>
      </div>
    );
  }

  const todayReading = getDailyReading();

  return (
    <div className="animate-fade-in max-w-4xl mx-auto space-y-8 pb-20">
      {/* Badge Notification */}
      {showReward && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[200] bg-bible-ink text-white p-6 rounded-[2.5rem] shadow-2xl flex items-center gap-6 border-2 border-bible-gold animate-bounce">
          <span className="text-5xl">{showReward.icon}</span>
          <div>
            <h4 className="font-bold text-bible-gold uppercase tracking-widest text-xs mb-1">¡Insignia Desbloqueada!</h4>
            <p className="font-display text-xl">{showReward.name}</p>
          </div>
        </div>
      )}

      {/* Stats Header */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white p-6 rounded-[2rem] border border-stone-200 shadow-sm flex items-center gap-4">
          <div className="w-12 h-12 bg-orange-100 rounded-full flex items-center justify-center text-2xl">🔥</div>
          <div>
            <span className="block text-[10px] font-bold text-stone-400 uppercase tracking-widest">Racha</span>
            <span className="text-xl font-bold text-bible-ink">{stats.streak} Días</span>
          </div>
        </div>
        <div className="bg-white p-6 rounded-[2rem] border border-stone-200 shadow-sm flex items-center gap-4">
          <div className="w-12 h-12 bg-bible-gold/20 rounded-full flex items-center justify-center text-2xl">⭐</div>
          <div>
            <span className="block text-[10px] font-bold text-stone-400 uppercase tracking-widest">Puntos</span>
            <span className="text-xl font-bold text-bible-ink">{stats.points} XP</span>
          </div>
