        <div className="bg-white p-6 rounded-[2rem] border border-stone-200 shadow-sm flex items-center gap-4">
          <div className="w-12 h-12 bg-bible-leather/10 rounded-full flex items-center justify-center text-2xl">🎖️</div>
          <div>
            <span className="block text-[10px] font-bold text-stone-400 uppercase tracking-widest">Rango</span>
            <span className="text-xl font-bold text-bible-leather">{stats.rank}</span>
          </div>
        </div>
      </div>

      {/* Main Reading Card */}
      <div className="bg-white p-10 rounded-[3rem] shadow-xl border-t-[10px] border-bible-gold relative overflow-hidden">
        <div className="relative z-10">
          <h3 className="text-xs font-bold text-bible-accent uppercase tracking-[0.4em] mb-6">Tarea de Hoy - Día {stats.completedDays.length + 1}</h3>
          <h2 className="text-4xl md:text-5xl font-display font-bold text-bible-ink mb-2">{todayReading.book}</h2>
          <p className="text-stone-500 mb-10 text-lg">Capítulos {todayReading.chapters.join(', ')}</p>

          <div className="flex flex-col sm:flex-row gap-4">
            <button 
              onClick={() => onNavigateToBible(todayReading.book, todayReading.chapters[0])}
              className="flex-1 bg-stone-100 text-bible-leather py-5 rounded-full font-bold hover:bg-stone-200 transition-all uppercase tracking-widest text-xs flex items-center justify-center gap-3"
            >
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-4 h-4"><path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" /></svg>
              Comenzar Lectura
            </button>
            <button 
              onClick={completeToday}
              disabled={stats.completedDays.includes(new Date().toISOString().split('T')[0])}
              className={`flex-1 py-5 rounded-full font-bold transition-all uppercase tracking-widest text-xs flex items-center justify-center gap-3 shadow-lg ${stats.completedDays.includes(new Date().toISOString().split('T')[0]) ? 'bg-green-100 text-green-600' : 'bg-bible-gold text-white hover:bg-bible-leather hover:scale-105'}`}
            >
              {stats.completedDays.includes(new Date().toISOString().split('T')[0]) ? (
                <>
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" /></svg>
                  Completado
                </>
              ) : (
                'Marcar como Hecho'
              )}
