        </div>
        <div className="absolute top-0 right-0 p-8 opacity-5">
           <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-64 h-64"><path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" /></svg>
        </div>
      </div>

      {/* Badge Gallery */}
      <div>
        <h3 className="text-sm font-bold text-stone-400 uppercase tracking-[0.3em] mb-6 px-4">Tus Insignias</h3>
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-4 px-4">
          {ALL_BADGES.map(badge => {
            const isUnlocked = stats.unlockedBadges.includes(badge.id);
            return (
              <div key={badge.id} className={`p-6 rounded-[2rem] flex flex-col items-center text-center transition-all ${isUnlocked ? 'bg-white shadow-md border border-bible-gold/20' : 'bg-stone-50 border border-stone-100 opacity-40 grayscale'}`}>
