      </div>

      <div className="text-center px-4">
        <button onClick={() => saveStats({ ...stats, currentPlanId: undefined })} className="text-xs font-bold text-red-400 hover:text-red-600 transition-colors uppercase tracking-widest">Cancelar y elegir otro plan</button>
      </div>
    </div>
  );
};

