              {loadingState === LoadingState.LOADING && ( <div className="space-y-8 animate-pulse pt-20 px-4"><div className="h-16 bg-stone-200 rounded-3xl w-1/3 mx-auto"></div><div className="space-y-4 mt-16"><div className="h-4 bg-stone-200 rounded-full w-full"></div><div className="h-4 bg-stone-200 rounded-full w-5/6"></div></div></div> )}

              {loadingState === LoadingState.SUCCESS && data && (
                <div className="animate-fade-in pb-32 relative">
                  <div className="text-center mb-10">
                    <span className="text-bible-accent uppercase tracking-[0.5em] text-[10px] font-bold mb-4 block">Capítulo {data.metadata.chapter_number}</span>
                    <h1 className="text-5xl lg:text-7xl font-display font-bold text-bible-ink leading-tight px-4">{data.metadata.book_name}</h1>
                  </div>

                  <div className="mb-10 max-w-xl mx-auto sticky top-4 z-20 shadow-2xl rounded-[2.5rem] overflow-hidden bg-white/95 backdrop-blur-md border border-stone-200 p-1 flex items-center gap-4 pr-6">
                    <div className="flex-1"><TextAudioPlayer text={data.verses.map(v => v.text).join(' ')} title="Voz de la Palabra" className="border-none" showText={false} onBoundary={handleAudioProgress} /></div>
                    <div className="flex gap-2">
                       <button onClick={() => setFontSize(s => Math.max(14, s - 2))} className="w-8 h-8 flex items-center justify-center bg-stone-100 rounded-full hover:bg-stone-200 transition-colors text-xs font-serif">A-</button>
                       <button onClick={() => setFontSize(s => Math.min(32, s + 2))} className="w-8 h-8 flex items-center justify-center bg-stone-100 rounded-full hover:bg-stone-200 transition-colors text-lg font-serif">A+</button>
                    </div>
                  </div>

                  <div className="space-y-10 px-4">
                    {data.verses.map((verse) => {
                      const noteKey = getNoteKey(data.metadata.book_name, data.metadata.chapter_number, verse.number);
                      const highlightKey = getHighlightKey(data.metadata.book_name, data.metadata.chapter_number, verse.number);
                      const note = userNotes[noteKey];
                      const currentVerseHighlights = verseHighlights[highlightKey] || [];
                      const isEditing = editingNote === noteKey;
                      const isAudioActive = audioActiveVerse === verse.number;
                      let activeCharIndexForVerse = null;
                      if (isAudioActive) {
                          const offsetData = verseOffsets.find(v => v.verse === verse.number);
                          if (offsetData) {
                              const localIndex = globalAudioCharIndex - offsetData.start;
                              if (localIndex >= 0 && localIndex <= (offsetData.end - offsetData.start)) activeCharIndexForVerse = localIndex;
                          }
                      }
                      return (
                        <div id={`verse-${verse.number}`} key={verse.number} className={`relative group transition-all duration-700 rounded-[2rem] p-6 -mx-6 ${isAudioActive ? 'bg-bible-gold/10 border-l-8 border-bible-gold shadow-md' : 'border-l-8 border-transparent'}`} data-verse-number={verse.number}>
                          <div className="absolute -left-8 lg:-left-12 top-6 flex flex-col items-end gap-3 w-8 z-10">
                             <span className={`text-[10px] font-bold font-sans select-none mb-1 transition-all ${isAudioActive ? 'text-bible-gold scale-150' : 'text-bible-gold/30'}`}>{verse.number}</span>
                             <div className={`flex flex-col gap-3 transition-opacity duration-300 ${note ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}>
                                <button onClick={() => setEditingNote(isEditing ? null : noteKey)} className={`p-2 rounded-full shadow-sm bg-white border border-stone-100 ${note ? 'text-yellow-600' : 'text-stone-300 hover:text-bible-accent'}`} title="Nota"><svg xmlns="http://www.w3.org/2000/svg" fill={note ? "currentColor" : "none"} viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path d="M16.862 4.487l1.687-1.688a1.875 1.875 0 112.652 2.652L10.582 16.07a4.5 4.5 0 01-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 011.13-1.897l8.932-8.931zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0115.75 21H5.25A2.25 2.25 0 013 18.75V8.25A2.25 2.25 0 015.25 6H10" /></svg></button>
                                <button onClick={() => handlePlayVerse(verse.number, verse.text)} className={`p-2 rounded-full shadow-sm bg-white border border-stone-100 ${playingVerse === verse.number ? 'text-bible-gold' : 'text-stone-300 hover:text-green-500'}`} title="Oír">{playingVerse === verse.number ? '🔊' : <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4"><path d="M19.114 5.636a9 9 0 010 12.728M16.463 8.288a5.25 5.25 0 010 7.424M6.75 8.25l4.72-4.72a.75.75 0 011.28.53v15.88a.75.75 0 01-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 012.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75z" /></svg>}</button>
                             </div>
                          </div>
                          <div className="rounded-lg px-2"><HighlightableVerse text={verse.text} highlights={currentVerseHighlights} fontSize={fontSize} lineHeight={lineHeight} activeCharIndex={activeCharIndexForVerse} /></div>
                          {isEditing && ( <NoteEditor initialNote={note || ''} onSave={(c) => { localStorage.setItem(noteKey, c); setUserNotes(prev => ({ ...prev, [noteKey]: c })); setEditingNote(null); }} onCancel={() => setEditingNote(null)} onDelete={() => { localStorage.removeItem(noteKey); setUserNotes(p => { const n = {...p}; delete n[noteKey]; return n; }); setEditingNote(null); }} /> )}
                          {!isEditing && note && ( <div onClick={() => setEditingNote(noteKey)} className="ml-4 lg:ml-10 mb-8 p-6 bg-yellow-50 rounded-[2rem] border-l-4 border-yellow-400 cursor-pointer hover:bg-yellow-100 transition-all shadow-sm relative"><div className="absolute -top-4 -left-3 text-3xl">📝</div><p className="font-handwriting text-stone-800 text-base italic leading-relaxed">"{note}"</p></div> )}
                        </div>
                      );
                    })}
                  </div>

                  <div className="mt-20 pt-12 border-t border-stone-200 px-4"><ChapterExplanation explanation={data.metadata.detailed_explanation} /></div>
                  <div className="mt-12 flex justify-center">
                    <button onClick={() => handleSelectChapter(currentChapter + 1)} className="px-14 py-5 bg-bible-leather text-white rounded-full hover:bg-bible-ink transition-all font-display shadow-2xl text-xs tracking-widest uppercase">
                       Siguiente Capítulo
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {viewMode === 'saved' && ( <SavedContent onNavigateToVerse={handleSelectVerse} onDeleteItem={(k) => { localStorage.removeItem(k); handleNavigate('saved'); }} /> )}
          {viewMode === 'study' && ( <StudyMode /> )}
          {viewMode === 'mood' && (
             <div className="max-w-4xl mx-auto pt-4 lg:pt-8 px-4">
                {selectedMood ? (
                   <div className="animate-fade-in">
                      <div className="flex items-center gap-2 mb-10 border-b border-stone-200 pb-6">
                        <button onClick={() => { setSelectedMood(''); setMoodResults([]); }} className="text-stone-500 hover:text-bible-gold transition-colors"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-7 h-7"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg></button>
                        <h3 className="text-3xl font-bold text-bible-ink">Versículos para: <span className="text-bible-accent italic">{selectedMood}</span></h3>
                      </div>
                      <div className="space-y-10 pb-20">{moodResults.map((item, idx) => (<div key={idx} className="bg-white p-10 rounded-[3rem] shadow-sm border border-stone-100 hover:shadow-2xl transition-all"><h4 className="font-bold text-bible-leather mb-3 text-xl">{item.verseReference}</h4><p className="font-serif text-3xl text-bible-ink mb-8 italic">"{item.text}"</p><div className="text-base text-stone-600 bg-stone-50 p-8 rounded-3xl border border-stone-100 leading-relaxed font-serif text-justify">{item.explanation}</div></div>))}</div>
                   </div>
                ) : ( <MoodSelector onSelectMood={async (m) => { setSelectedMood(m); setLoadingMood(true); const r = await getVersesByMood(m); setMoodResults(r); setLoadingMood(false); }} /> )}
             </div>
          )}
          {viewMode === 'plan' && ( 
            <div className="max-w-4xl mx-auto px-4">
              <div className="text-center mb-14 font-display font-bold text-5xl text-bible-ink">Rutas de Lectura</div>
              {/* Fix: Wrap handleSelectVerse to ensure compatibility with (book, chapter) => void signature */}
              <ReadingGoalSelector onNavigateToBible={(book, chapter) => handleSelectVerse(book, chapter, 1)} />
            </div> 
          )}
          {viewMode === 'devotional' && (
            <div className="max-w-3xl mx-auto pt-8 animate-fade-in px-4">
               <div className="text-center mb-14"><h1 className="text-5xl font-display font-bold text-bible-ink mb-2 tracking-tighter">DEVOCIONAL</h1><p className="text-stone-500 font-bold uppercase tracking-[0.3em] text-[10px]">{new Date().toLocaleDateString('es-ES', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p></div>
               {loadingDevotional ? ( <div className="h-80 bg-white rounded-[4rem] animate-pulse"></div> ) : devotional ? (
                <div className="space-y-12 pb-20 animate-fade-in-up">
                  <div className="bg-white p-16 rounded-[4rem] shadow-2xl border-t-[14px] border-bible-gold text-center relative overflow-hidden"><div className="absolute top-4 left-4 text-stone-100 text-9xl font-serif select-none">"</div><h2 className="text-4xl lg:text-5xl font-serif text-bible-ink leading-tight mb-10 italic relative z-10">"{devotional.verseText}"</h2><p className="text-bible-accent font-bold tracking-[0.5em] uppercase text-xs">{devotional.verseReference}</p></div>
                  <div className="bg-white p-12 rounded-[3rem] shadow-sm border border-stone-100"><TextAudioPlayer text={devotional.reflection} title="Reflexión Pastoral" /></div>
                </div>
               ) : ( <div className="text-center py-24"><button onClick={loadDevotional} className="px-16 py-6 bg-bible-gold text-white rounded-full font-bold shadow-2xl hover:scale-105 active:scale-95 transition-all text-xs tracking-[0.3em]">RECIBIR PALABRA DE HOY</button></div> )}
            </div>
          )}
        </div>
      </div>

      {/* Overlay Context Panel: Only visible when explicitly opened */}
      {isContextOpen && (
        <>
          <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[90] animate-fade-in" onClick={() => setContextOpen(false)}></div>
          <ContextPanel metadata={data ? data.metadata : null} isOpen={isContextOpen} onClose={() => setContextOpen(false)} isLoading={loadingState === LoadingState.LOADING} />
        </>
      )}
      <TheologyTutor topic={tutorTopic} isOpen={isReaderTutorOpen} onClose={() => setIsReaderTutorOpen(false)} />
    </div>
  );
}

export default App;

