        <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-stone-100 flex items-center gap-4">
          <div className="w-16 h-16 bg-bible-gold/10 rounded-full flex items-center justify-center text-3xl">⭐</div>
          <div>
