          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-64 h-64"><path strokeLinecap="round" strokeLinejoin="round" d="M11.48 3.499a.562.562 0 011.04 0l2.125 5.111a.563.563 0 00.475.345l5.518.442c.499.04.701.663.321.988l-4.204 3.602a.563.563 0 00-.182.557l1.285 5.385a.562.562 0 01-.84.61l-4.725-2.885a.563.563 0 00-.586 0L6.982 20.54a.562.562 0 01-.84-.61l1.285-5.386a.562.562 0 00-.182-.557l-4.204-3.602a.562.562 0 01.321-.988l5.518-.442a.563.563 0 00.475-.345L11.48 3.5z" /></svg>
        </div>

        <div className="relative z-10">
          <div className="flex justify-between items-center mb-10">
            <div>
              <h2 className="text-[10px] font-bold text-bible-accent uppercase tracking-[0.4em] mb-2">Lectura del Día {dayNumber}</h2>
              <h3 className="text-4xl font-display font-bold text-bible-ink">Génesis 1-3</h3>
            </div>
            <div className="text-right">
              <span className="text-xs font-bold text-stone-400 uppercase tracking-widest block mb-1">Tu Plan</span>
              <span className="text-bible-leather font-bold">{goals.find(g => g.id === stats.currentPlanId)?.label}</span>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row gap-4 mb-10">
            <button 
              onClick={() => onNavigateToBible('Génesis', 1)}
              className="flex-1 py-5 bg-stone-100 text-bible-leather rounded-full font-bold text-xs uppercase tracking-[0.2em] hover:bg-stone-200 transition-all flex items-center justify-center gap-2"
            >
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" /></svg>
              Comenzar Lectura
            </button>
            <button 
              onClick={completeToday}
              disabled={isDoneToday}
              className={`flex-1 py-5 rounded-full font-bold text-xs uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-2 shadow-lg ${isDoneToday ? 'bg-green-100 text-green-600' : 'bg-bible-leather text-white hover:bg-bible-ink hover:scale-105'}`}
            >
              {isDoneToday ? (
                <>
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={3} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" /></svg>
                  Día Completado
                </>
              ) : (
                'Marcar como Hecho'
              )}
            </button>
          </div>

          <div className="flex items-center gap-4 text-xs font-bold text-stone-400 uppercase tracking-widest">
            <div className="flex-1 h-2 bg-stone-100 rounded-full overflow-hidden">
              <div className="h-full bg-bible-gold transition-all duration-1000" style={{ width: `${(stats.completedDays.length / (goals.find(g => g.id === stats.currentPlanId)?.days || 365)) * 100}%` }}></div>
            </div>
            <span>{stats.completedDays.length} / {goals.find(g => g.id === stats.currentPlanId)?.days} Días</span>
          </div>
        </div>
      </div>

      {/* Badges Gallery */}
      <div className="px-2">
        <h4 className="text-sm font-bold text-stone-400 uppercase tracking-[0.3em] mb-6">Tus Logros</h4>
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          {ALL_BADGES.map((badge) => {
            const unlocked = stats.unlockedBadges.includes(badge.id);
            return (
              <div key={badge.id} className={`p-6 rounded-[2rem] text-center transition-all ${unlocked ? 'bg-white border border-bible-gold/20 shadow-sm' : 'bg-stone-100/50 opacity-40 grayscale'}`}>
                <span className="text-4xl mb-4 block">{badge.icon}</span>
                <span className="text-[10px] font-bold text-bible-ink uppercase tracking-tight block leading-tight">{badge.name}</span>
                <p className="text-[9px] text-stone-400 mt-2 line-clamp-2 leading-tight">{badge.description}</p>
              </div>
            );
          })}
        </div>
      </div>

      <div className="flex justify-center pt-8">
        <button onClick={handleRestart} className="text-[10px] font-bold text-red-400 hover:text-red-600 transition-colors uppercase tracking-widest">Cancelar Plan Actual</button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { ContextPanel } from './components/ContextPanel';
import { NoteEditor } from './components/NoteEditor';
import { ChapterExplanation } from './components/ChapterExplanation';
import { HighlightableVerse } from './components/HighlightableVerse';
import { TextAudioPlayer } from './components/TextAudioPlayer';
import { MoodSelector } from './components/MoodSelector';
import { SavedContent } from './components/SavedContent';
import { StudyMode } from './components/StudyMode';
import { ShareableImage } from './components/ShareableImage';
import { ReadingGoalSelector } from './components/ReadingGoalSelector';
import { TheologyTutor } from './components/TheologyTutor';
import { getBibleChapter, getDailyDevotional, getVersesByMood, searchBible } from './services/geminiService';
import { ChapterResponse, LoadingState, ReadingPlanItem, SearchResult, DailyDevotional, Highlight, MoodResult, UserStats } from './types';
import { BIBLE_BOOKS, CATEGORY_LABELS } from './constants';

const getNoteKey = (book: string, chapter: number, verse: number) => `note-${book}-${chapter}-${verse}`;
const getHighlightKey = (book: string, chapter: number, verse: number) => `highlights-v2-${book}-${chapter}-${verse}`;

function App() {
  const [currentBook, setCurrentBook] = useState<string>('');
  const [currentChapter, setCurrentChapter] = useState<number>(1);
  const [data, setData] = useState<ChapterResponse | null>(null);
  const [loadingState, setLoadingState] = useState<LoadingState>(LoadingState.IDLE);
  const [isContextOpen, setContextOpen] = useState(false);
  const [viewMode, setViewMode] = useState<'home' | 'reader' | 'plan' | 'search' | 'devotional' | 'mood' | 'saved' | 'study'>('home');
  const [devotional, setDevotional] = useState<DailyDevotional | null>(null);
  const [loadingDevotional, setLoadingDevotional] = useState(false);
  const [moodResults, setMoodResults] = useState<MoodResult[]>([]);
  const [loadingMood, setLoadingMood] = useState(false);
  const [selectedMood, setSelectedMood] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [userNotes, setUserNotes] = useState<Record<string, string>>({});
  const [verseHighlights, setVerseHighlights] = useState<Record<string, Highlight[]>>({});
  const [fontSize, setFontSize] = useState<number>(18); 
  const [lineHeight, setLineHeight] = useState<number>(1.625); 
  const [isReaderTutorOpen, setIsReaderTutorOpen] = useState(false);
  const [tutorTopic, setTutorTopic] = useState<string>('');
  const [audioActiveVerse, setAudioActiveVerse] = useState<number | null>(null);
  const [globalAudioCharIndex, setGlobalAudioCharIndex] = useState<number>(0);
  const [userStats, setUserStats] = useState<UserStats | null>(null);
  const [bibleBrowserView, setBibleBrowserView] = useState<'books' | 'chapters'>('books');

  const verseOffsets = useMemo(() => {
    if (!data) return [];
    let currentOffset = 0;
    return data.verses.map(v => {
        const start = currentOffset;
        const length = v.text.length;
        currentOffset += length + 1; // space
        return { verse: v.number, start, end: start + length };
    });
  }, [data]);

  const handleAudioProgress = (charIndex: number) => {
     setGlobalAudioCharIndex(charIndex); 
     if (!verseOffsets.length) return;
     const match = verseOffsets.find(v => charIndex >= v.start && charIndex <= v.end);
     if (match && match.verse !== audioActiveVerse) {
        setAudioActiveVerse(match.verse);
        const el = document.getElementById(`verse-${match.verse}`);
        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
     }
  };

  useEffect(() => {
    const loadedNotes: Record<string, string> = {};
    const loadedHighlights: Record<string, Highlight[]> = {};
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key) {
        if (key.startsWith('note-')) loadedNotes[key] = localStorage.getItem(key) || '';
        else if (key.startsWith('highlights-v2-')) {
          try { loadedHighlights[key] = JSON.parse(localStorage.getItem(key) || '[]'); } catch (e) {}
        }
      }
    }
    setUserNotes(loadedNotes);
    setVerseHighlights(loadedHighlights);

    const savedStats = localStorage.getItem('abba_bible_stats');
    if (savedStats) setUserStats(JSON.parse(savedStats));
  }, []);

  const fetchChapter = async (book: string, chapter: number) => {
    setLoadingState(LoadingState.LOADING);
    setData(null);
    setAudioActiveVerse(null);
    setGlobalAudioCharIndex(0);
    setContextOpen(false); 
    try {
      const result = await getBibleChapter(book, chapter);
      setData(result);
      setLoadingState(LoadingState.SUCCESS);
      setTutorTopic(`${result.metadata.book_name} Capítulo ${result.metadata.chapter_number}`);
    } catch (error) {
      setLoadingState(LoadingState.ERROR);
    }
  };

  const handleSelectBook = (book: string) => { 
    setCurrentBook(book); 
    setBibleBrowserView('chapters');
  };

  const handleSelectChapter = (chapter: number) => {
    setCurrentChapter(chapter);
    fetchChapter(currentBook, chapter);
    setViewMode('reader');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleGoHome = () => {
    setData(null); setLoadingState(LoadingState.IDLE); setViewMode('home');
    setCurrentBook(''); setCurrentChapter(1); setSearchQuery('');
    setBibleBrowserView('books');
    setContextOpen(false);
  };

  const handleNavigate = (mode: 'reader' | 'plan' | 'devotional' | 'mood' | 'saved' | 'study') => {
    if (mode === 'reader') { 
      setViewMode('reader');
      if (!data) setBibleBrowserView('books');
    }
    else if (mode === 'plan') setViewMode('plan');
    else if (mode === 'devotional') loadDevotional();
    else if (mode === 'mood') setViewMode('mood');
    else if (mode === 'saved') setViewMode('saved');
    else if (mode === 'study') setViewMode('study');
  };

  const loadDevotional = async () => {
    setViewMode('devotional');
    if (!devotional) {
      setLoadingDevotional(true);
      try { const result = await getDailyDevotional(); setDevotional(result); } catch (e) {} finally { setLoadingDevotional(false); }
    }
  };

  const handleSearch = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!searchQuery.trim()) return;
    setViewMode('search'); setIsSearching(true); setSearchResults([]);
    try { const results = await searchBible(searchQuery); setSearchResults(results); } catch (error) {} finally { setIsSearching(false); }
  };

  const activeBookData = BIBLE_BOOKS.find(b => b.name === currentBook);

  return (
    <div className="flex h-screen bg-stone-100 overflow-hidden font-sans">
      <div className="flex-1 flex flex-col h-full overflow-hidden relative">
        <header className="bg-white border-b border-stone-200 p-4 flex items-center justify-between shadow-sm z-30">
          <div className="flex items-center gap-2">
            {viewMode !== 'home' && (
              <button onClick={handleGoHome} className="p-2 text-bible-leather flex items-center gap-2 bg-stone-100 rounded-full pr-4 hover:bg-stone-200 transition-colors">
                 <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg>
                 <span className="text-xs font-bold uppercase tracking-widest text-bible-ink">Inicio</span>
              </button>
            )}
            {viewMode === 'home' && userStats && (
              <div className="flex items-center gap-2 px-2">
                <span className="text-xl">🔥</span>
                <span className="text-sm font-bold text-orange-600">{userStats.streak} días</span>
              </div>
            )}
          </div>

          <form onSubmit={handleSearch} className="flex-1 max-w-md mx-4 hidden md:block">
              <div className="relative">
                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="Buscar en las Escrituras..." className="w-full bg-stone-100 border-none rounded-full py-2 px-10 text-sm focus:ring-2 focus:ring-bible-gold outline-none" />
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-4 h-4 absolute left-3.5 top-2.5 text-stone-400"><path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" /></svg>
              </div>
          </form>

          <div className="flex items-center gap-2">
            {viewMode === 'reader' && data && (
               <div className="flex items-center bg-stone-100 rounded-full p-1 gap-1">
                  <button onClick={() => setContextOpen(!isContextOpen)} className={`p-2 rounded-full transition-all ${isContextOpen ? 'bg-bible-gold text-white shadow-md' : 'text-stone-400 hover:text-bible-gold'}`} title="Contexto"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M12 18v-5.25m0 0a6.001 6.001 0 00-5.304-7.618 6.002 6.002 0 019.957 5.304c.42 2.15-1.65 4.314-4.653 2.314zm0 0l-7.05 4.633a1.125 1.125 0 01-1.373-1.634l-.75-7.5M12 18l7.05 4.633a1.125 1.125 0 001.373-1.634l-.75-7.5" /></svg></button>
                  <button onClick={() => { setData(null); setBibleBrowserView('books'); setLoadingState(LoadingState.IDLE); }} className="p-2 text-stone-400 hover:text-bible-leather" title="Índice"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" /></svg></button>
               </div>
            )}
          </div>
        </header>

        <div id="bible-content-area" className="flex-1 overflow-y-auto bg-bible-paper p-4 lg:p-10 relative scroll-smooth">

          {loadingState === LoadingState.ERROR && (
             <div className="flex flex-col items-center justify-center py-20 text-center animate-fade-in px-4">
                <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mb-6">
                   <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-10 h-10"><path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m9-.75a9 9 0 11-18 0 9 9 0 0118 0zm-9 3.75h.008v.008H12v-.008z" /></svg>
                </div>
                <h2 className="text-2xl font-bold text-bible-ink mb-2">Error al cargar las Escrituras</h2>
                <button onClick={() => fetchChapter(currentBook, currentChapter)} className="px-8 py-3 bg-bible-leather text-white rounded-full font-bold shadow-lg">Reintentar</button>
             </div>
          )}

          {viewMode === 'home' && (
             <div className="max-w-6xl mx-auto py-4 animate-fade-in">
                <div className="text-center mb-12">
                   <div className="w-20 h-20 bg-bible-leather rounded-full flex items-center justify-center mx-auto mb-6 shadow-xl border-2 border-bible-gold/20">
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1} stroke="currentColor" className="w-12 h-12 text-bible-gold">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18-3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25" />
                      </svg>
                   </div>
                   <h1 className="text-4xl md:text-5xl font-display font-bold text-bible-ink mb-2 tracking-tighter uppercase">ABBA BIBLIA</h1>
                   {userStats && (
                     <div className="text-center mb-8">
                        <span className="text-bible-leather font-bold text-xs uppercase tracking-widest px-4 py-2 bg-bible-gold/10 rounded-full">{userStats.rank}</span>
                     </div>
                   )}
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 px-4">
                   {[
                      { mode: 'reader', label: 'Explorar Biblia', sub: 'Lectura y Contexto', icon: '📖', color: 'from-amber-50 to-orange-50' },
                      { mode: 'devotional', label: 'Devocional', sub: 'Palabra del Día', icon: '🙏', color: 'from-emerald-50 to-teal-50' },
                      { mode: 'plan', label: 'Rutas de Lectura', sub: 'Reto Diario', icon: '📅', color: 'from-blue-50 to-indigo-50' },
                      { mode: 'study', label: 'Academia Bíblica', sub: 'Cursos y Quizzes', icon: '🎓', color: 'from-purple-50 to-fuchsia-50' },
                      { mode: 'mood', label: 'Guía Espiritual', sub: 'Según tu Sentir', icon: '❤️', color: 'from-rose-50 to-red-50' },
                      { mode: 'saved', label: 'Mis Tesoros', sub: 'Notas y Marcas', icon: '🔖', color: 'from-stone-100 to-stone-200' },
                   ].map((item: any) => (
                      <button key={item.mode} onClick={() => handleNavigate(item.mode)} className={`bg-gradient-to-br ${item.color} p-8 rounded-[2.5rem] shadow-sm border border-black/5 hover:shadow-2xl hover:-translate-y-1 transition-all flex flex-col items-center text-center group h-full`}>
                         <span className="text-5xl mb-5 block">{item.icon}</span>
                         <h3 className="text-xl font-display font-bold text-bible-ink mb-1">{item.label}</h3>
                         <p className="text-stone-500 text-[10px] font-bold uppercase tracking-widest opacity-60">{item.sub}</p>
                      </button>
                   ))}
                </div>
             </div>
          )}

          {viewMode === 'reader' && loadingState !== LoadingState.ERROR && (
            <div className="max-w-4xl mx-auto">
              {!data && loadingState !== LoadingState.LOADING && (
                 <div className="animate-fade-in py-4">
                    {bibleBrowserView === 'books' ? (
                       <div className="space-y-12">
                          {Object.entries(CATEGORY_LABELS).map(([catId, label]) => {
                             const booksInCategory = BIBLE_BOOKS.filter(b => b.category === catId);
                             if (booksInCategory.length === 0) return null;
                             return (
                                <div key={catId} className="px-4">
                                   <h3 className="text-[10px] font-bold text-bible-accent uppercase tracking-[0.4em] mb-6 pl-4 border-l-4 border-bible-gold">{label}</h3>
                                   <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                                      {booksInCategory.map(book => (
                                         <button key={book.name} onClick={() => handleSelectBook(book.name)} className="p-6 bg-white border border-stone-100 rounded-3xl text-left hover:border-bible-gold hover:shadow-xl transition-all group relative overflow-hidden">
                                            <span className="block text-stone-800 font-bold group-hover:text-bible-leather transition-colors relative z-10">{book.name}</span>
                                            <span className="text-[10px] text-stone-400 font-bold uppercase tracking-widest relative z-10">{book.chapters} caps</span>
                                         </button>
                                      ))}
                                   </div>
                                </div>
                             )
                          })}
                       </div>
                    ) : (
                       <div className="animate-fade-in text-center py-10 px-4">
                          <span className="text-bible-accent text-xs font-bold uppercase tracking-[0.5em] mb-4 block">Libro de</span>
                          <h2 className="text-6xl font-display font-bold text-bible-ink mb-12">{activeBookData?.name}</h2>
                          <div className="grid grid-cols-4 sm:grid-cols-6 md:grid-cols-8 lg:grid-cols-10 gap-4">
                             {Array.from({ length: activeBookData?.chapters || 0 }, (_, i) => i + 1).map(chap => (
                                <button key={chap} onClick={() => handleSelectChapter(chap)} className="aspect-square flex items-center justify-center text-lg font-bold rounded-2xl bg-white border border-stone-200 text-stone-600 hover:bg-bible-leather hover:text-white transition-all transform hover:-translate-y-1">{chap}</button>
                             ))}
                          </div>
                       </div>
                    )}
                 </div>
              )}

              {loadingState === LoadingState.LOADING && ( <div className="space-y-8 animate-pulse pt-20 px-4"><div className="h-16 bg-stone-200 rounded-3xl w-1/3 mx-auto"></div><div className="space-y-4 mt-16"><div className="h-4 bg-stone-200 rounded-full w-full"></div><div className="h-4 bg-stone-200 rounded-full w-5/6"></div></div></div> )}

              {loadingState === LoadingState.SUCCESS && data && (
                <div className="animate-fade-in pb-32 relative px-4">
                  <div className="text-center mb-10">
                    <span className="text-bible-accent uppercase tracking-[0.5em] text-[10px] font-bold mb-4 block">Capítulo {data.metadata.chapter_number}</span>
                    <h1 className="text-5xl lg:text-7xl font-display font-bold text-bible-ink leading-tight">{data.metadata.book_name}</h1>
                  </div>
                  <div className="mb-10 max-w-xl mx-auto sticky top-4 z-20 shadow-2xl rounded-[2.5rem] overflow-hidden bg-white/95 backdrop-blur-md border border-stone-200 p-1 flex items-center gap-4 pr-6">
                    <div className="flex-1"><TextAudioPlayer text={data.verses.map(v => v.text).join(' ')} title="Voz de la Palabra" className="border-none" showText={false} onBoundary={handleAudioProgress} /></div>
                    <div className="flex gap-2">
                       <button onClick={() => setFontSize(s => Math.max(14, s - 2))} className="w-8 h-8 flex items-center justify-center bg-stone-100 rounded-full hover:bg-stone-200 text-xs font-serif">A-</button>
                       <button onClick={() => setFontSize(s => Math.min(32, s + 2))} className="w-8 h-8 flex items-center justify-center bg-stone-100 rounded-full hover:bg-stone-200 text-lg font-serif">A+</button>
                    </div>
                  </div>
                  <div className="space-y-10">
                    {data.verses.map((verse) => {
                      const isAudioActive = audioActiveVerse === verse.number;
                      let localIndex = null;
                      if (isAudioActive) {
                        const offsetData = verseOffsets.find(v => v.verse === verse.number);
                        if (offsetData) {
                          localIndex = globalAudioCharIndex - offsetData.start;
                        }
                      }
                      return (
                        <div id={`verse-${verse.number}`} key={verse.number} className={`relative transition-all duration-700 rounded-[2rem] p-6 -mx-6 ${isAudioActive ? 'bg-bible-gold/10 border-l-8 border-bible-gold shadow-md' : 'border-l-8 border-transparent'}`} data-verse-number={verse.number}>
                          <div className="absolute -left-12 top-6 hidden lg:block"><span className={`text-[10px] font-bold transition-all ${isAudioActive ? 'text-bible-gold scale-150' : 'text-bible-gold/30'}`}>{verse.number}</span></div>
                          <HighlightableVerse text={verse.text} highlights={[]} fontSize={fontSize} lineHeight={lineHeight} activeCharIndex={localIndex} />
                        </div>
                      );
                    })}
                  </div>
                  <div className="mt-20 pt-12 border-t border-stone-200"><ChapterExplanation explanation={data.metadata.detailed_explanation} /></div>
                </div>
              )}
            </div>
          )}

          {viewMode === 'plan' && ( 
            <ReadingGoalSelector onNavigateToBible={(book, chapter) => {
               setCurrentBook(book);
               setCurrentChapter(chapter);
               fetchChapter(book, chapter);
               setViewMode('reader');
            }} />
          )}

          {viewMode === 'devotional' && devotional && (
             <div className="max-w-3xl mx-auto pt-8 animate-fade-in px-4">
                <div className="bg-white p-16 rounded-[4rem] shadow-2xl border-t-[14px] border-bible-gold text-center">
                   <h2 className="text-4xl lg:text-5xl font-serif text-bible-ink leading-tight mb-10 italic">"{devotional.verseText}"</h2>
                   <p className="text-bible-accent font-bold tracking-[0.5em] uppercase text-xs">{devotional.verseReference}</p>
                </div>
             </div>
          )}

          {viewMode === 'mood' && (
             <MoodSelector onSelectMood={async (m) => { setSelectedMood(m); setLoadingMood(true); try { const r = await getVersesByMood(m); setMoodResults(r); } finally { setLoadingMood(false); } }} />
          )}

          {viewMode === 'saved' && ( <SavedContent onNavigateToVerse={() => {}} onDeleteItem={() => {}} /> )}
          {viewMode === 'study' && ( <StudyMode /> )}
        </div>
      </div>

      {isContextOpen && data && (
        <>
          <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[90] animate-fade-in" onClick={() => setContextOpen(false)}></div>
          <ContextPanel metadata={data.metadata} isOpen={isContextOpen} onClose={() => setContextOpen(false)} isLoading={loadingState === LoadingState.LOADING} />
        </>
      )}
    </div>
  );
}

export default App;

export enum LoadingState {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

export interface Verse {
  number: number;
  text: string;
}

export interface ChapterMetadata {
  book_name: string;
  chapter_number: number;
  author: string;
  estimated_date: string;
  target_audience: string;
  historical_setting: string;
  theological_theme: string;
  reading_guidance: string; 
  detailed_explanation: string;
  key_quotes?: string[];
}

export interface ChapterResponse {
  metadata: ChapterMetadata;
  verses: Verse[];
}

export interface BibleBook {
  name: string;
  chapters: number;
  category: 'law' | 'history' | 'poetry' | 'prophets_major' | 'prophets_minor' | 'gospels' | 'church_history' | 'letters' | 'prophecy';
}

export interface ReadingPlanItem {
  order: number;
  book: string;
  chapters: number[];
  reason: string;
}

export interface SearchResult {
  book: string;
  chapter: number;
  verse: number;
  text: string;
  relevance: string; 
}

export interface MoodResult {
  verseReference: string;
  text: string;
  explanation: string;
}

export interface DailyDevotional {
  verseReference: string;
  verseText: string;
  reflection: string;
  prayer: string;
  application: string;
}

export interface Highlight {
  id: string;
  start: number;
  end: number;
  color: string;
  text: string;
}

export interface ReadingGoal {
  id: string;
  label: string;
  days: number;
  chaptersPerDay: number;
  description: string;
}

export interface Badge {
  id: string;
  name: string;
  icon: string;
  description: string;
}

export interface UserStats {
  points: number;
  streak: number;
  completedDays: string[]; // ISO Dates
  rank: string;
  unlockedBadges: string[]; // Badge IDs
  currentPlanId?: string;
  xpToNextLevel: number;
}

// Interface for Quiz Questions used in StudyLesson
export interface QuizQuestion {
  id: number;
  question: string;
  options: string[];
  correctAnswerIndex: number;
  explanation: string;
}

// Interface for AI-generated Bible study lessons
export interface StudyLesson {
  topic: string;
  title: string;
  content: string;
  keyVerses: string[];
  quiz: QuizQuestion[];
}

// Interface for cross-references in Bible study
export interface CrossReference {
  verse: string;
  text: string;
}
